-- ================= san_pham (16 dòng) =================
DELETE FROM `san_pham`;
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (1, 'Cơm Bò Xào Bông Cải Sốt Tiêu', 'Món Chế Biến Sẵn', 55000, 30, '1786036482174.webp', 'Thịt bò thăn mềm mọng xào cùng bông cải xanh giòn ngọt, sốt tiêu đen đậm đà kèm cơm trắng dẻo thơm nóng hổi. Phần ăn đầy đủ dinh dưỡng cho bữa trưa và bữa tối.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (2, 'Thịt Heo Kho Tàu Trứng Cút (Kèm Cơm)', 'Món Chế Biến Sẵn', 50000, 25, '1786036788088.webp', 'Thịt ba chỉ kho mềm rục với nước dừa tươi béo ngậy, trứng cút ngấm vị mặn ngọt truyền thống. Ăn kèm dưa chua giòn rụm và cơm nóng.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (3, 'Canh Chua Tôm Sú Nam Bộ (Tô Lớn)', 'Món Chế Biến Sẵn', 45000, 20, '1786037230275.webp', 'Tôm sú tươi ngọt thịt nấu cùng dứa chín, cà chua đỏ mọng, đậu bắp giòn và nước cốt me chua thanh ngọt hậu, rắc ngò gai ngò om thơm lừng.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (4, 'Cơm Sườn Xào Chua Ngọt Bắc Bộ', 'Món Chế Biến Sẵn', 55000, 30, '1786036904867.webp', 'Sườn heo non chặt vừa miếng chiên xém vàng, ngấm đẫm lớp sốt chua ngọt giấm táo sánh dẻo óng ả. Món ăn khoái khẩu cực kỳ đưa cơm.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (5, 'Gà Chiên Nước Mắm Giòn Cay', 'Món Chế Biến Sẵn', 48000, 25, '1786036842355.webp', 'Thịt gà tươi chiên vàng giòn rụm lớp da ngoài, bên trong ẩm mềm ngọt nước, đảo đều với sốt nước mắm tỏi ớt kẹo cay ngọt đậm vị.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (6, 'Mực Xào Dứa Thơm Giòn Cay', 'Món Chế Biến Sẵn', 60000, 20, '1786036920587.webp', 'Mực ống tươi khía vảy rồng xào trên lửa lớn cùng dứa chua ngọt và cần tây, giữ trọn độ giòn ngọt sần sật đặc trưng của hải sản biển.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (7, '[Meal-kit] Set Canh Chua Tôm Tươi Sơ Chế Sẵn', 'Set Nấu Ăn (Meal-kit)', 65000, 15, '1786037230275.webp', 'Khay nguyên liệu định lượng chuẩn: 300g tôm sú bóc nõn sạch rút chỉ lưng + dứa, đậu bắp, giá đỗ, ngò om và chai cốt me nêm sẵn gia vị. Tự nấu thơm ngon chỉ 10 phút.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (8, '[Meal-kit] Set Bò Tươi Ướp Sốt & Bông Cải VietGAP', 'Set Nấu Ăn (Meal-kit)', 75000, 18, '1786036482174.webp', 'Khay gồm 300g thịt thăn bò thái mỏng ướp sẵn dầu hào tỏi mè + 1 cây bông cải xanh tách nhánh sạch + cà rốt hoa. Chỉ cần xào nhanh trên chảo nóng 5 phút.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (9, '[Meal-kit] Set Thịt Ba Chỉ & Trứng Cút Kho Tàu', 'Set Nấu Ăn (Meal-kit)', 70000, 15, '1786036788088.webp', 'Gồm 400g thịt ba chỉ cắt vuông chần sạch + 15 quả trứng cút luộc bóc vỏ + gói nước dừa xiêm tự nhiên và sốt kho thắng đường chuẩn màu cánh gián.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (10, '[Meal-kit] Set Sườn Heo Ướp Sốt Chua Ngọt', 'Set Nấu Ăn (Meal-kit)', 75000, 12, '1786036904867.webp', '500g sườn sụn non sơ chế sạch chặt miếng + chai sốt chua ngọt pha chế công thức độc quyền từ nước cốt dứa và giấm gạo. Nấu tiện lợi tại nhà.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (11, '[Meal-kit] Set Đậu Hũ Nhồi Thịt Sốt Cà Chua', 'Set Nấu Ăn (Meal-kit)', 50000, 20, '1786036870851.webp', '4 bìa đậu hũ nhồi thịt nạc băm nấm mèo gia vị thơm nức + khay cà chua lột vỏ băm nhuyễn và hành lá tươi. Nấu sốt cà chua sệt trong 10 phút.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (12, 'Nước Ép Trái Cây Tự Nhiên (Chai 350ml)', 'Đồ Uống & Tráng Miệng', 35000, 40, 'nuoc_ep_trai_cay_co_thuc_su_tot-3.jpg', 'Nước ép nguyên chất ép chậm từ cam sành, cà rốt và táo đỏ hữu cơ, thanh mát, bổ sung dồi dào vitamin C giúp tăng sức đề kháng.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (13, 'Hộp Trái Cây Tươi Cắt Sẵn Theo Mùa', 'Đồ Uống & Tráng Miệng', 30000, 25, 'fruite-item-2.jpg', 'Hộp trái cây tươi gọt sẵn đóng kín gồm thanh long ruột đỏ, táo Mỹ và ổi giòn ướp lạnh, kèm hũ muối tôm Tây Ninh hảo hạng.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (14, 'Cà Chua Bi Hữu Cơ VietGAP (Hộp 500g)', 'Nông Sản & Nguyên Liệu', 25000, 50, '1786008268041.jpg', 'Cà chua bi tươi giòn, ngọt thanh, quả tròn đều chín mọng trồng theo tiêu chuẩn hữu cơ tại nông trường Đà Lạt Lâm Đồng.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (15, 'Khoai Tây Đà Lạt Tươi Sạch (Túi 1kg)', 'Nông Sản & Nguyên Liệu', 35000, 45, '1786008327361.jpg', 'Khoai tây vàng ruột dẻo thơm, không mọc mầm, giàu vitamin C và khoáng chất, thích hợp làm các món xào, súp hầm hoặc chiên giòn.');
INSERT INTO `san_pham` (`id`, `ten_san_pham`, `danh_muc`, `gia`, `so_luong_ton`, `hinh_anh`, `mo_ta`) VALUES (16, 'Bông Cải Xanh Đà Lạt (Cây 400g)', 'Nông Sản & Nguyên Liệu', 30000, 35, 'vegetable-item-6.jpg', 'Bông cải xanh (súp lơ xanh) bông to chắc, búp xanh mướt giòn ngọt tự nhiên, giàu chất xơ, vitamin K và chất chống oxy hóa.');

-- ================= mon_an (52 dòng) =================
DELETE FROM `mon_an`;
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (1, 'Trứng chiên cà chua', 'Trứng gà tươi (3 quả), Cà chua chín mọng (2 quả (~200g)), Hành tím (1 củ), Hành hoa (2 nhánh), Nước mắm truyền thống (1 muỗng canh), Hạt nêm & Tiêu xay (0.5 thìa cà phê), Dầu ăn thực vật (2 muỗng canh)', '[Bước 1: Đánh bông trứng & Khóa ẩm - ⏱️ 3 phút]
Đập 3 quả trứng gà ta vào tô thủy tinh sạch. Thêm 1 thìa cà phê nước mắm ngon, 1/2 thìa hạt nêm, 1/2 thìa cà phê tiêu xay, 1 thìa cà phê nước lọc (bí quyết giữ trứng mềm mướt không khô cứng) và một nửa lượng hành hoa thái nhỏ. Dùng đũa hoặc phới lồng đánh đều tay theo một chiều trong 1 phút đến khi hỗn hợp nổi bọt khí mịn màng.

[Bước 2: Lột vỏ & Xào sốt cà chua sánh mịn - ⏱️ 4 phút]
Khía hình chữ thập ở đuôi cà chua, chần nhanh qua nước sôi 30 giây rồi bóc sạch lớp vỏ mỏng bên ngoài, thái hạt lựu nhuyễn. Đặt chảo lên bếp, cho 1 thìa dầu ăn vào đun nóng ở lửa vừa, phi thơm hành tím băm đến khi ngả vàng nhạt. Trút toàn bộ cà chua vào xào đều tay, nêm 1/2 thìa đường và 1/2 thìa hạt nêm giúp cà chua nhanh nhừ mềm. Dùng muôi gỗ dằm nhẹ liên tục đến khi cà chua tan nhuyễn tạo thành hỗn hợp sốt đỏ au sền sệt.

[Bước 3: Kỹ thuật tráng trứng vân mây mềm mọng - ⏱️ 3 phút]
Khi sốt cà chua sôi lục bục, hạ lửa xuống mức nhỏ vừa. Từ từ rót hỗn hợp trứng đã đánh tan vào đều khắp mặt chảo. Chờ khoảng 15 - 20 giây cho lớp đáy trứng định hình se lại. Dùng muôi gỗ đẩy nhẹ nhàng từ mép ngoài viền chảo vào trung tâm để trứng dồn thành các lớp vân mềm xốp (kiểu scramble mịn), cho phần trứng lỏng còn lại tràn ra tiếp xúc với đáy chảo.

[Bước 4: Hoàn thiện & Thưởng thức nóng hổi - ⏱️ 1 phút]
Khi trứng đạt độ chín khoảng 85 - 90% (vẫn giữ được độ bóng mượt, mềm mại ẩm mọng và không bị chiên quá khô xác), rắc nốt phần hành hoa còn lại và chút tiêu sọ xay thơm nồng lên mặt. Tắt bếp ngay lập tức, đậy vung 30 giây để hơi nóng làm hành chín tái dậy mùi thơm. Múc trứng ra đĩa sâu lòng, rưới nước sốt cà chua bóng bẩy lên trên và thưởng thức cùng cơm trắng nóng.

💡 Mẹo đầu bếp: Thêm 1 thìa cà phê nước lọc khi đánh trứng và tắt bếp khi trứng còn hơi ẩm mượt (khoảng 90% độ chín) sẽ giúp món trứng xào cà chua mềm mịn tan ngay trên đầu lưỡi, không bao giờ bị bã khô.', '1786034640636.webp', 'Món mặn', 'Món ăn quốc dân nhanh gọn nhưng đậm đà tinh tế, trứng bông xốp mềm mọng quyện nước sốt cà chua đỏ tươi sánh quyện chua thanh ngọt dịu.', 'Dễ', '2 - 3 người', 5, 10, '[{"ten":"Trứng gà tươi","so_luong":3,"don_vi":"quả","ghi_chu":"chọn trứng gà ta lòng đỏ đậm"},{"ten":"Cà chua chín mọng","so_luong":2,"don_vi":"quả (~200g)","ghi_chu":"bỏ cuống, lột vỏ thái hạt lựu"},{"ten":"Hành tím","so_luong":1,"don_vi":"củ","ghi_chu":"băm nhuyễn phi thơm"},{"ten":"Hành hoa","so_luong":2,"don_vi":"nhánh","ghi_chu":"rửa sạch, thái nhỏ 0.5cm"},{"ten":"Nước mắm truyền thống","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"độ đạm 35 - 40 độ"},{"ten":"Hạt nêm & Tiêu xay","so_luong":0.5,"don_vi":"thìa cà phê","ghi_chu":"tạo vị hài hòa"},{"ten":"Dầu ăn thực vật","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"chia xào sốt và chiên trứng"}]', '[{"buoc":1,"tieu_de":"Đánh bông trứng & Khóa ẩm","thoi_gian":"3 phút","noi_dung":"Đập 3 quả trứng gà ta vào tô thủy tinh sạch. Thêm 1 thìa cà phê nước mắm ngon, 1/2 thìa hạt nêm, 1/2 thìa cà phê tiêu xay, 1 thìa cà phê nước lọc (bí quyết giữ trứng mềm mướt không khô cứng) và một nửa lượng hành hoa thái nhỏ. Dùng đũa hoặc phới lồng đánh đều tay theo một chiều trong 1 phút đến khi hỗn hợp nổi bọt khí mịn màng."},{"buoc":2,"tieu_de":"Lột vỏ & Xào sốt cà chua sánh mịn","thoi_gian":"4 phút","noi_dung":"Khía hình chữ thập ở đuôi cà chua, chần nhanh qua nước sôi 30 giây rồi bóc sạch lớp vỏ mỏng bên ngoài, thái hạt lựu nhuyễn. Đặt chảo lên bếp, cho 1 thìa dầu ăn vào đun nóng ở lửa vừa, phi thơm hành tím băm đến khi ngả vàng nhạt. Trút toàn bộ cà chua vào xào đều tay, nêm 1/2 thìa đường và 1/2 thìa hạt nêm giúp cà chua nhanh nhừ mềm. Dùng muôi gỗ dằm nhẹ liên tục đến khi cà chua tan nhuyễn tạo thành hỗn hợp sốt đỏ au sền sệt."},{"buoc":3,"tieu_de":"Kỹ thuật tráng trứng vân mây mềm mọng","thoi_gian":"3 phút","noi_dung":"Khi sốt cà chua sôi lục bục, hạ lửa xuống mức nhỏ vừa. Từ từ rót hỗn hợp trứng đã đánh tan vào đều khắp mặt chảo. Chờ khoảng 15 - 20 giây cho lớp đáy trứng định hình se lại. Dùng muôi gỗ đẩy nhẹ nhàng từ mép ngoài viền chảo vào trung tâm để trứng dồn thành các lớp vân mềm xốp (kiểu scramble mịn), cho phần trứng lỏng còn lại tràn ra tiếp xúc với đáy chảo."},{"buoc":4,"tieu_de":"Hoàn thiện & Thưởng thức nóng hổi","thoi_gian":"1 phút","noi_dung":"Khi trứng đạt độ chín khoảng 85 - 90% (vẫn giữ được độ bóng mượt, mềm mại ẩm mọng và không bị chiên quá khô xác), rắc nốt phần hành hoa còn lại và chút tiêu sọ xay thơm nồng lên mặt. Tắt bếp ngay lập tức, đậy vung 30 giây để hơi nóng làm hành chín tái dậy mùi thơm. Múc trứng ra đĩa sâu lòng, rưới nước sốt cà chua bóng bẩy lên trên và thưởng thức cùng cơm trắng nóng."}]', 'Thêm 1 thìa cà phê nước lọc khi đánh trứng và tắt bếp khi trứng còn hơi ẩm mượt (khoảng 90% độ chín) sẽ giúp món trứng xào cà chua mềm mịn tan ngay trên đầu lưỡi, không bao giờ bị bã khô.', '{"calo":240,"protein":"16g","chat_beo":"17g","carb":"6g"}', '["Nhanh gọn","Dễ làm","Bữa sáng/Tối","Thanh đạm","Giàu đạm"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (3, 'Bò xào bông cải xanh', 'Thịt thăn bò tươi (300 g), Bông cải xanh (súp lơ) (1 cây (~400g)), Cà rốt tươi (0.5 củ), Tỏi khô ta (1.5 củ), Dầu hào cao cấp (1.5 muỗng canh), Dầu mè & Tiêu đen (1 thìa cà phê)', '[Bước 1: Thái mỏng & Ướp thịt bò chuẩn vị - ⏱️ 15 phút]
Thịt bò dùng khăn giấy thấm khô, đặt dao nghiêng thái mỏng ngang thớ thịt (thái dọc thớ thịt sẽ bị dai). Cho thịt vào âu, ướp cùng 1 thìa canh dầu hào, 1/2 thìa cà phê hạt nêm, 1/2 lượng tỏi băm, 1 thìa cà phê dầu mè và 1 thìa canh dầu ăn. Trộn đều tay và để thịt nghỉ 15 phút. Dầu ăn sẽ bao bọc các thớ thịt giúp giữ trọn nước ngọt bên trong khi xào nhiệt cao.

[Bước 2: Chần sơ bông cải sốc nhiệt đá lạnh - ⏱️ 3 phút]
Đun sôi một nồi nước lớn với 1 thìa cà phê muối hạt. Khi nước sôi sùng sục, thả bông cải xanh và cà rốt tỉa hoa vào chần nhanh đúng 60 giây. Vớt ngay ra thau nước đá lạnh ngâm 2 phút để khóa màu xanh mướt diệp lục và giữ độ giòn sần sật tự nhiên, sau đó vớt ra rổ lắc ráo nước.

[Bước 3: Xào tái thịt bò trên lửa lớn (Wok Hei) - ⏱️ 2 phút]
Đặt chảo gang hoặc chảo sâu lòng lên bếp bật lửa lớn nhất đến khi chảo bốc khói nhẹ. Cho 1 thìa dầu ăn và lượng tỏi băm còn lại vào phi nhanh trong 10 giây cho dậy mùi thơm. Trút toàn bộ thịt bò vào đảo cực nhanh tay và dàn đều khắp mặt chảo trong 60 - 90 giây. Khi thịt vừa chuyển màu hồng nhạt chín tái (chín khoảng 70%), trút ngay thịt bò ra đĩa riêng (không để trong chảo làm thịt dai).

[Bước 4: Xào rau củ & Hòa quyện thành phẩm - ⏱️ 2 phút]
Tận dụng nước xào ngọt trong chảo, trút bông cải xanh và cà rốt vào đảo đều trên lửa lớn, nêm 1/2 thìa dầu hào và 1 thìa hạt nêm. Xào trong 1 phút cho rau ngấm vị. Đổ đĩa thịt bò cùng toàn bộ nước thịt ngọt trở lại chảo, đảo nhanh tay 30 giây cho hòa quyện. Rắc tiêu xay thô, đảo thêm 5 giây rồi trút ra đĩa lớn thưởng thức nóng.

💡 Mẹo đầu bếp: Bắt buộc phải xào thịt bò trên lửa lớn nhất và trút ra đĩa khi vừa chín tái. Không xào chung thịt bò với rau từ đầu vì thời gian nấu lâu sẽ làm thịt ra hết nước ngọt và dai cứng.', '1786036482174.webp', 'Món mặn', 'Thịt thăn bò mềm mọng ngấm đậm gia vị tỏi dầu hào kết hợp với bông cải xanh giòn sần sật ngọt lành, món xào bổ dưỡng giàu chất xơ và sắt.', 'Dễ', '3 - 4 người', 15, 10, '[{"ten":"Thịt thăn bò tươi","so_luong":300,"don_vi":"g","ghi_chu":"thái lát mỏng ngang thớ bản rộng"},{"ten":"Bông cải xanh (súp lơ)","so_luong":1,"don_vi":"cây (~400g)","ghi_chu":"tách nhánh vừa ăn, ngâm nước muối"},{"ten":"Cà rốt tươi","so_luong":0.5,"don_vi":"củ","ghi_chu":"tỉa hoa thái lát mỏng 2mm"},{"ten":"Tỏi khô ta","so_luong":1.5,"don_vi":"củ","ghi_chu":"băm nhỏ, chia làm 2 phần"},{"ten":"Dầu hào cao cấp","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo màu bóng và vị ngọt thịt"},{"ten":"Dầu mè & Tiêu đen","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"tạo hương thơm quyến rũ"}]', '[{"buoc":1,"tieu_de":"Thái mỏng & Ướp thịt bò chuẩn vị","thoi_gian":"15 phút","noi_dung":"Thịt bò dùng khăn giấy thấm khô, đặt dao nghiêng thái mỏng ngang thớ thịt (thái dọc thớ thịt sẽ bị dai). Cho thịt vào âu, ướp cùng 1 thìa canh dầu hào, 1/2 thìa cà phê hạt nêm, 1/2 lượng tỏi băm, 1 thìa cà phê dầu mè và 1 thìa canh dầu ăn. Trộn đều tay và để thịt nghỉ 15 phút. Dầu ăn sẽ bao bọc các thớ thịt giúp giữ trọn nước ngọt bên trong khi xào nhiệt cao."},{"buoc":2,"tieu_de":"Chần sơ bông cải sốc nhiệt đá lạnh","thoi_gian":"3 phút","noi_dung":"Đun sôi một nồi nước lớn với 1 thìa cà phê muối hạt. Khi nước sôi sùng sục, thả bông cải xanh và cà rốt tỉa hoa vào chần nhanh đúng 60 giây. Vớt ngay ra thau nước đá lạnh ngâm 2 phút để khóa màu xanh mướt diệp lục và giữ độ giòn sần sật tự nhiên, sau đó vớt ra rổ lắc ráo nước."},{"buoc":3,"tieu_de":"Xào tái thịt bò trên lửa lớn (Wok Hei)","thoi_gian":"2 phút","noi_dung":"Đặt chảo gang hoặc chảo sâu lòng lên bếp bật lửa lớn nhất đến khi chảo bốc khói nhẹ. Cho 1 thìa dầu ăn và lượng tỏi băm còn lại vào phi nhanh trong 10 giây cho dậy mùi thơm. Trút toàn bộ thịt bò vào đảo cực nhanh tay và dàn đều khắp mặt chảo trong 60 - 90 giây. Khi thịt vừa chuyển màu hồng nhạt chín tái (chín khoảng 70%), trút ngay thịt bò ra đĩa riêng (không để trong chảo làm thịt dai)."},{"buoc":4,"tieu_de":"Xào rau củ & Hòa quyện thành phẩm","thoi_gian":"2 phút","noi_dung":"Tận dụng nước xào ngọt trong chảo, trút bông cải xanh và cà rốt vào đảo đều trên lửa lớn, nêm 1/2 thìa dầu hào và 1 thìa hạt nêm. Xào trong 1 phút cho rau ngấm vị. Đổ đĩa thịt bò cùng toàn bộ nước thịt ngọt trở lại chảo, đảo nhanh tay 30 giây cho hòa quyện. Rắc tiêu xay thô, đảo thêm 5 giây rồi trút ra đĩa lớn thưởng thức nóng."}]', 'Bắt buộc phải xào thịt bò trên lửa lớn nhất và trút ra đĩa khi vừa chín tái. Không xào chung thịt bò với rau từ đầu vì thời gian nấu lâu sẽ làm thịt ra hết nước ngọt và dai cứng.', '{"calo":310,"protein":"32g","chat_beo":"12g","carb":"14g"}', '["Giàu dinh dưỡng","Eat Clean","Bổ máu","Món xào ngon","Bữa cơm gia đình"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (4, 'Thịt heo kho tàu', 'Thịt ba chỉ rút sườn (500 g), Trứng cút tươi (15 quả), Nước dừa xiêm tươi (450 ml), Hành tím & Tỏi củ (4 củ), Nước mắm nhĩ ngon (3 muỗng canh), Đường phèn hoặc đường thốt nốt (1.5 muỗng canh), Ớt sừng & Tiêu sọ (1 set)', '[Bước 1: Khử mùi & Cắt khối chuẩn quy cách - ⏱️ 10 phút]
Thịt ba chỉ rửa với nước muối loãng, cạo sạch bì. Đun sôi nồi nước có vài lát gừng và 1 thìa giấm, chần thịt trong 3 phút để đẩy hết bọt bẩn và máu đọng ra ngoài. Vớt ra rửa sạch dưới vòi nước lạnh, để ráo rồi dùng dao sắc cắt khối vuông vức kích thước 3.5 x 3.5cm.

[Bước 2: Ướp thịt đượm vị & Thắng nước hàng cánh gián - ⏱️ 30 phút]
Ướp thịt với 2.5 muỗng nước mắm nhĩ, 1 thìa đường, nước cốt hành tỏi băm (vắt lấy nước giúp kho không bị cháy cặn đáy nồi), 1/2 thìa tiêu sọ và 1 quả ớt đập dập trong 30 phút. Đặt nồi kho lên bếp, cho 1.5 thìa đường phèn cùng 1 thìa dầu ăn, đun lửa nhỏ đến khi đường tan chảy sủi bọt khí li ti chuyển sang màu nâu cánh gián thì cho 2 thìa nước nóng vào hãm màu.

[Bước 3: Xào săn thớ thịt & Ninh với nước dừa tươi - ⏱️ 35 phút]
Trút toàn bộ thịt đã ướp vào nồi nước màu, bật lửa vừa đảo liên tục trong 5 - 7 phút cho từng miếng thịt săn chắc lại, lớp mỡ chuyển trong veo và áo đều màu nâu bóng óng ả. Đổ 450ml nước dừa xiêm tươi vào ngập mặt thịt. Đun lửa lớn cho sôi bùng lên, dùng muôi hớt sạch toàn bộ bọt màng nổi trên mặt nước.

[Bước 4: Kho liu riu mở nắp & Thấm vị trứng cút - ⏱️ 15 phút]
Hạ lửa thật nhỏ liu riu, kho mở hé nắp vung trong 30 phút để nước kho trong veo và thịt mềm rục. Cho tiếp 15 quả trứng cút luộc vào nồi, nêm nếm lại thêm chút nước mắm cho vị mặn ngọt đậm đà cân bằng. Tiếp tục kho thêm 15 phút đến khi nước kho cạn bớt keo sánh sền sệt ôm lấy miếng thịt trong suốt bóng mượt thì tắt bếp.

💡 Mẹo đầu bếp: Khi kho thịt với nước dừa tươi, tuyệt đối không đậy kín nắp vung nồi; kho mở nắp ở lửa nhỏ liu riu sẽ giúp nước kho trong vắt không bị đục và lớp mỡ thịt trở nên trong suốt như thạch.', '1786036788088.webp', 'Món mặn', 'Món thịt kho tàu truyền thống với những miếng ba chỉ vuông vắn mềm rục tan trong miệng, trứng cút ngấm đượm nước dừa tươi ngọt thanh thơm phức.', 'Trung bình', '4 người', 20, 50, '[{"ten":"Thịt ba chỉ rút sườn","so_luong":500,"don_vi":"g","ghi_chu":"nạc mỡ đan xen liền khối, thái khối vuông 3.5cm"},{"ten":"Trứng cút tươi","so_luong":15,"don_vi":"quả","ghi_chu":"luộc chín bóc sạch vỏ"},{"ten":"Nước dừa xiêm tươi","so_luong":450,"don_vi":"ml","ghi_chu":"nước dừa ngọt thanh tự nhiên"},{"ten":"Hành tím & Tỏi củ","so_luong":4,"don_vi":"củ","ghi_chu":"giã nhuyễn vắt lấy nước cốt ướp"},{"ten":"Nước mắm nhĩ ngon","so_luong":3,"don_vi":"muỗng canh","ghi_chu":"nước mắm cốt truyền thống"},{"ten":"Đường phèn hoặc đường thốt nốt","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"thắng nước màu hổ phách"},{"ten":"Ớt sừng & Tiêu sọ","so_luong":1,"don_vi":"set","ghi_chu":"tạo vị ấm nồng"}]', '[{"buoc":1,"tieu_de":"Khử mùi & Cắt khối chuẩn quy cách","thoi_gian":"10 phút","noi_dung":"Thịt ba chỉ rửa với nước muối loãng, cạo sạch bì. Đun sôi nồi nước có vài lát gừng và 1 thìa giấm, chần thịt trong 3 phút để đẩy hết bọt bẩn và máu đọng ra ngoài. Vớt ra rửa sạch dưới vòi nước lạnh, để ráo rồi dùng dao sắc cắt khối vuông vức kích thước 3.5 x 3.5cm."},{"buoc":2,"tieu_de":"Ướp thịt đượm vị & Thắng nước hàng cánh gián","thoi_gian":"30 phút","noi_dung":"Ướp thịt với 2.5 muỗng nước mắm nhĩ, 1 thìa đường, nước cốt hành tỏi băm (vắt lấy nước giúp kho không bị cháy cặn đáy nồi), 1/2 thìa tiêu sọ và 1 quả ớt đập dập trong 30 phút. Đặt nồi kho lên bếp, cho 1.5 thìa đường phèn cùng 1 thìa dầu ăn, đun lửa nhỏ đến khi đường tan chảy sủi bọt khí li ti chuyển sang màu nâu cánh gián thì cho 2 thìa nước nóng vào hãm màu."},{"buoc":3,"tieu_de":"Xào săn thớ thịt & Ninh với nước dừa tươi","thoi_gian":"35 phút","noi_dung":"Trút toàn bộ thịt đã ướp vào nồi nước màu, bật lửa vừa đảo liên tục trong 5 - 7 phút cho từng miếng thịt săn chắc lại, lớp mỡ chuyển trong veo và áo đều màu nâu bóng óng ả. Đổ 450ml nước dừa xiêm tươi vào ngập mặt thịt. Đun lửa lớn cho sôi bùng lên, dùng muôi hớt sạch toàn bộ bọt màng nổi trên mặt nước."},{"buoc":4,"tieu_de":"Kho liu riu mở nắp & Thấm vị trứng cút","thoi_gian":"15 phút","noi_dung":"Hạ lửa thật nhỏ liu riu, kho mở hé nắp vung trong 30 phút để nước kho trong veo và thịt mềm rục. Cho tiếp 15 quả trứng cút luộc vào nồi, nêm nếm lại thêm chút nước mắm cho vị mặn ngọt đậm đà cân bằng. Tiếp tục kho thêm 15 phút đến khi nước kho cạn bớt keo sánh sền sệt ôm lấy miếng thịt trong suốt bóng mượt thì tắt bếp."}]', 'Khi kho thịt với nước dừa tươi, tuyệt đối không đậy kín nắp vung nồi; kho mở nắp ở lửa nhỏ liu riu sẽ giúp nước kho trong vắt không bị đục và lớp mỡ thịt trở nên trong suốt như thạch.', '{"calo":480,"protein":"30g","chat_beo":"36g","carb":"7g"}', '["Món truyền thống","Đậm đà","Món Tết","Đưa cơm","Gia đình"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (5, 'Thịt ba chỉ rang cháy cạnh', 'Thịt ba chỉ tươi (400 g), Hành tím khô (3 củ), Hành hoa tươi (3 nhánh), Nước mắm nguyên chất (2 muỗng canh), Đường vàng hoa mai (1.5 muỗng canh), Tiêu xay & Ớt hiểm (1 thìa cà phê)', '[Bước 1: Sơ chế & Thái lát mỏng chuẩn lửa - ⏱️ 5 phút]
Thịt ba chỉ rửa sạch với muối hạt, thấm thật khô bề mặt. Dùng dao sắc thái thịt thành các lát mỏng đều tay khoảng 2 - 3mm (không thái quá dày thịt lâu xém cạnh, không thái quá mỏng thịt sẽ bị vụn khô xác).

[Bước 2: Đảo kiệt mỡ & Tạo viền cháy cạnh vàng giòn - ⏱️ 7 phút]
Đặt chảo chống dính sâu lòng lên bếp không cho dầu ăn. Khi chảo nóng, trút thịt ba chỉ vào đảo đều tay trên lửa vừa. Thịt sẽ tự tiết mỡ ra xèo xèo. Đảo liên tục trong 6 - 8 phút đến khi các cạnh miếng thịt xém vàng ươm, bề mặt se giòn rụm. Nghiêng chảo chắt bớt toàn bộ mỡ thừa ra chén (chỉ giữ lại khoảng 1 thìa nhỏ mỡ trong chảo để tránh bị ngấy).

[Bước 3: Phi thơm hành & Nấu sốt rim mắm đường - ⏱️ 3 phút]
Gạt thịt sang một bên chảo, cho hành tím thái lát vào phần mỡ còn lại phi nhanh trong 20 giây cho dậy mùi thơm nức. Pha chén sốt gồm: 2 muỗng nước mắm, 1.5 muỗng đường vàng, 1/2 thìa tiêu, ớt thái lát và 2 muỗng nước lọc khuấy tan hoàn toàn. Rưới toàn bộ chén sốt đều vào chảo thịt.

[Bước 4: Rim kẹo bóng bẩy & Hoàn thiện - ⏱️ 2 phút]
Tăng lửa lên mức vừa, đảo đều tay liên tục để nước sốt mắm đường sôi sủi bọt keo lại, bao phủ một lớp caramel mặn ngọt bóng bẩy quanh từng miếng thịt vàng rộm. Thả toàn bộ hành hoa cắt khúc vào đảo nhanh tay trong 15 giây rồi tắt bếp ngay. Múc ra đĩa sâu lòng ăn cùng cơm trắng nóng hổi.

💡 Mẹo đầu bếp: Bắt buộc phải chắt bỏ phần mỡ thừa tiết ra sau khi đảo xém cạnh rồi mới rưới nước mắm đường vào rim; làm như vậy miếng thịt sẽ giòn dai đậm đà mà không hề bị ngấy dầu mỡ.', '1786036806028.webp', 'Món mặn', 'Thịt ba chỉ thái mỏng đảo cháy cạnh vàng giòn thơm nức mũi, quyện lớp sốt nước mắm đường cay the mặn ngọt bóng bẩy cực kỳ bắt cơm.', 'Dễ', '3 - 4 người', 10, 15, '[{"ten":"Thịt ba chỉ tươi","so_luong":400,"don_vi":"g","ghi_chu":"nạc mỡ cân đối, thái lát mỏng 2 - 3mm"},{"ten":"Hành tím khô","so_luong":3,"don_vi":"củ","ghi_chu":"thái lát mỏng"},{"ten":"Hành hoa tươi","so_luong":3,"don_vi":"nhánh","ghi_chu":"cắt khúc 2.5cm"},{"ten":"Nước mắm nguyên chất","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"độ mặn ngọt chuẩn vị"},{"ten":"Đường vàng hoa mai","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo màu xém vàng óng ả"},{"ten":"Tiêu xay & Ớt hiểm","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"tạo vị ấm cay the"}]', '[{"buoc":1,"tieu_de":"Sơ chế & Thái lát mỏng chuẩn lửa","thoi_gian":"5 phút","noi_dung":"Thịt ba chỉ rửa sạch với muối hạt, thấm thật khô bề mặt. Dùng dao sắc thái thịt thành các lát mỏng đều tay khoảng 2 - 3mm (không thái quá dày thịt lâu xém cạnh, không thái quá mỏng thịt sẽ bị vụn khô xác)."},{"buoc":2,"tieu_de":"Đảo kiệt mỡ & Tạo viền cháy cạnh vàng giòn","thoi_gian":"7 phút","noi_dung":"Đặt chảo chống dính sâu lòng lên bếp không cho dầu ăn. Khi chảo nóng, trút thịt ba chỉ vào đảo đều tay trên lửa vừa. Thịt sẽ tự tiết mỡ ra xèo xèo. Đảo liên tục trong 6 - 8 phút đến khi các cạnh miếng thịt xém vàng ươm, bề mặt se giòn rụm. Nghiêng chảo chắt bớt toàn bộ mỡ thừa ra chén (chỉ giữ lại khoảng 1 thìa nhỏ mỡ trong chảo để tránh bị ngấy)."},{"buoc":3,"tieu_de":"Phi thơm hành & Nấu sốt rim mắm đường","thoi_gian":"3 phút","noi_dung":"Gạt thịt sang một bên chảo, cho hành tím thái lát vào phần mỡ còn lại phi nhanh trong 20 giây cho dậy mùi thơm nức. Pha chén sốt gồm: 2 muỗng nước mắm, 1.5 muỗng đường vàng, 1/2 thìa tiêu, ớt thái lát và 2 muỗng nước lọc khuấy tan hoàn toàn. Rưới toàn bộ chén sốt đều vào chảo thịt."},{"buoc":4,"tieu_de":"Rim kẹo bóng bẩy & Hoàn thiện","thoi_gian":"2 phút","noi_dung":"Tăng lửa lên mức vừa, đảo đều tay liên tục để nước sốt mắm đường sôi sủi bọt keo lại, bao phủ một lớp caramel mặn ngọt bóng bẩy quanh từng miếng thịt vàng rộm. Thả toàn bộ hành hoa cắt khúc vào đảo nhanh tay trong 15 giây rồi tắt bếp ngay. Múc ra đĩa sâu lòng ăn cùng cơm trắng nóng hổi."}]', 'Bắt buộc phải chắt bỏ phần mỡ thừa tiết ra sau khi đảo xém cạnh rồi mới rưới nước mắm đường vào rim; làm như vậy miếng thịt sẽ giòn dai đậm đà mà không hề bị ngấy dầu mỡ.', '{"calo":420,"protein":"24g","chat_beo":"34g","carb":"5g"}', '["Đưa cơm","Dễ làm","Món mặn miền Bắc","Bữa cơm hàng ngày"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (6, 'Cá kho tộ', 'Cá lóc tươi (hoặc cá trắm, cá basa) (600 g), Thịt ba chỉ heo (150 g), Nước dừa tươi (150 ml), Nước mắm ngon cốt cá cơm (3 muỗng canh), Nước hàng (nước màu thắng kẹo) (1.5 muỗng canh), Hành tím, tỏi, ớt chỉ thiên (5 củ/trái), Tiêu sọ giã dập thô (1 muỗng canh)', '[Bước 1: Khử tanh triệt để & Cắt khúc cá - ⏱️ 10 phút]
Cá lóc đánh vảy, mổ sạch màng đen trong bụng (màng đen là nguyên nhân chính gây tanh). Xát muối hạt và nước cốt chanh lên khắp mình cá để làm sạch nhớt, rửa lại thật sạch dưới vòi nước lạnh rồi cắt khúc dày khoảng 3.5cm. Dùng khăn sạch thấm thật khô từng khúc cá.

[Bước 2: Ướp cá thấm sâu từng thớ thịt - ⏱️ 25 phút]
Cho cá vào âu ướp cùng 2.5 muỗng nước mắm nhĩ, 1.5 muỗng nước hàng, 1 muỗng đường, 1/2 muỗng tiêu sọ giã dập, hành tỏi băm và ớt tươi. Trộn nhẹ nhàng và để cá ngấm gia vị trong ít nhất 20 - 25 phút. Lật mặt cá giữa thời gian ướp để gia vị ngấm đều hai mặt.

[Bước 3: Lót đáy tộ đất & Xếp cá đun săn - ⏱️ 8 phút]
Dùng tộ đất hoặc nồi gang dày, xếp đều lớp thịt ba chỉ thái con chì xuống kín đáy nồi (lớp thịt này giúp cá không bị bén cháy đáy tộ và khi kho mỡ thịt tứa ra làm khúc cá béo ngậy). Xếp từng khúc cá lên trên lớp thịt, rưới toàn bộ phần nước ướp cá vào. Đặt tộ lên bếp bật lửa lớn đun sôi bùng trong 5 phút cho thớ thịt cá co săn chắc lại.

[Bước 4: Kho liu riu nước sôi nóng & Kẹo nước sốt - ⏱️ 25 phút]
Đun sôi 150ml nước dừa tươi (hoặc nước sôi nóng già), từ từ châm vào quanh mép tộ cá (tuyệt đối không dùng nước lạnh sẽ làm tanh cá). Hạ lửa nhỏ nhất, đun liu riu mở hé nắp trong 25 - 30 phút cho cá chín mềm rục từ từ. Khi nước kho cạn dần sền sệt sánh đặc bám đều quanh từng khúc cá nâu óng, rắc nhiều tiêu sọ và hành lá cắt khúc lên mặt rồi tắt bếp.

💡 Mẹo đầu bếp: Khi châm thêm nước vào nồi cá đang kho, bắt buộc phải dùng nước thật sôi nóng. Nếu đổ nước lạnh vào cá đang nóng sẽ khiến thớ thịt cá bị tanh nồng và vỡ nát.', '1786036823083.webp', 'Món mặn', 'Cá lóc (hoặc cá basa) kho trong tộ đất chuẩn phong vị Nam Bộ, thịt cá chắc nịch không tanh ngấm đẫm tiêu ớt cay nồng và mỡ ba chỉ béo ngậy.', 'Trung bình', '3 - 4 người', 20, 35, '[{"ten":"Cá lóc tươi (hoặc cá trắm, cá basa)","so_luong":600,"don_vi":"g","ghi_chu":"cắt khúc dày 3 - 3.5cm"},{"ten":"Thịt ba chỉ heo","so_luong":150,"don_vi":"g","ghi_chu":"thái sợi con chì lót đáy tộ"},{"ten":"Nước dừa tươi","so_luong":150,"don_vi":"ml","ghi_chu":"tạo vị ngọt sâu và bóng cá"},{"ten":"Nước mắm ngon cốt cá cơm","so_luong":3,"don_vi":"muỗng canh","ghi_chu":"độ đạm cao"},{"ten":"Nước hàng (nước màu thắng kẹo)","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"màu cánh gián đẹp"},{"ten":"Hành tím, tỏi, ớt chỉ thiên","so_luong":5,"don_vi":"củ/trái","ghi_chu":"băm nhỏ và để nguyên quả"},{"ten":"Tiêu sọ giã dập thô","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"linh hồn món cá kho tộ"}]', '[{"buoc":1,"tieu_de":"Khử tanh triệt để & Cắt khúc cá","thoi_gian":"10 phút","noi_dung":"Cá lóc đánh vảy, mổ sạch màng đen trong bụng (màng đen là nguyên nhân chính gây tanh). Xát muối hạt và nước cốt chanh lên khắp mình cá để làm sạch nhớt, rửa lại thật sạch dưới vòi nước lạnh rồi cắt khúc dày khoảng 3.5cm. Dùng khăn sạch thấm thật khô từng khúc cá."},{"buoc":2,"tieu_de":"Ướp cá thấm sâu từng thớ thịt","thoi_gian":"25 phút","noi_dung":"Cho cá vào âu ướp cùng 2.5 muỗng nước mắm nhĩ, 1.5 muỗng nước hàng, 1 muỗng đường, 1/2 muỗng tiêu sọ giã dập, hành tỏi băm và ớt tươi. Trộn nhẹ nhàng và để cá ngấm gia vị trong ít nhất 20 - 25 phút. Lật mặt cá giữa thời gian ướp để gia vị ngấm đều hai mặt."},{"buoc":3,"tieu_de":"Lót đáy tộ đất & Xếp cá đun săn","thoi_gian":"8 phút","noi_dung":"Dùng tộ đất hoặc nồi gang dày, xếp đều lớp thịt ba chỉ thái con chì xuống kín đáy nồi (lớp thịt này giúp cá không bị bén cháy đáy tộ và khi kho mỡ thịt tứa ra làm khúc cá béo ngậy). Xếp từng khúc cá lên trên lớp thịt, rưới toàn bộ phần nước ướp cá vào. Đặt tộ lên bếp bật lửa lớn đun sôi bùng trong 5 phút cho thớ thịt cá co săn chắc lại."},{"buoc":4,"tieu_de":"Kho liu riu nước sôi nóng & Kẹo nước sốt","thoi_gian":"25 phút","noi_dung":"Đun sôi 150ml nước dừa tươi (hoặc nước sôi nóng già), từ từ châm vào quanh mép tộ cá (tuyệt đối không dùng nước lạnh sẽ làm tanh cá). Hạ lửa nhỏ nhất, đun liu riu mở hé nắp trong 25 - 30 phút cho cá chín mềm rục từ từ. Khi nước kho cạn dần sền sệt sánh đặc bám đều quanh từng khúc cá nâu óng, rắc nhiều tiêu sọ và hành lá cắt khúc lên mặt rồi tắt bếp."}]', 'Khi châm thêm nước vào nồi cá đang kho, bắt buộc phải dùng nước thật sôi nóng. Nếu đổ nước lạnh vào cá đang nóng sẽ khiến thớ thịt cá bị tanh nồng và vỡ nát.', '{"calo":380,"protein":"38g","chat_beo":"22g","carb":"6g"}', '["Đậm đà","Món tộ đất","Món ngon Nam Bộ","Giàu đạm & Omega-3"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (7, 'Gà chiên nước mắm', 'Cánh gà tươi (hoặc tỏi gà) (600 g), Tỏi khô ta (2.5 củ), Ớt hiểm đỏ (2 trái), Nước mắm ngon cốt cá cơm (2.5 muỗng canh), Đường cát trắng (2 muỗng canh), Tương ớt Chin-su (1 muỗng canh), Bột bắp / Bột chiên giòn (2 muỗng canh)', '[Bước 1: Sơ chế gà & Khía thớ thịt - ⏱️ 10 phút]
Cánh gà bóp kỹ với muối hạt, gừng đập dập và chút rượu trắng trong 3 phút để tẩy sạch mùi hôi đặc trưng, rửa sạch lại và để ráo hoàn toàn. Dùng dao khía 2 đường chéo ở mặt trong cánh gà để thịt dễ thấm gia vị và nhanh chín đều bên trong khi chiên.

[Bước 2: Áo bột mỏng & Chiên giòn 2 lần lửa - ⏱️ 12 phút]
Rắc 2 thìa canh bột bắp lên cánh gà, xóc đều để bột bám một lớp mỏng tang như sương quanh miếng gà. Đun chảo ngập dầu nóng già ở lửa vừa, thả cánh gà vào chiên lần 1 trong 8 - 10 phút đến khi thịt gà chín tới, vỏ ngoài hơi hanh vàng thì vớt ra để ráo 5 phút. Trước khi đảo sốt, tăng lửa lớn chiên lại lần 2 trong 1 - 2 phút cho lớp da vàng ươm giòn rụm tối đa.

[Bước 3: Nấu sốt nước mắm tỏi ớt kẹo sền sệt - ⏱️ 3 phút]
Hòa tan hỗn hợp sốt gồm: 2.5 muỗng nước mắm, 2 muỗng đường, 1 muỗng tương ớt và 1 muỗng nước lọc. Chắt bớt dầu trong chảo chỉ chừa lại 1 thìa, cho toàn bộ tỏi băm và ớt băm vào phi vàng giòn dậy mùi thơm nức. Đổ chén sốt nước mắm vào đun sôi bùng, khuấy nhẹ cho đường tan chảy thành hỗn hợp sốt sủi bọt keo sánh đặc.

[Bước 4: Lắc gà đẫm sốt & Hoàn tất - ⏱️ 2 phút]
Trút toàn bộ cánh gà đã chiên giòn vào chảo sốt đang sôi. Hạ lửa vừa, đảo và xóc chảo thật nhanh tay trong 1 - 2 phút cho lớp sốt mắm tỏi óng ánh bao phủ đều khắp các mặt miếng gà. Khi sốt cạn bám dính chặt quanh lớp da giòn rụm thì tắt bếp, bày ra đĩa ăn kèm dưa leo và rau răm.

💡 Mẹo đầu bếp: Kỹ thuật chiên 2 lần lửa (lần 1 lửa vừa cho gà chín kỹ, lần 2 lửa lớn trong 90 giây) là bí quyết giúp gà chiên nước mắm giữ được lớp da giòn rụm cả tiếng đồng hồ mà không hề bị mềm ỉu.', '1786036842355.webp', 'Món mặn', 'Cánh gà chiên vàng ươm giòn rụm lớp da bên ngoài, thịt bên trong mềm ngọt mọng nước, áo đều lớp sốt tỏi ớt mắm đường thơm nức mũi.', 'Trung bình', '3 - 4 người', 15, 25, '[{"ten":"Cánh gà tươi (hoặc tỏi gà)","so_luong":600,"don_vi":"g","ghi_chu":"chặt khúc vừa ăn, khía nhẹ mặt sau"},{"ten":"Tỏi khô ta","so_luong":2.5,"don_vi":"củ","ghi_chu":"băm nhuyễn thật nhiều tỏi phi thơm"},{"ten":"Ớt hiểm đỏ","so_luong":2,"don_vi":"trái","ghi_chu":"băm nhỏ"},{"ten":"Nước mắm ngon cốt cá cơm","so_luong":2.5,"don_vi":"muỗng canh","ghi_chu":"độ đạm cao"},{"ten":"Đường cát trắng","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"cân bằng mặn ngọt"},{"ten":"Tương ớt Chin-su","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"tạo độ sánh đỏ đẹp"},{"ten":"Bột bắp / Bột chiên giòn","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"áo lớp mỏng giòn rụm"}]', '[{"buoc":1,"tieu_de":"Sơ chế gà & Khía thớ thịt","thoi_gian":"10 phút","noi_dung":"Cánh gà bóp kỹ với muối hạt, gừng đập dập và chút rượu trắng trong 3 phút để tẩy sạch mùi hôi đặc trưng, rửa sạch lại và để ráo hoàn toàn. Dùng dao khía 2 đường chéo ở mặt trong cánh gà để thịt dễ thấm gia vị và nhanh chín đều bên trong khi chiên."},{"buoc":2,"tieu_de":"Áo bột mỏng & Chiên giòn 2 lần lửa","thoi_gian":"12 phút","noi_dung":"Rắc 2 thìa canh bột bắp lên cánh gà, xóc đều để bột bám một lớp mỏng tang như sương quanh miếng gà. Đun chảo ngập dầu nóng già ở lửa vừa, thả cánh gà vào chiên lần 1 trong 8 - 10 phút đến khi thịt gà chín tới, vỏ ngoài hơi hanh vàng thì vớt ra để ráo 5 phút. Trước khi đảo sốt, tăng lửa lớn chiên lại lần 2 trong 1 - 2 phút cho lớp da vàng ươm giòn rụm tối đa."},{"buoc":3,"tieu_de":"Nấu sốt nước mắm tỏi ớt kẹo sền sệt","thoi_gian":"3 phút","noi_dung":"Hòa tan hỗn hợp sốt gồm: 2.5 muỗng nước mắm, 2 muỗng đường, 1 muỗng tương ớt và 1 muỗng nước lọc. Chắt bớt dầu trong chảo chỉ chừa lại 1 thìa, cho toàn bộ tỏi băm và ớt băm vào phi vàng giòn dậy mùi thơm nức. Đổ chén sốt nước mắm vào đun sôi bùng, khuấy nhẹ cho đường tan chảy thành hỗn hợp sốt sủi bọt keo sánh đặc."},{"buoc":4,"tieu_de":"Lắc gà đẫm sốt & Hoàn tất","thoi_gian":"2 phút","noi_dung":"Trút toàn bộ cánh gà đã chiên giòn vào chảo sốt đang sôi. Hạ lửa vừa, đảo và xóc chảo thật nhanh tay trong 1 - 2 phút cho lớp sốt mắm tỏi óng ánh bao phủ đều khắp các mặt miếng gà. Khi sốt cạn bám dính chặt quanh lớp da giòn rụm thì tắt bếp, bày ra đĩa ăn kèm dưa leo và rau răm."}]', 'Kỹ thuật chiên 2 lần lửa (lần 1 lửa vừa cho gà chín kỹ, lần 2 lửa lớn trong 90 giây) là bí quyết giúp gà chiên nước mắm giữ được lớp da giòn rụm cả tiếng đồng hồ mà không hề bị mềm ỉu.', '{"calo":460,"protein":"34g","chat_beo":"28g","carb":"16g"}', '["Món khoái khẩu","Giòn rụm","Mặn ngọt","Thích hợp liên hoan/gia đình"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (8, 'Thịt bò xào hành tây', 'Thịt thăn bò tươi (300 g), Hành tây trắng (1 củ), Cần tây & Tỏi tây (boa-rô) (100 g), Cà chua chín (1 quả), Tỏi khô băm nhuyễn (1.5 củ), Dầu hào & Nước tương (1.5 muỗng canh)', '[Bước 1: Ướp thịt bò mềm mọng với dầu ăn - ⏱️ 15 phút]
Thịt bò thái mỏng ngang thớ, ướp với 1 muỗng dầu hào, 1/2 thìa cà phê tiêu, 1/2 lượng tỏi băm và 1 thìa canh dầu ăn trong 15 phút. Dầu ăn sẽ khóa nước ngọt bên trong, giúp thịt bò khi tiếp xúc nhiệt độ cao không bị khô xác hay dai cứng.

[Bước 2: Xào tái thịt bò lửa lớn thần tốc - ⏱️ 2 phút]
Đặt chảo lên bếp bật lửa lớn tối đa, cho 1 thìa dầu ăn phi thơm 1/2 lượng tỏi băm còn lại trong 5 giây. Trút thịt bò vào đảo cực nhanh tay và dứt khoát trong khoảng 60 giây đến khi thịt vừa chuyển tái hồng chín khoảng 70% thì trút ngay ra đĩa riêng.

[Bước 3: Xào hành tây & cần tỏi tây giòn ngọt - ⏱️ 3 phút]
Thêm chút dầu vào chảo trên lửa lớn, cho hành tây và cà chua vào đảo nhanh trong 1.5 phút cho hành tây vừa chín tái bớt hăng. Thả tiếp cần tây và tỏi tây vào đảo đều tay, nêm 1 thìa hạt nêm và chút dầu hào cho rau củ ngấm đều vị.

[Bước 4: Đảo kết hợp & Rắc tiêu thơm lừng - ⏱️ 1 phút]
Đổ đĩa thịt bò cùng toàn bộ nước thịt ngọt trở lại chảo rau, bật lửa to đảo nhanh tay trong 30 giây cho hòa quyện hương vị. Tắt bếp ngay, rắc hạt tiêu xay thô thơm lừng và trút ra đĩa thưởng thức nóng cùng cơm trắng.

💡 Mẹo đầu bếp: Cần tây và tỏi tây rất nhanh chín; chỉ xào chung khoảng 30 - 45 giây để giữ được mùi thơm tinh dầu nồng nàn và độ giòn ngọt mọng nước, không xào lâu rau sẽ bị dai vàng.', '1786036856696.webp', 'Món mặn', 'Thịt bò thăn mềm mọng ngọt đậm đà xào trên lửa lớn cùng hành tây giòn ngọt và cần tỏi tây thơm ngát, món xào bổ dưỡng năng lượng dồi dào.', 'Dễ', '3 người', 15, 8, '[{"ten":"Thịt thăn bò tươi","so_luong":300,"don_vi":"g","ghi_chu":"thái mỏng ngang thớ bản rộng"},{"ten":"Hành tây trắng","so_luong":1,"don_vi":"củ","ghi_chu":"bổ múi cau dày 1.5cm"},{"ten":"Cần tây & Tỏi tây (boa-rô)","so_luong":100,"don_vi":"g","ghi_chu":"cắt khúc 3.5cm"},{"ten":"Cà chua chín","so_luong":1,"don_vi":"quả","ghi_chu":"bổ múi cau tạo độ ẩm"},{"ten":"Tỏi khô băm nhuyễn","so_luong":1.5,"don_vi":"củ","ghi_chu":"phi thơm"},{"ten":"Dầu hào & Nước tương","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"nêm nếm đậm đà"}]', '[{"buoc":1,"tieu_de":"Ướp thịt bò mềm mọng với dầu ăn","thoi_gian":"15 phút","noi_dung":"Thịt bò thái mỏng ngang thớ, ướp với 1 muỗng dầu hào, 1/2 thìa cà phê tiêu, 1/2 lượng tỏi băm và 1 thìa canh dầu ăn trong 15 phút. Dầu ăn sẽ khóa nước ngọt bên trong, giúp thịt bò khi tiếp xúc nhiệt độ cao không bị khô xác hay dai cứng."},{"buoc":2,"tieu_de":"Xào tái thịt bò lửa lớn thần tốc","thoi_gian":"2 phút","noi_dung":"Đặt chảo lên bếp bật lửa lớn tối đa, cho 1 thìa dầu ăn phi thơm 1/2 lượng tỏi băm còn lại trong 5 giây. Trút thịt bò vào đảo cực nhanh tay và dứt khoát trong khoảng 60 giây đến khi thịt vừa chuyển tái hồng chín khoảng 70% thì trút ngay ra đĩa riêng."},{"buoc":3,"tieu_de":"Xào hành tây & cần tỏi tây giòn ngọt","thoi_gian":"3 phút","noi_dung":"Thêm chút dầu vào chảo trên lửa lớn, cho hành tây và cà chua vào đảo nhanh trong 1.5 phút cho hành tây vừa chín tái bớt hăng. Thả tiếp cần tây và tỏi tây vào đảo đều tay, nêm 1 thìa hạt nêm và chút dầu hào cho rau củ ngấm đều vị."},{"buoc":4,"tieu_de":"Đảo kết hợp & Rắc tiêu thơm lừng","thoi_gian":"1 phút","noi_dung":"Đổ đĩa thịt bò cùng toàn bộ nước thịt ngọt trở lại chảo rau, bật lửa to đảo nhanh tay trong 30 giây cho hòa quyện hương vị. Tắt bếp ngay, rắc hạt tiêu xay thô thơm lừng và trút ra đĩa thưởng thức nóng cùng cơm trắng."}]', 'Cần tây và tỏi tây rất nhanh chín; chỉ xào chung khoảng 30 - 45 giây để giữ được mùi thơm tinh dầu nồng nàn và độ giòn ngọt mọng nước, không xào lâu rau sẽ bị dai vàng.', '{"calo":290,"protein":"31g","chat_beo":"11g","carb":"12g"}', '["Nhanh gọn","Bổ dưỡng","Giàu đạm","Bữa tối gia đình"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (9, 'Đậu hũ nhồi thịt sốt cà chua', 'Đậu hũ trắng mơ (4 miếng), Thịt nạc vai xay (200 g), Mộc nhĩ & Nấm hương khô (3 tai), Cà chua chín đỏ (3 quả), Hành tím & Hành hoa (3 nhánh), Nước mắm & Đường (1.5 muỗng canh)', '[Bước 1: Trộn nhân thịt mềm xốp & Khoét đậu - ⏱️ 10 phút]
Đậu hũ cắt làm đôi, dùng thìa nhỏ nhẹ nhàng khoét bớt phần ruột ở giữa tạo thành hình chiếc thuyền (chừa lại thành đậu dày 0.8cm để không bị rách). Lấy phần ruột đậu vừa khoét dầm nát, trộn đều cùng thịt xay, mộc nhĩ nấm hương băm, hành tím, 1 thìa cà phê hạt nêm và 1/2 thìa tiêu (ruột đậu hũ trộn cùng giúp nhân mềm xốp không bị khô cứng sau khi rán).

[Bước 2: Nhồi nhân thịt & Rán định hình - ⏱️ 10 phút]
Dùng thìa múc nhân thịt nhồi chặt vào lòng từng miếng đậu, dùng lưng thìa miết phẳng mặt nhân cho gọn gàng đẹp mắt. Đặt chảo dầu lên bếp đun nóng vừa, úp mặt có nhân thịt xuống rán trước trong 3 phút để nhân thịt săn chắc định hình không bị rơi ra. Lật các mặt còn lại rán vàng đều lớp vỏ đậu rồi gắp ra đĩa.

[Bước 3: Nấu sốt cà chua nhuyễn sánh - ⏱️ 5 phút]
Chắt bớt dầu trong chảo, phi thơm hành tím băm rồi trút cà chua thái hạt lựu vào xào đều trên lửa vừa. Nêm 1.5 muỗng nước mắm, 1 muỗng đường, 1/2 muỗng hạt nêm và nửa chén nước sôi nóng. Dùng muôi dằm nhuyễn cà chua cho đến khi tan mịn thành nước sốt đỏ sánh đặc.

[Bước 4: Om đậu ngấm đẫm sốt cà chua - ⏱️ 8 phút]
Xếp nhẹ nhàng các miếng đậu nhồi thịt vào chảo sốt cà chua. Dùng thìa múc nước sốt rưới đều lên mặt thịt. Đậy nắp chảo, hạ lửa nhỏ om liu riu trong 8 - 10 phút cho nhân thịt chín thấu bên trong và vỏ đậu hút đẫm vị chua ngọt của sốt. Mở nắp, rắc hành hoa thái nhỏ và tiêu thơm rồi tắt bếp.

💡 Mẹo đầu bếp: Bí quyết nhân thịt luôn mềm mướt không bị khô xác là hãy trộn thêm 2 thìa ruột đậu hũ nghiền nhuyễn vào nhân thịt trước khi nhồi; ruột đậu giữ ẩm cực tốt khi chiên rán.', '1786036870851.webp', 'Món mặn', 'Miếng đậu hũ vàng ruộm nhồi nhân thịt băm mộc nhĩ nấm hương béo bùi, om đẫm trong sốt cà chua đỏ au chua ngọt thanh mát cực kỳ bắt cơm.', 'Trung bình', '3 - 4 người', 20, 20, '[{"ten":"Đậu hũ trắng mơ","so_luong":4,"don_vi":"miếng","ghi_chu":"cắt đôi hoặc khoét lỗ ở giữa"},{"ten":"Thịt nạc vai xay","so_luong":200,"don_vi":"g","ghi_chu":"có chút mỡ cho nhân mềm mọng"},{"ten":"Mộc nhĩ & Nấm hương khô","so_luong":3,"don_vi":"tai","ghi_chu":"ngâm nở, băm nhuyễn"},{"ten":"Cà chua chín đỏ","so_luong":3,"don_vi":"quả","ghi_chu":"thái hạt lựu nhỏ"},{"ten":"Hành tím & Hành hoa","so_luong":3,"don_vi":"nhánh","ghi_chu":"băm nhỏ"},{"ten":"Nước mắm & Đường","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"nêm nước sốt"}]', '[{"buoc":1,"tieu_de":"Trộn nhân thịt mềm xốp & Khoét đậu","thoi_gian":"10 phút","noi_dung":"Đậu hũ cắt làm đôi, dùng thìa nhỏ nhẹ nhàng khoét bớt phần ruột ở giữa tạo thành hình chiếc thuyền (chừa lại thành đậu dày 0.8cm để không bị rách). Lấy phần ruột đậu vừa khoét dầm nát, trộn đều cùng thịt xay, mộc nhĩ nấm hương băm, hành tím, 1 thìa cà phê hạt nêm và 1/2 thìa tiêu (ruột đậu hũ trộn cùng giúp nhân mềm xốp không bị khô cứng sau khi rán)."},{"buoc":2,"tieu_de":"Nhồi nhân thịt & Rán định hình","thoi_gian":"10 phút","noi_dung":"Dùng thìa múc nhân thịt nhồi chặt vào lòng từng miếng đậu, dùng lưng thìa miết phẳng mặt nhân cho gọn gàng đẹp mắt. Đặt chảo dầu lên bếp đun nóng vừa, úp mặt có nhân thịt xuống rán trước trong 3 phút để nhân thịt săn chắc định hình không bị rơi ra. Lật các mặt còn lại rán vàng đều lớp vỏ đậu rồi gắp ra đĩa."},{"buoc":3,"tieu_de":"Nấu sốt cà chua nhuyễn sánh","thoi_gian":"5 phút","noi_dung":"Chắt bớt dầu trong chảo, phi thơm hành tím băm rồi trút cà chua thái hạt lựu vào xào đều trên lửa vừa. Nêm 1.5 muỗng nước mắm, 1 muỗng đường, 1/2 muỗng hạt nêm và nửa chén nước sôi nóng. Dùng muôi dằm nhuyễn cà chua cho đến khi tan mịn thành nước sốt đỏ sánh đặc."},{"buoc":4,"tieu_de":"Om đậu ngấm đẫm sốt cà chua","thoi_gian":"8 phút","noi_dung":"Xếp nhẹ nhàng các miếng đậu nhồi thịt vào chảo sốt cà chua. Dùng thìa múc nước sốt rưới đều lên mặt thịt. Đậy nắp chảo, hạ lửa nhỏ om liu riu trong 8 - 10 phút cho nhân thịt chín thấu bên trong và vỏ đậu hút đẫm vị chua ngọt của sốt. Mở nắp, rắc hành hoa thái nhỏ và tiêu thơm rồi tắt bếp."}]', 'Bí quyết nhân thịt luôn mềm mướt không bị khô xác là hãy trộn thêm 2 thìa ruột đậu hũ nghiền nhuyễn vào nhân thịt trước khi nhồi; ruột đậu giữ ẩm cực tốt khi chiên rán.', '{"calo":350,"protein":"26g","chat_beo":"22g","carb":"14g"}', '["Món ngon gia đình","Dễ ăn","Thanh đạm","Đậm đà"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (10, 'Chả giò (Nem rán)', 'Thịt nạc vai xay nhuyễn (350 g), Miến dong & Mộc nhĩ, nấm hương (60 g), Cà rốt & Su hào (hoặc củ đậu) (0.5 củ mỗi loại), Trứng gà tươi (2 quả), Bánh đa nem (vỏ ram Hà Tĩnh) (1 tập (~30 lá)), Giá đỗ & Hành hoa (100 g), Giấm gạo & Bia tươi (1 chén nhỏ)', '[Bước 1: Sơ chế nguyên liệu & Vắt ráo nước củ quả - ⏱️ 15 phút]
Mộc nhĩ, nấm hương ngâm nở rửa sạch thái sợi nhuyễn. Miến dong ngâm nước ấm 5 phút cho mềm rồi cắt khúc ngắn 1.5cm. Cà rốt và su hào bào sợi mỏng, bóp nhẹ với nhúm muối nhỏ trong 3 phút rồi dùng tay vắt thật kiệt nước (đây là bước quyết định giúp nhân nem không bị ra nước làm mềm rách vỏ khi cuốn và rán).

[Bước 2: Kỹ thuật trộn nhân chuẩn độ ẩm - ⏱️ 10 phút]
Cho thịt xay, miến, mộc nhĩ, nấm hương, cà rốt, su hào, giá đỗ và hành hoa vào âu lớn. Thêm 1 thìa cà phê tiêu sọ xay, 1 thìa hạt nêm. Đập 2 lòng đỏ và 1 lòng trắng trứng vào (không cho quá nhiều lòng trắng sẽ làm nhân nhão ướt). Dùng găng tay trộn nhẹ nhàng từ dưới lên cho nguyên liệu hòa quyện đều mà không bóp nát miến.

[Bước 3: Kỹ thuật cuốn nem vừa tay - ⏱️ 15 phút]
Pha chén nước gồm 1 thìa giấm gạo và 2 thìa bia tươi, dùng cọ quét nhẹ một lớp thật mỏng lên lá bánh đa nem (giúp vỏ mềm dễ cuốn và khi rán sẽ giòn rụm màu vàng hổ phách). Múc 1 thìa nhân đặt vào 1/3 lá bánh, gấp mép hai bên lại rồi cuộn tròn vừa tay (tuyệt đối không cuộn quá chặt tay vì khi rán nhân nem nở ra sẽ làm bục nứt vỏ).

[Bước 4: Chiên ngập dầu 2 lần lửa giòn tan 3 tiếng - ⏱️ 20 phút]
Đun chảo dầu ngập 1/2 chiếc nem ở lửa vừa. Thả từng chiếc nem vào chiên lần 1 trong khoảng 4 - 5 phút đến khi vỏ nem se cứng định hình và hơi vàng nhạt thì vớt ra xếp lên rây để nguội ráo dầu. Trước khi ăn, đun dầu nóng già ở lửa lớn, thả nem vào chiên lại lần 2 trong 2 - 3 phút cho lớp vỏ phồng xốp vàng ruộm giòn tan rồi vớt ra giấy thấm dầu. Dọn ăn cùng bún tươi, rau sống và nước mắm chua ngọt.

💡 Mẹo đầu bếp: Bí quyết nem rán giòn rụm cả tiếng không ỉu: (1) Vắt thật kiệt nước ở cà rốt/su hào, (2) Quét một lớp bia pha giấm lên vỏ bánh trước khi cuốn, (3) Rán 2 lần lửa ngập dầu.', '1786036888180.webp', 'Món mặn', 'Nem rán truyền thống với lớp vỏ bánh đa nem vàng ruộm giòn tan lâu ỉu, nhân thịt băm miến mộc nhĩ thơm bùi chấm nước mắm tỏi ớt chua ngọt chuẩn vị.', 'Khó', '4 - 5 người', 30, 30, '[{"ten":"Thịt nạc vai xay nhuyễn","so_luong":350,"don_vi":"g","ghi_chu":"thịt tươi có mỡ nhẹ để nhân ngậy"},{"ten":"Miến dong & Mộc nhĩ, nấm hương","so_luong":60,"don_vi":"g","ghi_chu":"ngâm mềm cắt ngắn 1.5cm"},{"ten":"Cà rốt & Su hào (hoặc củ đậu)","so_luong":0.5,"don_vi":"củ mỗi loại","ghi_chu":"bào sợi ngắn, vắt kiệt nước"},{"ten":"Trứng gà tươi","so_luong":2,"don_vi":"quả","ghi_chu":"lấy 2 lòng đỏ + 1 lòng trắng"},{"ten":"Bánh đa nem (vỏ ram Hà Tĩnh)","so_luong":1,"don_vi":"tập (~30 lá)","ghi_chu":"chọn loại giòn dai"},{"ten":"Giá đỗ & Hành hoa","so_luong":100,"don_vi":"g","ghi_chu":"thái nhỏ ráo nước"},{"ten":"Giấm gạo & Bia tươi","so_luong":1,"don_vi":"chén nhỏ","ghi_chu":"quét vỏ nem giòn rụm"}]', '[{"buoc":1,"tieu_de":"Sơ chế nguyên liệu & Vắt ráo nước củ quả","thoi_gian":"15 phút","noi_dung":"Mộc nhĩ, nấm hương ngâm nở rửa sạch thái sợi nhuyễn. Miến dong ngâm nước ấm 5 phút cho mềm rồi cắt khúc ngắn 1.5cm. Cà rốt và su hào bào sợi mỏng, bóp nhẹ với nhúm muối nhỏ trong 3 phút rồi dùng tay vắt thật kiệt nước (đây là bước quyết định giúp nhân nem không bị ra nước làm mềm rách vỏ khi cuốn và rán)."},{"buoc":2,"tieu_de":"Kỹ thuật trộn nhân chuẩn độ ẩm","thoi_gian":"10 phút","noi_dung":"Cho thịt xay, miến, mộc nhĩ, nấm hương, cà rốt, su hào, giá đỗ và hành hoa vào âu lớn. Thêm 1 thìa cà phê tiêu sọ xay, 1 thìa hạt nêm. Đập 2 lòng đỏ và 1 lòng trắng trứng vào (không cho quá nhiều lòng trắng sẽ làm nhân nhão ướt). Dùng găng tay trộn nhẹ nhàng từ dưới lên cho nguyên liệu hòa quyện đều mà không bóp nát miến."},{"buoc":3,"tieu_de":"Kỹ thuật cuốn nem vừa tay","thoi_gian":"15 phút","noi_dung":"Pha chén nước gồm 1 thìa giấm gạo và 2 thìa bia tươi, dùng cọ quét nhẹ một lớp thật mỏng lên lá bánh đa nem (giúp vỏ mềm dễ cuốn và khi rán sẽ giòn rụm màu vàng hổ phách). Múc 1 thìa nhân đặt vào 1/3 lá bánh, gấp mép hai bên lại rồi cuộn tròn vừa tay (tuyệt đối không cuộn quá chặt tay vì khi rán nhân nem nở ra sẽ làm bục nứt vỏ)."},{"buoc":4,"tieu_de":"Chiên ngập dầu 2 lần lửa giòn tan 3 tiếng","thoi_gian":"20 phút","noi_dung":"Đun chảo dầu ngập 1/2 chiếc nem ở lửa vừa. Thả từng chiếc nem vào chiên lần 1 trong khoảng 4 - 5 phút đến khi vỏ nem se cứng định hình và hơi vàng nhạt thì vớt ra xếp lên rây để nguội ráo dầu. Trước khi ăn, đun dầu nóng già ở lửa lớn, thả nem vào chiên lại lần 2 trong 2 - 3 phút cho lớp vỏ phồng xốp vàng ruộm giòn tan rồi vớt ra giấy thấm dầu. Dọn ăn cùng bún tươi, rau sống và nước mắm chua ngọt."}]', 'Bí quyết nem rán giòn rụm cả tiếng không ỉu: (1) Vắt thật kiệt nước ở cà rốt/su hào, (2) Quét một lớp bia pha giấm lên vỏ bánh trước khi cuốn, (3) Rán 2 lần lửa ngập dầu.', '{"calo":430,"protein":"22g","chat_beo":"25g","carb":"28g"}', '["Món truyền thống","Món cỗ Tết","Giòn rụm","Khoái khẩu"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (11, 'Sườn xào chua ngọt', 'Sườn non heo ngon (500 g), Cà chua chín mọng (2 quả), Ớt chuông & Hành tây (0.5 củ/quả), Giấm gạo lên men tự nhiên (2.5 muỗng canh), Đường cát & Nước mắm (2 muỗng canh mỗi loại), Tương cà & Tương ớt (1.5 muỗng canh)', '[Bước 1: Chần sườn khử sạch bọt bẩn - ⏱️ 10 phút]
Sườn chặt khúc 3 - 4cm, rửa sạch với nước muối. Cho sườn vào nồi nước lạnh cùng 1 thìa cà phê muối và vài lát gừng, đun sôi trong 3 phút để bọt bẩn và mùi hôi tiết ra hết. Vớt sườn ra rửa lại thật sạch bằng nước ấm, dùng khăn giấy thấm khô hoàn toàn.

[Bước 2: Chiên sườn xém vàng da - ⏱️ 8 phút]
Ướp sườn với 1/2 thìa hạt nêm và chút tiêu trong 10 phút. Đun nóng chảo dầu ở lửa vừa, cho từng miếng sườn vào chiên đến khi các mặt xém vàng rộm óng ả (không chiên quá lâu làm thịt sườn bị khô rút nước). Vớt sườn ra đĩa có lót giấy thấm dầu.

[Bước 3: Pha nước sốt chua ngọt tỉ lệ vàng - ⏱️ 4 phút]
Hòa tan hỗn hợp sốt trong chén gồm: 2 muỗng nước mắm, 2 muỗng đường, 2.5 muỗng giấm gạo, 1.5 muỗng tương cà, 1 muỗng tương ớt và 4 muỗng nước lọc. Phi thơm hành tỏi băm trên chảo với 1 thìa dầu ăn, cho cà chua băm nhuyễn vào xào chín nát rồi đổ toàn bộ chén sốt chua ngọt vào đun sôi sủi bọt sánh mịn.

[Bước 4: Rim sườn đẫm sốt sánh quyện - ⏱️ 8 phút]
Trút toàn bộ sườn chiên vàng cùng ớt chuông và hành tây cắt khối vào chảo sốt. Hạ lửa nhỏ vừa, đảo đều tay liên tục trong 6 - 8 phút để nước sốt ngấm đượm và keo sánh lại, ôm một lớp áo đỏ óng ánh quanh từng miếng sườn. Rắc chút tiêu xay và hành hoa rồi tắt bếp múc ra đĩa.

💡 Mẹo đầu bếp: Thêm 1 thìa tương cà vào sốt chua ngọt sẽ giúp màu sắc đỏ óng ả bắt mắt và nước sốt có độ sệt tự nhiên mà không cần dùng đến bột năng.', '1786036904867.webp', 'Món mặn', 'Sườn non heo chặt vừa miếng rán xém vàng giòn, rim đẫm sốt chua ngọt đỏ au sóng sánh từ giấm đường và cà chua, vị đậm đà đưa cơm tuyệt đỉnh.', 'Trung bình', '3 - 4 người', 20, 25, '[{"ten":"Sườn non heo ngon","so_luong":500,"don_vi":"g","ghi_chu":"chọn sườn thăn nhiều sụn mềm, chặt khúc 3 - 4cm"},{"ten":"Cà chua chín mọng","so_luong":2,"don_vi":"quả","ghi_chu":"bỏ hạt băm nhuyễn tạo sốt đỏ"},{"ten":"Ớt chuông & Hành tây","so_luong":0.5,"don_vi":"củ/quả","ghi_chu":"cắt quân cờ vuông 2cm"},{"ten":"Giấm gạo lên men tự nhiên","so_luong":2.5,"don_vi":"muỗng canh","ghi_chu":"tạo độ chua thanh dịu"},{"ten":"Đường cát & Nước mắm","so_luong":2,"don_vi":"muỗng canh mỗi loại","ghi_chu":"tỉ lệ vàng mặn ngọt"},{"ten":"Tương cà & Tương ớt","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo màu đẹp và độ sánh keo"}]', '[{"buoc":1,"tieu_de":"Chần sườn khử sạch bọt bẩn","thoi_gian":"10 phút","noi_dung":"Sườn chặt khúc 3 - 4cm, rửa sạch với nước muối. Cho sườn vào nồi nước lạnh cùng 1 thìa cà phê muối và vài lát gừng, đun sôi trong 3 phút để bọt bẩn và mùi hôi tiết ra hết. Vớt sườn ra rửa lại thật sạch bằng nước ấm, dùng khăn giấy thấm khô hoàn toàn."},{"buoc":2,"tieu_de":"Chiên sườn xém vàng da","thoi_gian":"8 phút","noi_dung":"Ướp sườn với 1/2 thìa hạt nêm và chút tiêu trong 10 phút. Đun nóng chảo dầu ở lửa vừa, cho từng miếng sườn vào chiên đến khi các mặt xém vàng rộm óng ả (không chiên quá lâu làm thịt sườn bị khô rút nước). Vớt sườn ra đĩa có lót giấy thấm dầu."},{"buoc":3,"tieu_de":"Pha nước sốt chua ngọt tỉ lệ vàng","thoi_gian":"4 phút","noi_dung":"Hòa tan hỗn hợp sốt trong chén gồm: 2 muỗng nước mắm, 2 muỗng đường, 2.5 muỗng giấm gạo, 1.5 muỗng tương cà, 1 muỗng tương ớt và 4 muỗng nước lọc. Phi thơm hành tỏi băm trên chảo với 1 thìa dầu ăn, cho cà chua băm nhuyễn vào xào chín nát rồi đổ toàn bộ chén sốt chua ngọt vào đun sôi sủi bọt sánh mịn."},{"buoc":4,"tieu_de":"Rim sườn đẫm sốt sánh quyện","thoi_gian":"8 phút","noi_dung":"Trút toàn bộ sườn chiên vàng cùng ớt chuông và hành tây cắt khối vào chảo sốt. Hạ lửa nhỏ vừa, đảo đều tay liên tục trong 6 - 8 phút để nước sốt ngấm đượm và keo sánh lại, ôm một lớp áo đỏ óng ánh quanh từng miếng sườn. Rắc chút tiêu xay và hành hoa rồi tắt bếp múc ra đĩa."}]', 'Thêm 1 thìa tương cà vào sốt chua ngọt sẽ giúp màu sắc đỏ óng ả bắt mắt và nước sốt có độ sệt tự nhiên mà không cần dùng đến bột năng.', '{"calo":490,"protein":"32g","chat_beo":"30g","carb":"18g"}', '["Đưa cơm","Chua ngọt","Khoái khẩu trẻ em","Bữa tối gia đình"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (12, 'Mực xào dứa (thơm)', 'Mực ống tươi loại dày thịt (400 g), Dứa (thơm) chín vừa (0.5 quả), Cần tây & Tỏi tây (100 g), Cà chua & Hành tây (1 quả/củ), Gừng tươi & Rượu trắng (1 nhánh)', '[Bước 1: Khử tanh & Khía hoa vảy rồng - ⏱️ 10 phút]
Mực rút mai và túi mực, lột sạch lớp màng tím bên ngoài. Bóp mực với gừng giã nhuyễn và 2 thìa rượu trắng trong 2 phút để khử sạch hoàn toàn mùi tanh, rửa sạch lại và thấm khô. Đặt dao nghiêng 45 độ khía các đường ca-rô đan chéo vảy rồng trên thân mực, sau đó cắt thành từng miếng vuông 3.5 x 3.5cm.

[Bước 2: Chần nhanh mực & Khóa độ giòn sần sật - ⏱️ 2 phút]
Đun sôi một nồi nước có vài lát gừng và nhúm muối nhỏ. Thả mực vào chần nhanh trong đúng 20 - 25 giây cho mực nở bung cánh hoa vảy rồng rồi vớt ra ngâm ngay vào thau nước đá lạnh trong 2 phút. Vớt ra rổ lắc thật ráo nước (bước này giúp mực khi xào không bị ra nước làm ỉu rau và giữ độ giòn đanh tối đa).

[Bước 3: Xào thơm dứa và rau củ - ⏱️ 3 phút]
Bật chảo lửa lớn, phi thơm tỏi băm với 1 thìa dầu ăn. Cho dứa và cà chua vào đảo nhanh tay trong 1.5 phút cho dứa tiết vị chua ngọt thơm nức. Thêm hành tây và cần tỏi tây vào đảo đều, nêm 1 thìa dầu hào và 1 thìa hạt nêm.

[Bước 4: Xào mực lửa lớn thần tốc - ⏱️ 1 phút]
Trút toàn bộ mực đã ráo nước vào chảo rau củ. Giữ lửa lớn nhất đảo thật nhanh tay trong 45 - 60 giây cho mực ngấm đều gia vị bóng bẩy. Tắt bếp ngay lập tức, rắc nhiều tiêu sọ xay thơm nồng rồi trút ra đĩa thưởng thức nóng.

💡 Mẹo đầu bếp: Chần sơ mực qua nước sôi có gừng rồi ngâm ngay nước đá lạnh trước khi xào; mực sẽ nở hoa vảy rồng tuyệt đẹp, giòn sần sật và tuyệt đối không chảy nước ra chảo.', '1786036920587.webp', 'Món mặn', 'Mực ống tươi ngọt giòn sần sật khía vảy rồng xào cùng dứa chín chua thơm và cần tỏi tây ngào ngạt, món hải sản thanh nhẹ kích thích vị giác.', 'Dễ', '3 người', 15, 8, '[{"ten":"Mực ống tươi loại dày thịt","so_luong":400,"don_vi":"g","ghi_chu":"mắt trong, thịt trắng đàn hồi"},{"ten":"Dứa (thơm) chín vừa","so_luong":0.5,"don_vi":"quả","ghi_chu":"thái lát mỏng hình rẻ quạt"},{"ten":"Cần tây & Tỏi tây","so_luong":100,"don_vi":"g","ghi_chu":"rửa sạch, cắt khúc 3.5cm"},{"ten":"Cà chua & Hành tây","so_luong":1,"don_vi":"quả/củ","ghi_chu":"bổ múi cau"},{"ten":"Gừng tươi & Rượu trắng","so_luong":1,"don_vi":"nhánh","ghi_chu":"khử sạch mùi tanh của mực"}]', '[{"buoc":1,"tieu_de":"Khử tanh & Khía hoa vảy rồng","thoi_gian":"10 phút","noi_dung":"Mực rút mai và túi mực, lột sạch lớp màng tím bên ngoài. Bóp mực với gừng giã nhuyễn và 2 thìa rượu trắng trong 2 phút để khử sạch hoàn toàn mùi tanh, rửa sạch lại và thấm khô. Đặt dao nghiêng 45 độ khía các đường ca-rô đan chéo vảy rồng trên thân mực, sau đó cắt thành từng miếng vuông 3.5 x 3.5cm."},{"buoc":2,"tieu_de":"Chần nhanh mực & Khóa độ giòn sần sật","thoi_gian":"2 phút","noi_dung":"Đun sôi một nồi nước có vài lát gừng và nhúm muối nhỏ. Thả mực vào chần nhanh trong đúng 20 - 25 giây cho mực nở bung cánh hoa vảy rồng rồi vớt ra ngâm ngay vào thau nước đá lạnh trong 2 phút. Vớt ra rổ lắc thật ráo nước (bước này giúp mực khi xào không bị ra nước làm ỉu rau và giữ độ giòn đanh tối đa)."},{"buoc":3,"tieu_de":"Xào thơm dứa và rau củ","thoi_gian":"3 phút","noi_dung":"Bật chảo lửa lớn, phi thơm tỏi băm với 1 thìa dầu ăn. Cho dứa và cà chua vào đảo nhanh tay trong 1.5 phút cho dứa tiết vị chua ngọt thơm nức. Thêm hành tây và cần tỏi tây vào đảo đều, nêm 1 thìa dầu hào và 1 thìa hạt nêm."},{"buoc":4,"tieu_de":"Xào mực lửa lớn thần tốc","thoi_gian":"1 phút","noi_dung":"Trút toàn bộ mực đã ráo nước vào chảo rau củ. Giữ lửa lớn nhất đảo thật nhanh tay trong 45 - 60 giây cho mực ngấm đều gia vị bóng bẩy. Tắt bếp ngay lập tức, rắc nhiều tiêu sọ xay thơm nồng rồi trút ra đĩa thưởng thức nóng."}]', 'Chần sơ mực qua nước sôi có gừng rồi ngâm ngay nước đá lạnh trước khi xào; mực sẽ nở hoa vảy rồng tuyệt đẹp, giòn sần sật và tuyệt đối không chảy nước ra chảo.', '{"calo":260,"protein":"28g","chat_beo":"5g","carb":"15g"}', '["Hải sản tươi","Chua ngọt","Giàu đạm ít béo","Món xào hấp dẫn"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (13, 'Gà kho gừng', 'Thịt gà ta tươi (đùi/cánh/lườn) (600 g), Gừng tươi củ già (1 củ to (~50g)), Hành tím khô (2 củ), Nước mắm ngon truyền thống (2.5 muỗng canh), Đường thốt nốt / Nước màu (1 muỗng canh), Ớt hiểm & Tiêu xay (1 thìa cà phê)', '[Bước 1: Sơ chế gà sạch thơm & Cắt miếng - ⏱️ 10 phút]
Gà chà xát kỹ với muối hạt và gừng giã trong 3 phút để tẩy sạch mùi hôi lông, rửa lại nước sạch để thật ráo. Dùng dao chặt dứt khoát thành từng miếng vuông vừa ăn khoảng 3 x 3cm (chặt dứt khoát để không bị vụn xương).

[Bước 2: Ướp gà thấm đượm hương gừng - ⏱️ 20 phút]
Ướp gà cùng 2 muỗng nước mắm ngon, 1 muỗng đường, 1 muỗng nước màu, hành tím băm, 1/2 muỗng tiêu xay và một nửa phần gừng thái sợi. Trộn bóp đều và để gà nghỉ 20 phút cho thớ thịt thấm sâu vị mặn ngọt và tinh dầu gừng ấm.

[Bước 3: Phi thơm gừng & Xào săn thịt gà - ⏱️ 6 phút]
Đặt nồi lên bếp cho 1 thìa dầu ăn vào, trút phần gừng sợi còn lại vào phi trên lửa vừa cho đến khi gừng ngả vàng giòn dậy mùi thơm nức mũi. Trút toàn bộ thịt gà đã ướp vào xào đảo liên tục trên lửa vừa trong 5 - 6 phút đến khi thịt gà săn chắc lại, lớp da gà tưa mỡ vàng óng ả.

[Bước 4: Kho liu riu kẹo nước sốt - ⏱️ 15 phút]
Châm thêm nửa chén nước sôi nóng vào ngang mặt thịt gà. Đậy hé nắp đun sôi bùng lên rồi hạ lửa nhỏ liu riu kho trong 15 - 18 phút cho thịt gà mềm thấu gia vị. Khi nước kho cạn keo sền sệt ôm bóng quanh từng miếng thịt gà vàng ươm, rắc ớt chỉ thiên và tiêu thơm rồi tắt bếp.

💡 Mẹo đầu bếp: Chia gừng làm 2 phần: 1 phần ướp sâu trong thịt gà, phần còn lại phi vàng giòn trong dầu trước khi xào gà; hương gừng sẽ tỏa ngát nồng nàn từ trong ra ngoài miếng thịt.', '1786036934209.webp', 'Món mặn', 'Thịt gà ta săn chắc đậm đà ngập tràn hương gừng tươi già thái sợi cay nồng, nước kho vàng óng ánh ấm bụng thích hợp cho ngày mưa hoặc se lạnh.', 'Dễ', '3 - 4 người', 15, 25, '[{"ten":"Thịt gà ta tươi (đùi/cánh/lườn)","so_luong":600,"don_vi":"g","ghi_chu":"chặt miếng vuông 3cm"},{"ten":"Gừng tươi củ già","so_luong":1,"don_vi":"củ to (~50g)","ghi_chu":"gọt vỏ, thái sợi chỉ dài"},{"ten":"Hành tím khô","so_luong":2,"don_vi":"củ","ghi_chu":"băm nhỏ"},{"ten":"Nước mắm ngon truyền thống","so_luong":2.5,"don_vi":"muỗng canh","ghi_chu":"độ đạm cao"},{"ten":"Đường thốt nốt / Nước màu","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"tạo màu cánh gián"},{"ten":"Ớt hiểm & Tiêu xay","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"tạo vị ấm nồng"}]', '[{"buoc":1,"tieu_de":"Sơ chế gà sạch thơm & Cắt miếng","thoi_gian":"10 phút","noi_dung":"Gà chà xát kỹ với muối hạt và gừng giã trong 3 phút để tẩy sạch mùi hôi lông, rửa lại nước sạch để thật ráo. Dùng dao chặt dứt khoát thành từng miếng vuông vừa ăn khoảng 3 x 3cm (chặt dứt khoát để không bị vụn xương)."},{"buoc":2,"tieu_de":"Ướp gà thấm đượm hương gừng","thoi_gian":"20 phút","noi_dung":"Ướp gà cùng 2 muỗng nước mắm ngon, 1 muỗng đường, 1 muỗng nước màu, hành tím băm, 1/2 muỗng tiêu xay và một nửa phần gừng thái sợi. Trộn bóp đều và để gà nghỉ 20 phút cho thớ thịt thấm sâu vị mặn ngọt và tinh dầu gừng ấm."},{"buoc":3,"tieu_de":"Phi thơm gừng & Xào săn thịt gà","thoi_gian":"6 phút","noi_dung":"Đặt nồi lên bếp cho 1 thìa dầu ăn vào, trút phần gừng sợi còn lại vào phi trên lửa vừa cho đến khi gừng ngả vàng giòn dậy mùi thơm nức mũi. Trút toàn bộ thịt gà đã ướp vào xào đảo liên tục trên lửa vừa trong 5 - 6 phút đến khi thịt gà săn chắc lại, lớp da gà tưa mỡ vàng óng ả."},{"buoc":4,"tieu_de":"Kho liu riu kẹo nước sốt","thoi_gian":"15 phút","noi_dung":"Châm thêm nửa chén nước sôi nóng vào ngang mặt thịt gà. Đậy hé nắp đun sôi bùng lên rồi hạ lửa nhỏ liu riu kho trong 15 - 18 phút cho thịt gà mềm thấu gia vị. Khi nước kho cạn keo sền sệt ôm bóng quanh từng miếng thịt gà vàng ươm, rắc ớt chỉ thiên và tiêu thơm rồi tắt bếp."}]', 'Chia gừng làm 2 phần: 1 phần ướp sâu trong thịt gà, phần còn lại phi vàng giòn trong dầu trước khi xào gà; hương gừng sẽ tỏa ngát nồng nàn từ trong ra ngoài miếng thịt.', '{"calo":390,"protein":"35g","chat_beo":"22g","carb":"5g"}', '["Món kho ấm bụng","Đậm đà","Món cơm mùa đông","Truyền thống"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (14, 'Trứng cút kho thịt', 'Thịt ba chỉ heo tươi (350 g), Trứng cút tươi (15 quả), Hành tím khô băm nhỏ (3 củ), Nước mắm ngon & Đường (2 muỗng canh), Nước hàng (nước màu) (1 muỗng canh), Tiêu xay & Hành hoa (1 thìa)', '[Bước 1: Luộc & Bóc vỏ trứng cút nhanh gọn - ⏱️ 8 phút]
Cho trứng cút vào nồi nước lạnh có chút muối và giấm, đun sôi trong 5 phút. Vớt ngay ra thau nước đá lạnh ngâm 3 phút. Lăn nhẹ quả trứng trên mặt bàn cho dập đều vỏ rồi lột vỏ dưới vòi nước chảy; lớp vỏ sẽ tuột ra dễ dàng mà không làm nát lòng trắng.

[Bước 2: Thái & Ướp thịt ba chỉ - ⏱️ 15 phút]
Thịt ba chỉ rửa sạch với nước muối, thái con chì dày khoảng 1.5 x 3cm. Ướp thịt với 1.5 muỗng nước mắm, 1 muỗng đường, 1 muỗng nước màu, 1/2 muỗng tiêu xay và hành tím băm trong 15 phút.

[Bước 3: Xào săn thịt & Đun nước kho - ⏱️ 7 phút]
Cho thịt đã ướp vào nồi đảo đều tay trên lửa vừa trong 4 - 5 phút cho mỡ tứa ra và thịt săn lại se màu vàng nâu bóng. Đổ 1 chén nước sôi nóng vào ngập ngang mặt thịt, đun sôi bùng và hớt bọt.

[Bước 4: Kho cùng trứng cút keo sánh - ⏱️ 15 phút]
Hạ lửa nhỏ liu riu kho trong 10 phút cho thịt mềm. Thả toàn bộ trứng cút vào nồi kho chung thêm 10 phút, thỉnh thoảng dùng muôi lật nhẹ trứng cho ngấm đều màu nâu hổ phách. Khi nước kho sánh lại sền sệt bám quanh thịt và trứng, rắc hành hoa tiêu xay rồi tắt bếp.

💡 Mẹo đầu bếp: Nếu thích vỏ trứng cút dai dai và ngấm màu cánh gián đậm hơn, bạn có thể chiên sơ trứng cút ngập dầu trong 1 phút trước khi thả vào nồi kho cùng thịt.', '1786036955700.webp', 'Món mặn', 'Trứng cút bùi béo kết hợp thịt ba chỉ mềm ngậy đậm đà, đượm nước sốt kho màu cánh gián ngọt thanh, món ăn tuổi thơ quen thuộc trong mâm cơm người Việt.', 'Dễ', '3 - 4 người', 15, 30, '[{"ten":"Thịt ba chỉ heo tươi","so_luong":350,"don_vi":"g","ghi_chu":"thái con chì dày 1.5 x 3cm"},{"ten":"Trứng cút tươi","so_luong":15,"don_vi":"quả","ghi_chu":"luộc chín, bóc sạch vỏ"},{"ten":"Hành tím khô băm nhỏ","so_luong":3,"don_vi":"củ","ghi_chu":"phi thơm"},{"ten":"Nước mắm ngon & Đường","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"cân bằng mặn ngọt"},{"ten":"Nước hàng (nước màu)","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"tạo màu cánh gián"},{"ten":"Tiêu xay & Hành hoa","so_luong":1,"don_vi":"thìa","ghi_chu":"rắc hoàn thiện"}]', '[{"buoc":1,"tieu_de":"Luộc & Bóc vỏ trứng cút nhanh gọn","thoi_gian":"8 phút","noi_dung":"Cho trứng cút vào nồi nước lạnh có chút muối và giấm, đun sôi trong 5 phút. Vớt ngay ra thau nước đá lạnh ngâm 3 phút. Lăn nhẹ quả trứng trên mặt bàn cho dập đều vỏ rồi lột vỏ dưới vòi nước chảy; lớp vỏ sẽ tuột ra dễ dàng mà không làm nát lòng trắng."},{"buoc":2,"tieu_de":"Thái & Ướp thịt ba chỉ","thoi_gian":"15 phút","noi_dung":"Thịt ba chỉ rửa sạch với nước muối, thái con chì dày khoảng 1.5 x 3cm. Ướp thịt với 1.5 muỗng nước mắm, 1 muỗng đường, 1 muỗng nước màu, 1/2 muỗng tiêu xay và hành tím băm trong 15 phút."},{"buoc":3,"tieu_de":"Xào săn thịt & Đun nước kho","thoi_gian":"7 phút","noi_dung":"Cho thịt đã ướp vào nồi đảo đều tay trên lửa vừa trong 4 - 5 phút cho mỡ tứa ra và thịt săn lại se màu vàng nâu bóng. Đổ 1 chén nước sôi nóng vào ngập ngang mặt thịt, đun sôi bùng và hớt bọt."},{"buoc":4,"tieu_de":"Kho cùng trứng cút keo sánh","thoi_gian":"15 phút","noi_dung":"Hạ lửa nhỏ liu riu kho trong 10 phút cho thịt mềm. Thả toàn bộ trứng cút vào nồi kho chung thêm 10 phút, thỉnh thoảng dùng muôi lật nhẹ trứng cho ngấm đều màu nâu hổ phách. Khi nước kho sánh lại sền sệt bám quanh thịt và trứng, rắc hành hoa tiêu xay rồi tắt bếp."}]', 'Nếu thích vỏ trứng cút dai dai và ngấm màu cánh gián đậm hơn, bạn có thể chiên sơ trứng cút ngập dầu trong 1 phút trước khi thả vào nồi kho cùng thịt.', '{"calo":420,"protein":"26g","chat_beo":"32g","carb":"6g"}', '["Đưa cơm","Gia đình","Dễ làm","Món mặn truyền thống"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (15, 'Tôm rim mặn ngọt', 'Tôm tươi (tôm đất hoặc tôm sú) (350 g), Tỏi khô ta băm nhuyễn (1.5 muỗng canh), Nước mắm ngon cốt cá cơm (2 muỗng canh), Đường thốt nốt hoặc đường cát (1.5 muỗng canh), Tiêu đen xay & Hành hoa (1 thìa)', '[Bước 1: Sơ chế & Rút chỉ lưng tôm - ⏱️ 8 phút]
Tôm dùng kéo cắt bỏ phần râu dài và ngạnh nhọn ở đầu, cắt bớt chóp đuôi. Dùng tăm nhọn xiên vào đốt sống thứ 2 trên lưng tôm nhẹ nhàng kéo sạch sợi chỉ đen đắng ra ngoài. Rửa sạch tôm với nước muối loãng rồi dùng khăn thấm thật khô ráo.

[Bước 2: Đảo tôm săn giòn vỏ - ⏱️ 3 phút]
Đặt chảo lên bếp với 1 thìa dầu ăn đun nóng già ở lửa lớn. Trút toàn bộ tôm vào đảo nhanh tay liên tục trong 2 - 3 phút đến khi tôm chuyển sang màu đỏ cam rực rỡ, lớp vỏ co săn giòn rụm thì trút tôm ra đĩa riêng.

[Bước 3: Nấu sốt rim mặn ngọt caramel - ⏱️ 3 phút]
Cho thêm 1 thìa dầu vào chảo phi thơm tỏi băm đến khi vàng ruộm. Trút hỗn hợp gồm 2 muỗng nước mắm, 1.5 muỗng đường, 1/2 muỗng tiêu và 1 muỗng nước lọc vào chảo. Đun lửa vừa khuấy đều cho đường tan chảy sủi bọt khí keo lại sền sệt.

[Bước 4: Rim tôm đẫm sốt óng ả - ⏱️ 3 phút]
Đổ đĩa tôm trở lại chảo sốt, đảo đều tay liên tục trên lửa vừa trong 2 - 3 phút để nước sốt bám dính một lớp caramel đỏ bóng bao quanh từng con tôm. Khi sốt cạn ráo keo lại, rắc hành hoa thái nhỏ đảo 5 giây rồi tắt bếp múc ra đĩa.

💡 Mẹo đầu bếp: Đảo tôm trên lửa lớn cho vỏ săn trước khi cho sốt đường mắm vào rim; cách này giúp vỏ tôm giòn tan mà thịt tôm bên trong vẫn giữ nguyên vị ngọt mọng nước tự nhiên.', '1786036969926.webp', 'Món mặn', 'Tôm sú hoặc tôm đất tươi rim mặn ngọt óng ánh, vỏ giòn rụm sần sật, thịt tôm đỏ au săn ngọt ngào đậm đà thơm nồng tỏi ớt.', 'Dễ', '3 người', 10, 12, '[{"ten":"Tôm tươi (tôm đất hoặc tôm sú)","so_luong":350,"don_vi":"g","ghi_chu":"cắt bỏ râu và ngạnh đầu nhọn"},{"ten":"Tỏi khô ta băm nhuyễn","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"phi thơm"},{"ten":"Nước mắm ngon cốt cá cơm","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"độ mặn chuẩn"},{"ten":"Đường thốt nốt hoặc đường cát","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo độ keo dính bóng bẩy"},{"ten":"Tiêu đen xay & Hành hoa","so_luong":1,"don_vi":"thìa","ghi_chu":"tạo mùi thơm"}]', '[{"buoc":1,"tieu_de":"Sơ chế & Rút chỉ lưng tôm","thoi_gian":"8 phút","noi_dung":"Tôm dùng kéo cắt bỏ phần râu dài và ngạnh nhọn ở đầu, cắt bớt chóp đuôi. Dùng tăm nhọn xiên vào đốt sống thứ 2 trên lưng tôm nhẹ nhàng kéo sạch sợi chỉ đen đắng ra ngoài. Rửa sạch tôm với nước muối loãng rồi dùng khăn thấm thật khô ráo."},{"buoc":2,"tieu_de":"Đảo tôm săn giòn vỏ","thoi_gian":"3 phút","noi_dung":"Đặt chảo lên bếp với 1 thìa dầu ăn đun nóng già ở lửa lớn. Trút toàn bộ tôm vào đảo nhanh tay liên tục trong 2 - 3 phút đến khi tôm chuyển sang màu đỏ cam rực rỡ, lớp vỏ co săn giòn rụm thì trút tôm ra đĩa riêng."},{"buoc":3,"tieu_de":"Nấu sốt rim mặn ngọt caramel","thoi_gian":"3 phút","noi_dung":"Cho thêm 1 thìa dầu vào chảo phi thơm tỏi băm đến khi vàng ruộm. Trút hỗn hợp gồm 2 muỗng nước mắm, 1.5 muỗng đường, 1/2 muỗng tiêu và 1 muỗng nước lọc vào chảo. Đun lửa vừa khuấy đều cho đường tan chảy sủi bọt khí keo lại sền sệt."},{"buoc":4,"tieu_de":"Rim tôm đẫm sốt óng ả","thoi_gian":"3 phút","noi_dung":"Đổ đĩa tôm trở lại chảo sốt, đảo đều tay liên tục trên lửa vừa trong 2 - 3 phút để nước sốt bám dính một lớp caramel đỏ bóng bao quanh từng con tôm. Khi sốt cạn ráo keo lại, rắc hành hoa thái nhỏ đảo 5 giây rồi tắt bếp múc ra đĩa."}]', 'Đảo tôm trên lửa lớn cho vỏ săn trước khi cho sốt đường mắm vào rim; cách này giúp vỏ tôm giòn tan mà thịt tôm bên trong vẫn giữ nguyên vị ngọt mọng nước tự nhiên.', '{"calo":280,"protein":"32g","chat_beo":"8g","carb":"10g"}', '["Đưa cơm","Nhanh gọn","Giàu canxi & đạm","Món mặn dân dã"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (16, 'Chả cá chiên', 'Thịt cá thác lác nạo tươi (400 g), Mỡ heo phần thăn (50 g), Thì là tươi & Hành hoa (50 g), Hành tím băm nhuyễn (2 củ), Nước mắm ngon & Tiêu sọ đập dập (1.5 muỗng canh), Dầu ăn chiên ngập (250 ml)', '[Bước 1: Chuẩn bị độ lạnh & Sơ chế thì là - ⏱️ 10 phút]
Thịt cá nạo để trong ngăn đá tủ lạnh khoảng 15 phút trước khi làm cho thịt cá se lạnh (nhiệt độ lạnh là bí quyết vàng để protein cá kết dính dẻo dai mà không cần hàn the). Mỡ heo luộc sơ thái hạt lựu thật nhỏ ướp chút đường cho trong veo. Thì là và hành hoa rửa sạch, vẩy ráo nước rồi dùng dao sắc thái thật nhuyễn.

[Bước 2: Kỹ thuật quết chả cá dẻo quánh - ⏱️ 12 phút]
Cho cá nạo vào âu cùng 1.5 muỗng nước mắm nhĩ, 1 thìa cà phê hạt nêm, 1 thìa tiêu sọ giã dập thô, hành tím băm và 1 thìa dầu ăn. Dùng muôi gỗ hoặc thìa lớn miết và quết thật mạnh tay theo một chiều cố định liên tục trong 10 - 12 phút. Khi thấy khối cá dẻo quánh, dính chặt vào muôi và bóng mịn thì trút mỡ hạt lựu và thì là vào trộn đều nhẹ nhàng.

[Bước 3: Tạo hình miếng chả tròn dẹt - ⏱️ 5 phút]
Thoa một lớp mỏng dầu ăn lên hai lòng bàn tay để chống dính. Múc từng viên cá nặng khoảng 50g, vo tròn trong lòng bàn tay rồi ấn dẹt thành miếng chả tròn dày khoảng 1.2 - 1.5cm (không nặn quá mỏng chả sẽ khô, không nặn quá dày chả lâu chín ở giữa).

[Bước 4: Chiên phồng vàng ruộm & Hoàn thiện - ⏱️ 10 phút]
Đun nóng chảo dầu ở mức nhiệt vừa (khoảng 160°C). Nhẹ nhàng thả từng miếng chả cá vào chiên. Khi miếng chả nổi lên mặt dầu và phồng căng tròn, lật mặt chiên tiếp trong 3 - 4 phút cho cả hai mặt chuyển sang màu vàng ruộm óng ả. Vớt ra để ráo dầu trên vỉ inox rồi dùng dao thái lát xéo ăn kèm tương ớt hoặc nước mắm chanh tỏi.

💡 Mẹo đầu bếp: Bắt buộc thịt cá phải giữ thật lạnh trước khi quết và chỉ quết theo một chiều cố định; các thớ protein sẽ đan xen tạo độ dai giòn tự nhiên 100% không cần hóa chất.', '1786036988521.webp', 'Món mặn', 'Chả cá thác lác quết dẻo quánh tự nhiên, dậy mùi thơm đặc trưng của thì là tươi và tiêu sọ, chiên phồng vàng ươm dai giòn không hàn the.', 'Trung bình', '3 - 4 người', 20, 15, '[{"ten":"Thịt cá thác lác nạo tươi","so_luong":400,"don_vi":"g","ghi_chu":"giữ thật lạnh để chả dai giòn"},{"ten":"Mỡ heo phần thăn","so_luong":50,"don_vi":"g","ghi_chu":"luộc sơ, thái hạt lựu nhỏ giúp chả không bị khô"},{"ten":"Thì là tươi & Hành hoa","so_luong":50,"don_vi":"g","ghi_chu":"rửa sạch, thái thật nhuyễn"},{"ten":"Hành tím băm nhuyễn","so_luong":2,"don_vi":"củ","ghi_chu":"phi thơm"},{"ten":"Nước mắm ngon & Tiêu sọ đập dập","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo mùi thơm nồng nàn"},{"ten":"Dầu ăn chiên ngập","so_luong":250,"don_vi":"ml","ghi_chu":"chiên chả phồng đều"}]', '[{"buoc":1,"tieu_de":"Chuẩn bị độ lạnh & Sơ chế thì là","thoi_gian":"10 phút","noi_dung":"Thịt cá nạo để trong ngăn đá tủ lạnh khoảng 15 phút trước khi làm cho thịt cá se lạnh (nhiệt độ lạnh là bí quyết vàng để protein cá kết dính dẻo dai mà không cần hàn the). Mỡ heo luộc sơ thái hạt lựu thật nhỏ ướp chút đường cho trong veo. Thì là và hành hoa rửa sạch, vẩy ráo nước rồi dùng dao sắc thái thật nhuyễn."},{"buoc":2,"tieu_de":"Kỹ thuật quết chả cá dẻo quánh","thoi_gian":"12 phút","noi_dung":"Cho cá nạo vào âu cùng 1.5 muỗng nước mắm nhĩ, 1 thìa cà phê hạt nêm, 1 thìa tiêu sọ giã dập thô, hành tím băm và 1 thìa dầu ăn. Dùng muôi gỗ hoặc thìa lớn miết và quết thật mạnh tay theo một chiều cố định liên tục trong 10 - 12 phút. Khi thấy khối cá dẻo quánh, dính chặt vào muôi và bóng mịn thì trút mỡ hạt lựu và thì là vào trộn đều nhẹ nhàng."},{"buoc":3,"tieu_de":"Tạo hình miếng chả tròn dẹt","thoi_gian":"5 phút","noi_dung":"Thoa một lớp mỏng dầu ăn lên hai lòng bàn tay để chống dính. Múc từng viên cá nặng khoảng 50g, vo tròn trong lòng bàn tay rồi ấn dẹt thành miếng chả tròn dày khoảng 1.2 - 1.5cm (không nặn quá mỏng chả sẽ khô, không nặn quá dày chả lâu chín ở giữa)."},{"buoc":4,"tieu_de":"Chiên phồng vàng ruộm & Hoàn thiện","thoi_gian":"10 phút","noi_dung":"Đun nóng chảo dầu ở mức nhiệt vừa (khoảng 160°C). Nhẹ nhàng thả từng miếng chả cá vào chiên. Khi miếng chả nổi lên mặt dầu và phồng căng tròn, lật mặt chiên tiếp trong 3 - 4 phút cho cả hai mặt chuyển sang màu vàng ruộm óng ả. Vớt ra để ráo dầu trên vỉ inox rồi dùng dao thái lát xéo ăn kèm tương ớt hoặc nước mắm chanh tỏi."}]', 'Bắt buộc thịt cá phải giữ thật lạnh trước khi quết và chỉ quết theo một chiều cố định; các thớ protein sẽ đan xen tạo độ dai giòn tự nhiên 100% không cần hóa chất.', '{"calo":320,"protein":"30g","chat_beo":"18g","carb":"4g"}', '["Món chiên ngon","Thì là thơm lừng","Dẻo dai tự nhiên","Món nhắm / ăn cơm"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (17, 'Bò sốt vang', 'Dẻ sườn hoặc nạm bắp bò (600 g), Khoai tây & Cà rốt (2 củ mỗi loại), Rượu vang đỏ (Cabernet/Merlot) (150 ml), Cà chua chín & Sốt cà chua Paste (2 quả / 2 muỗng), Quế, hoa hồi, thảo quả (1 set), Bơ lạt & Tỏi băm nhuyễn (30 g), Bột bắp (hoặc bột năng) (1.5 muỗng canh)', '[Bước 1: Chần thịt bò & Cắt khối quân cờ - ⏱️ 10 phút]
Thịt dẻ sườn bò rửa sạch với rượu gừng, chần qua nước sôi 3 phút rồi vớt ra xả nước lạnh để thịt sạch bọt cặn và không bị ngái mùi. Cắt thịt thành từng khối vuông vức kích thước 3.5 x 3.5cm (khi hầm thịt co lại là vừa ăn).

[Bước 2: Ướp thịt bò với rượu vang đỏ lần 1 - ⏱️ 30 phút]
Cho thịt bò vào âu cùng 100ml rượu vang đỏ, 1 muỗng tỏi băm, 1 thìa canh hạt nêm, 1 thìa đường, 1/2 thìa ngũ vị hương, 1 thìa tiêu đen và 1 muỗng nước mắm. Trộn đều và bọc màng thực phẩm ướp trong ít nhất 30 phút để cồn trong rượu vang phá vỡ cấu trúc cơ thịt giúp thịt mềm nhừ nhanh chóng.

[Bước 3: Xào săn thịt với bơ tỏi & Sốt cà chua - ⏱️ 8 phút]
Đặt nồi dày lên bếp, đun chảy 30g bơ lạt, phi thơm tỏi băm đến khi dậy mùi thơm béo. Cho cà chua băm và 2 thìa sốt cà chua paste vào xào nhuyễn lấy màu đỏ ruby. Trút thịt bò đã ướp vào đảo đều tay trên lửa lớn trong 5 phút cho các cạnh thịt săn chắc lại và ngấm màu đỏ đẹp.

[Bước 4: Hầm nhừ cùng thảo mộc quế hồi - ⏱️ 40 phút]
Đổ nước sôi nóng ngập mặt thịt khoảng 2 đốt ngón tay. Cho thanh quế, 2 cánh hoa hồi và 1 quả thảo quả đã nướng thơm vào nồi. Đậy vung đun sôi bùng, hớt sạch bọt rồi hạ lửa nhỏ nhất hầm liu riu trong 40 phút cho thịt bò mềm rục, thớ gân trong veo dẻo quánh.

[Bước 5: Nấu rau củ, Thêm vang đỏ lần 2 & Tạo độ sánh - ⏱️ 15 phút]
Thả khoai tây và cà rốt vào hầm thêm 12 phút cho củ quả vừa chín mềm bở tơi. Rót 50ml rượu vang đỏ còn lại vào nồi (giữ hương thơm nguyên bản của vang), nêm nếm lại gia vị vừa miệng. Từ từ rót bát bột bắp hòa nước vào khuấy đều nhẹ tay theo một chiều trong 2 phút đến khi nước sốt sánh mịn bóng bẩy ôm lấy miếng thịt thì tắt bếp. Rắc ngò gai thái nhỏ thưởng thức cùng bánh mì nóng giòn.

💡 Mẹo đầu bếp: Bí quyết vàng của món bò sốt vang chuẩn Âu: Chia rượu vang làm 2 lần - 2/3 dùng để ướp thịt từ đầu giúp thịt mềm rục, 1/3 còn lại cho vào trước khi tắt bếp 3 phút để giữ trọn vẹn hương nồng nàn quyến rũ.', '1786037002591.webp', 'Món mặn', 'Bò sốt vang phong cách ẩm thực Pháp - Việt tinh tế, từng thớ thịt nạm bò mềm rục ngấm hương quế hồi và rượu vang đỏ sóng sánh ăn kèm bánh mì hoặc cơm nóng.', 'Khó', '4 - 5 người', 25, 60, '[{"ten":"Dẻ sườn hoặc nạm bắp bò","so_luong":600,"don_vi":"g","ghi_chu":"có gân nạc đan xen, thái quân cờ 3.5cm"},{"ten":"Khoai tây & Cà rốt","so_luong":2,"don_vi":"củ mỗi loại","ghi_chu":"gọt vỏ cắt khối dày 3cm"},{"ten":"Rượu vang đỏ (Cabernet/Merlot)","so_luong":150,"don_vi":"ml","ghi_chu":"chia làm 2 lần nấu"},{"ten":"Cà chua chín & Sốt cà chua Paste","so_luong":2,"don_vi":"quả / 2 muỗng","ghi_chu":"tạo màu đỏ vang đẹp"},{"ten":"Quế, hoa hồi, thảo quả","so_luong":1,"don_vi":"set","ghi_chu":"rang thơm dậy mùi"},{"ten":"Bơ lạt & Tỏi băm nhuyễn","so_luong":30,"don_vi":"g","ghi_chu":"xào thịt bò thơm ngậy"},{"ten":"Bột bắp (hoặc bột năng)","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"hòa nước tạo độ sánh"}]', '[{"buoc":1,"tieu_de":"Chần thịt bò & Cắt khối quân cờ","thoi_gian":"10 phút","noi_dung":"Thịt dẻ sườn bò rửa sạch với rượu gừng, chần qua nước sôi 3 phút rồi vớt ra xả nước lạnh để thịt sạch bọt cặn và không bị ngái mùi. Cắt thịt thành từng khối vuông vức kích thước 3.5 x 3.5cm (khi hầm thịt co lại là vừa ăn)."},{"buoc":2,"tieu_de":"Ướp thịt bò với rượu vang đỏ lần 1","thoi_gian":"30 phút","noi_dung":"Cho thịt bò vào âu cùng 100ml rượu vang đỏ, 1 muỗng tỏi băm, 1 thìa canh hạt nêm, 1 thìa đường, 1/2 thìa ngũ vị hương, 1 thìa tiêu đen và 1 muỗng nước mắm. Trộn đều và bọc màng thực phẩm ướp trong ít nhất 30 phút để cồn trong rượu vang phá vỡ cấu trúc cơ thịt giúp thịt mềm nhừ nhanh chóng."},{"buoc":3,"tieu_de":"Xào săn thịt với bơ tỏi & Sốt cà chua","thoi_gian":"8 phút","noi_dung":"Đặt nồi dày lên bếp, đun chảy 30g bơ lạt, phi thơm tỏi băm đến khi dậy mùi thơm béo. Cho cà chua băm và 2 thìa sốt cà chua paste vào xào nhuyễn lấy màu đỏ ruby. Trút thịt bò đã ướp vào đảo đều tay trên lửa lớn trong 5 phút cho các cạnh thịt săn chắc lại và ngấm màu đỏ đẹp."},{"buoc":4,"tieu_de":"Hầm nhừ cùng thảo mộc quế hồi","thoi_gian":"40 phút","noi_dung":"Đổ nước sôi nóng ngập mặt thịt khoảng 2 đốt ngón tay. Cho thanh quế, 2 cánh hoa hồi và 1 quả thảo quả đã nướng thơm vào nồi. Đậy vung đun sôi bùng, hớt sạch bọt rồi hạ lửa nhỏ nhất hầm liu riu trong 40 phút cho thịt bò mềm rục, thớ gân trong veo dẻo quánh."},{"buoc":5,"tieu_de":"Nấu rau củ, Thêm vang đỏ lần 2 & Tạo độ sánh","thoi_gian":"15 phút","noi_dung":"Thả khoai tây và cà rốt vào hầm thêm 12 phút cho củ quả vừa chín mềm bở tơi. Rót 50ml rượu vang đỏ còn lại vào nồi (giữ hương thơm nguyên bản của vang), nêm nếm lại gia vị vừa miệng. Từ từ rót bát bột bắp hòa nước vào khuấy đều nhẹ tay theo một chiều trong 2 phút đến khi nước sốt sánh mịn bóng bẩy ôm lấy miếng thịt thì tắt bếp. Rắc ngò gai thái nhỏ thưởng thức cùng bánh mì nóng giòn."}]', 'Bí quyết vàng của món bò sốt vang chuẩn Âu: Chia rượu vang làm 2 lần - 2/3 dùng để ướp thịt từ đầu giúp thịt mềm rục, 1/3 còn lại cho vào trước khi tắt bếp 3 phút để giữ trọn vẹn hương nồng nàn quyến rũ.', '{"calo":480,"protein":"36g","chat_beo":"24g","carb":"22g"}', '["Món hầm sang trọng","Ăn kèm bánh mì","Hương vị Á-Âu","Món ngon cuối tuần"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (18, 'Gà luộc lá chanh', 'Gà ta thả vườn nguyên con (1.4 kg), Lá chanh tươi bánh tẻ (12 lá), Gừng củ & Hành tím khô (3 củ mỗi loại), Mỡ gà rán vàng trộn bột nghệ (1 thìa), Muối hạt & Chanh ớt (1 set)', '[Bước 1: Sơ chế gà sạch thơm & Định hình cánh tiên - ⏱️ 10 phút]
Gà xát kỹ với muối hạt và gừng giã trong 3 phút khử sạch mùi hôi, rửa sạch dưới vòi nước lạnh, mổ moi sạch phổi và máu tụ trong xương sống. Bẻ gập 2 cánh gà về phía sau lườn hoặc dùng lạt buộc cánh tiên để khi luộc gà có tư thế ngẩng cao đầu trang trọng.

[Bước 2: Luộc gà nước lạnh & Canh nhiệt độ sôi - ⏱️ 15 phút]
Đặt gà vào nồi to úp phần bụng xuống dưới đáy nồi (lưng hướng lên trên). Đổ nước lạnh ngập hoàn toàn thân gà. Thả hành khô nướng, gừng đập dập và 1 thìa canh hạt nêm vào nồi. Bật lửa lớn đun đến khi nước sôi bùng lên thì hạ ngay lửa xuống mức nhỏ nhất, vớt sạch bọt và đậy hé vung đun liu riu đúng 15 phút.

[Bước 3: Kỹ thuật ngâm ủ chín thấu từ trong tủy - ⏱️ 15 phút]
Sau 15 phút sôi liu riu, tắt bếp hoàn toàn nhưng KHÔNG vớt gà ra ngay. Đậy kín nắp vung nồi và để gà ngâm ủ trong nước nóng thêm đúng 15 phút. Hơi nóng thẩm thấu từ từ sẽ làm phần thịt đùi và khớp xương chín mềm ngọt mọng mà da gà tuyệt đối không bị rách nứt hay thâm đỏ tủy.

[Bước 4: Sốc nhiệt nước đá & Quét mỡ nghệ bóng bẩy - ⏱️ 10 phút]
Vớt gà ra thả ngay vào thau nước đá lạnh ngập thân gà trong 5 phút. Nước đá lạnh sẽ làm lớp da gà co săn lại tức thì, tạo độ giòn sần sật đặc trưng. Vớt gà ra để ráo, dùng cọ quét đều hỗn hợp mỡ gà pha chút tinh bột nghệ lên khắp bề mặt da để tạo màu vàng óng ả căng bóng. Dùng dao sắc chặt miếng vuông vắn đều tăm tắp, xếp ra đĩa và rắc lá chanh thái chỉ mỏng như sợi tơ lên trên.

💡 Mẹo đầu bếp: Công thức vàng: ''Luộc 15 phút lửa nhỏ - Tắt bếp ngâm ủ 15 phút - Sốc nhiệt nước đá 5 phút'' đảm bảo 100% da gà căng bóng giòn rụm nguyên vẹn, thịt chín mọng nước không bao giờ bị đỏ xương.', '1786037018198.webp', 'Món mặn', 'Gà ta luộc da vàng óng căng bóng giòn sần sật, thịt chắc ngọt mọng nước thơm thoang thoảng mùi gừng hành và lá chanh thái chỉ tươi non.', 'Dễ', '4 - 5 người', 10, 30, '[{"ten":"Gà ta thả vườn nguyên con","so_luong":1.4,"don_vi":"kg","ghi_chu":"chọn gà mái tơ ức đầy, da vàng tự nhiên"},{"ten":"Lá chanh tươi bánh tẻ","so_luong":12,"don_vi":"lá","ghi_chu":"thái chỉ thật mỏng rắc mặt"},{"ten":"Gừng củ & Hành tím khô","so_luong":3,"don_vi":"củ mỗi loại","ghi_chu":"nướng sơ đập dập"},{"ten":"Mỡ gà rán vàng trộn bột nghệ","so_luong":1,"don_vi":"thìa","ghi_chu":"quét da gà vàng ươm bóng bẩy"},{"ten":"Muối hạt & Chanh ớt","so_luong":1,"don_vi":"set","ghi_chu":"làm muối tiêu chanh chuẩn vị"}]', '[{"buoc":1,"tieu_de":"Sơ chế gà sạch thơm & Định hình cánh tiên","thoi_gian":"10 phút","noi_dung":"Gà xát kỹ với muối hạt và gừng giã trong 3 phút khử sạch mùi hôi, rửa sạch dưới vòi nước lạnh, mổ moi sạch phổi và máu tụ trong xương sống. Bẻ gập 2 cánh gà về phía sau lườn hoặc dùng lạt buộc cánh tiên để khi luộc gà có tư thế ngẩng cao đầu trang trọng."},{"buoc":2,"tieu_de":"Luộc gà nước lạnh & Canh nhiệt độ sôi","thoi_gian":"15 phút","noi_dung":"Đặt gà vào nồi to úp phần bụng xuống dưới đáy nồi (lưng hướng lên trên). Đổ nước lạnh ngập hoàn toàn thân gà. Thả hành khô nướng, gừng đập dập và 1 thìa canh hạt nêm vào nồi. Bật lửa lớn đun đến khi nước sôi bùng lên thì hạ ngay lửa xuống mức nhỏ nhất, vớt sạch bọt và đậy hé vung đun liu riu đúng 15 phút."},{"buoc":3,"tieu_de":"Kỹ thuật ngâm ủ chín thấu từ trong tủy","thoi_gian":"15 phút","noi_dung":"Sau 15 phút sôi liu riu, tắt bếp hoàn toàn nhưng KHÔNG vớt gà ra ngay. Đậy kín nắp vung nồi và để gà ngâm ủ trong nước nóng thêm đúng 15 phút. Hơi nóng thẩm thấu từ từ sẽ làm phần thịt đùi và khớp xương chín mềm ngọt mọng mà da gà tuyệt đối không bị rách nứt hay thâm đỏ tủy."},{"buoc":4,"tieu_de":"Sốc nhiệt nước đá & Quét mỡ nghệ bóng bẩy","thoi_gian":"10 phút","noi_dung":"Vớt gà ra thả ngay vào thau nước đá lạnh ngập thân gà trong 5 phút. Nước đá lạnh sẽ làm lớp da gà co săn lại tức thì, tạo độ giòn sần sật đặc trưng. Vớt gà ra để ráo, dùng cọ quét đều hỗn hợp mỡ gà pha chút tinh bột nghệ lên khắp bề mặt da để tạo màu vàng óng ả căng bóng. Dùng dao sắc chặt miếng vuông vắn đều tăm tắp, xếp ra đĩa và rắc lá chanh thái chỉ mỏng như sợi tơ lên trên."}]', 'Công thức vàng: ''Luộc 15 phút lửa nhỏ - Tắt bếp ngâm ủ 15 phút - Sốc nhiệt nước đá 5 phút'' đảm bảo 100% da gà căng bóng giòn rụm nguyên vẹn, thịt chín mọng nước không bao giờ bị đỏ xương.', '{"calo":340,"protein":"38g","chat_beo":"18g","carb":"0g"}', '["Món cỗ truyền thống","Thanh đạm","Giòn ngọt","Giàu protein"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (19, 'Thịt bò áp chảo', 'Thịt thăn bò tươi (Tenderloin / Ribeye) (400 g), Bơ lạt động vật Anchor (30 g), Tỏi khô ta nguyên tép (1 củ), Nhánh hương thảo tươi (Rosemary) (2 nhánh), Muối biển hạt thô & Tiêu đen xay (1 thìa), Dầu ô liu nguyên chất (1.5 muỗng canh)', '[Bước 1: Đưa thịt về nhiệt độ phòng & Thấm khô tuyệt đối - ⏱️ 10 phút]
Lấy miếng thăn bò ra khỏi tủ lạnh trước 15 - 20 phút để thịt đạt nhiệt độ phòng (nếu áp chảo khi thịt còn lạnh, tâm thịt sẽ bị nguội sống mà vỏ ngoài đã cháy). Dùng khăn giấy chuyên dụng dặm thật khô bề mặt miếng thịt. Rắc muối biển hạt thô và tiêu đen xay thô đều lên cả hai mặt thịt ngay trước khi cho vào chảo (không rắc muối quá sớm sẽ làm thịt chảy nước).

[Bước 2: Áp chảo tạo lớp vỏ caramel nâu giòn (Sear) - ⏱️ 4 phút]
Đặt chảo gang dày lên bếp đun thật nóng với 1 muỗng dầu ô liu đến khi bốc khói nhẹ. Cẩn thận đặt miếng bò vào chảo. Giữ nguyên không xê dịch miếng thịt trong 2 phút ở lửa lớn để phản ứng Maillard tạo lớp vỏ ngoài nâu vàng caramel giòn thơm. Lật mặt miếng thịt và áp chảo tiếp tục trong 2 phút.

[Bước 3: Kỹ thuật rưới bơ tỏi thơm ngậy (Basting) - ⏱️ 2 phút]
Hạ lửa xuống mức vừa, thả 30g bơ lạt, các tép tỏi đập dập và nhánh rosemary vào chảo. Bơ sẽ nhanh chóng tan chảy sủi bọt thơm lừng. Nghiêng chảo một góc 30 độ, dùng thìa lớn liên tục múc bơ tan chảy nóng rưới đều khắp bề mặt miếng thịt trong 60 - 90 giây để thịt chín đều và thẩm thấu trọn vẹn hương thơm ngậy của bơ tỏi thảo mộc.

[Bước 4: Kỹ thuật nghỉ thịt (Resting) khóa trọn nước ngọt - ⏱️ 6 phút]
Gắp miếng thịt bò ra thớt gỗ hoặc đĩa ấm, để thịt nghỉ yên tĩnh trong đúng 5 - 7 phút (tuyệt đối không cắt ngay). Trong thời gian nghỉ, các sợi cơ thịt thư giãn và nước ngọt cốt tủy sẽ phân bổ ngược lại đều khắp miếng thịt. Dùng dao sắc thái lát dày 0.8cm xéo thớ, rắc chút muối tiêu thưởng thức cùng khoai tây nghiền và măng tây.

💡 Mẹo đầu bếp: Quy tắc bất di bất dịch của bít tết hảo hạng: Bắt buộc phải để thịt nghỉ 5 phút sau khi áp chảo trước khi cắt; nếu cắt ngay lập tức toàn bộ nước ngọt màu hồng quý giá bên trong sẽ tuôn sạch ra ngoài thớt khiến miếng thịt khô bã nguội lạnh.', '1786037034911.webp', 'Món mặn', 'Thăn bò áp chảo mềm ngọt mọng nước tan ngay trên đầu lưỡi, thơm ngậy bơ tỏi và hương thảo mộc tinh tế phong cách bít tết hảo hạng.', 'Trung bình', '2 - 3 người', 10, 8, '[{"ten":"Thịt thăn bò tươi (Tenderloin / Ribeye)","so_luong":400,"don_vi":"g","ghi_chu":"cắt tảng dày 2.5 - 3cm, vân mỡ đều"},{"ten":"Bơ lạt động vật Anchor","so_luong":30,"don_vi":"g","ghi_chu":"tạo mùi thơm béo ngậy"},{"ten":"Tỏi khô ta nguyên tép","so_luong":1,"don_vi":"củ","ghi_chu":"đập dập nhẹ cả vỏ"},{"ten":"Nhánh hương thảo tươi (Rosemary)","so_luong":2,"don_vi":"nhánh","ghi_chu":"tinh dầu thơm quyến rũ"},{"ten":"Muối biển hạt thô & Tiêu đen xay","so_luong":1,"don_vi":"thìa","ghi_chu":"nêm ngay trước khi áp chảo"},{"ten":"Dầu ô liu nguyên chất","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"chịu nhiệt áp chảo"}]', '[{"buoc":1,"tieu_de":"Đưa thịt về nhiệt độ phòng & Thấm khô tuyệt đối","thoi_gian":"10 phút","noi_dung":"Lấy miếng thăn bò ra khỏi tủ lạnh trước 15 - 20 phút để thịt đạt nhiệt độ phòng (nếu áp chảo khi thịt còn lạnh, tâm thịt sẽ bị nguội sống mà vỏ ngoài đã cháy). Dùng khăn giấy chuyên dụng dặm thật khô bề mặt miếng thịt. Rắc muối biển hạt thô và tiêu đen xay thô đều lên cả hai mặt thịt ngay trước khi cho vào chảo (không rắc muối quá sớm sẽ làm thịt chảy nước)."},{"buoc":2,"tieu_de":"Áp chảo tạo lớp vỏ caramel nâu giòn (Sear)","thoi_gian":"4 phút","noi_dung":"Đặt chảo gang dày lên bếp đun thật nóng với 1 muỗng dầu ô liu đến khi bốc khói nhẹ. Cẩn thận đặt miếng bò vào chảo. Giữ nguyên không xê dịch miếng thịt trong 2 phút ở lửa lớn để phản ứng Maillard tạo lớp vỏ ngoài nâu vàng caramel giòn thơm. Lật mặt miếng thịt và áp chảo tiếp tục trong 2 phút."},{"buoc":3,"tieu_de":"Kỹ thuật rưới bơ tỏi thơm ngậy (Basting)","thoi_gian":"2 phút","noi_dung":"Hạ lửa xuống mức vừa, thả 30g bơ lạt, các tép tỏi đập dập và nhánh rosemary vào chảo. Bơ sẽ nhanh chóng tan chảy sủi bọt thơm lừng. Nghiêng chảo một góc 30 độ, dùng thìa lớn liên tục múc bơ tan chảy nóng rưới đều khắp bề mặt miếng thịt trong 60 - 90 giây để thịt chín đều và thẩm thấu trọn vẹn hương thơm ngậy của bơ tỏi thảo mộc."},{"buoc":4,"tieu_de":"Kỹ thuật nghỉ thịt (Resting) khóa trọn nước ngọt","thoi_gian":"6 phút","noi_dung":"Gắp miếng thịt bò ra thớt gỗ hoặc đĩa ấm, để thịt nghỉ yên tĩnh trong đúng 5 - 7 phút (tuyệt đối không cắt ngay). Trong thời gian nghỉ, các sợi cơ thịt thư giãn và nước ngọt cốt tủy sẽ phân bổ ngược lại đều khắp miếng thịt. Dùng dao sắc thái lát dày 0.8cm xéo thớ, rắc chút muối tiêu thưởng thức cùng khoai tây nghiền và măng tây."}]', 'Quy tắc bất di bất dịch của bít tết hảo hạng: Bắt buộc phải để thịt nghỉ 5 phút sau khi áp chảo trước khi cắt; nếu cắt ngay lập tức toàn bộ nước ngọt màu hồng quý giá bên trong sẽ tuôn sạch ra ngoài thớt khiến miếng thịt khô bã nguội lạnh.', '{"calo":420,"protein":"36g","chat_beo":"28g","carb":"1g"}', '["Bít tết thơm ngon","Mọng nước","Phong cách Tây","Bổ máu giàu kẽm"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (20, 'Cá sốt cà chua', 'Cá điêu hồng tươi (hoặc cá chép) (700 g), Cà chua chín đỏ mọng (3 quả), Hành tím & Tỏi băm (2 củ), Thì là & Hành hoa tươi (50 g), Nước mắm ngon & Đường (2 muỗng canh), Dầu ăn chiên cá (150 ml)', '[Bước 1: Khử tanh cá & Khía chéo thân - ⏱️ 10 phút]
Cá mổ sạch ruột, cạo sạch màng đen trong bụng, xát muối hạt và chanh rửa sạch nhớt. Dùng khăn sạch lau khô hoàn toàn cả trong lẫn ngoài thân cá (lau khô giúp khi rán không bị bắn dầu và da cá giòn rụm). Khía 3 đường chéo trên mỗi mặt thân cá sâu chạm tới xương để cá nhanh chín và dễ thấm sốt.

[Bước 2: Chiên cá vàng giòn hai mặt - ⏱️ 10 phút]
Đun chảo dầu nóng già ở lửa vừa (thử đầu đũa sủi bọt tăm lăn tăn). Rắc một nhúm bột bắp nhỏ vào chảo để chống bắn dầu. Nhẹ nhàng thả cá vào chiên trong 5 - 6 phút cho mặt dưới se cứng vàng ruộm thì mới lật mặt chiên tiếp 4 - 5 phút cho mặt còn lại chín giòn đều. Vớt cá ra đĩa để ráo dầu.

[Bước 3: Nấu sốt cà chua thì là sánh mịn - ⏱️ 5 phút]
Chắt bớt dầu trong chảo, cho hành tỏi băm vào phi thơm vàng. Trút cà chua thái hạt lựu vào xào đều tay trên lửa vừa, nêm 2 muỗng nước mắm, 1 muỗng đường, 1/2 muỗng hạt nêm và nửa bát nước lọc nóng. Dùng muôi dằm nhuyễn cà chua cho tan mịn thành hỗn hợp sốt đỏ sánh đặc sủi bọt.

[Bước 4: Om cá ngấm sốt & Bày đĩa - ⏱️ 5 phút]
Đặt cá đã chiên vào chảo sốt cà chua, dùng muôi múc nước sốt rưới đều lên mình cá liên tục trong 3 - 4 phút ở lửa nhỏ cho thớ cá ngấm vị chua ngọt đậm đà. Rải đều hành hoa và thì là cắt khúc lên trên cá, đun thêm 30 giây cho rau thơm chín tái dậy mùi ngào ngạt rồi tắt bếp, trút ra đĩa sâu lòng.

💡 Mẹo đầu bếp: Tuyệt đối không lật cá khi mặt dưới chưa chín vàng cứng; lật cá quá sớm sẽ làm da cá bị rách nát dính chặt vào chảo.', '1786037051142.webp', 'Món mặn', 'Cá chiên vàng giòn rụm lớp vảy bên ngoài, thịt cá trắng ngọt ngào ngấm đượm sốt cà chua đỏ tươi sánh sệt và thì là ngát hương thơm.', 'Dễ', '3 - 4 người', 15, 20, '[{"ten":"Cá điêu hồng tươi (hoặc cá chép)","so_luong":700,"don_vi":"g","ghi_chu":"đánh vảy mổ sạch, khía chéo thân"},{"ten":"Cà chua chín đỏ mọng","so_luong":3,"don_vi":"quả","ghi_chu":"thái hạt lựu nhỏ"},{"ten":"Hành tím & Tỏi băm","so_luong":2,"don_vi":"củ","ghi_chu":"phi thơm"},{"ten":"Thì là & Hành hoa tươi","so_luong":50,"don_vi":"g","ghi_chu":"cắt khúc 3cm"},{"ten":"Nước mắm ngon & Đường","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"nêm nước sốt"},{"ten":"Dầu ăn chiên cá","so_luong":150,"don_vi":"ml","ghi_chu":"chiên giòn đều mặt"}]', '[{"buoc":1,"tieu_de":"Khử tanh cá & Khía chéo thân","thoi_gian":"10 phút","noi_dung":"Cá mổ sạch ruột, cạo sạch màng đen trong bụng, xát muối hạt và chanh rửa sạch nhớt. Dùng khăn sạch lau khô hoàn toàn cả trong lẫn ngoài thân cá (lau khô giúp khi rán không bị bắn dầu và da cá giòn rụm). Khía 3 đường chéo trên mỗi mặt thân cá sâu chạm tới xương để cá nhanh chín và dễ thấm sốt."},{"buoc":2,"tieu_de":"Chiên cá vàng giòn hai mặt","thoi_gian":"10 phút","noi_dung":"Đun chảo dầu nóng già ở lửa vừa (thử đầu đũa sủi bọt tăm lăn tăn). Rắc một nhúm bột bắp nhỏ vào chảo để chống bắn dầu. Nhẹ nhàng thả cá vào chiên trong 5 - 6 phút cho mặt dưới se cứng vàng ruộm thì mới lật mặt chiên tiếp 4 - 5 phút cho mặt còn lại chín giòn đều. Vớt cá ra đĩa để ráo dầu."},{"buoc":3,"tieu_de":"Nấu sốt cà chua thì là sánh mịn","thoi_gian":"5 phút","noi_dung":"Chắt bớt dầu trong chảo, cho hành tỏi băm vào phi thơm vàng. Trút cà chua thái hạt lựu vào xào đều tay trên lửa vừa, nêm 2 muỗng nước mắm, 1 muỗng đường, 1/2 muỗng hạt nêm và nửa bát nước lọc nóng. Dùng muôi dằm nhuyễn cà chua cho tan mịn thành hỗn hợp sốt đỏ sánh đặc sủi bọt."},{"buoc":4,"tieu_de":"Om cá ngấm sốt & Bày đĩa","thoi_gian":"5 phút","noi_dung":"Đặt cá đã chiên vào chảo sốt cà chua, dùng muôi múc nước sốt rưới đều lên mình cá liên tục trong 3 - 4 phút ở lửa nhỏ cho thớ cá ngấm vị chua ngọt đậm đà. Rải đều hành hoa và thì là cắt khúc lên trên cá, đun thêm 30 giây cho rau thơm chín tái dậy mùi ngào ngạt rồi tắt bếp, trút ra đĩa sâu lòng."}]', 'Tuyệt đối không lật cá khi mặt dưới chưa chín vàng cứng; lật cá quá sớm sẽ làm da cá bị rách nát dính chặt vào chảo.', '{"calo":350,"protein":"34g","chat_beo":"16g","carb":"8g"}', '["Món cá đưa cơm","Chua thanh dịu","Món ăn gia đình","Giàu Omega-3"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (21, 'Vịt nấu chao', 'Thịt vịt xiêm tươi béo (1 kg), Chao trắng & Chao đỏ (1 hũ nhỏ (~6 viên)), Khoai môn cao (khoai sáp) (400 g), Nước dừa xiêm tươi (600 ml), Sả cây, gừng già, tỏi, ớt (4 cây/củ), Bún tươi & Rau muống non (1 set)', '[Bước 1: Khử hôi lông vịt triệt để bằng rượu gừng - ⏱️ 15 phút]
Cắt bỏ phao câu vịt (nguyên nhân gây hôi hàng đầu). Giã nát 1 củ gừng trộn cùng nửa bát rượu trắng, chà xát thật mạnh tay lên khắp mình vịt trong 5 phút từ trong ra ngoài. Rửa lại thật sạch với nước lạnh rồi để ráo. Dùng dao chặt thịt vịt thành các miếng vuông vừa ăn khoảng 3.5 x 3.5cm.

[Bước 2: Ướp vịt đậm đà với cốt chao béo ngậy - ⏱️ 40 phút]
Dùng thìa tán nhuyễn 4 viên chao trắng, 2 viên chao đỏ cùng 3 thìa canh nước chao. Trộn cùng 1.5 muỗng đường, 1 muỗng hạt nêm, sả băm, tỏi ớt băm và 1 thìa dầu hào. Ướp đều vào thịt vịt, dùng tay bóp nhẹ cho ngấm sâu và để thịt nghỉ trong ít nhất 40 phút.

[Bước 3: Chiên sơ khoai môn giữ độ bở nguyên khối - ⏱️ 8 phút]
Khoai môn gọt vỏ (đeo găng tay tránh ngứa), cắt thành các khối vuông dày 3cm. Đun nóng chảo dầu ở lửa vừa, thả khoai môn vào chiên sơ trong 3 - 4 phút đến khi mặt ngoài se cứng hanh vàng thì vớt ra để ráo (chiên khoai giúp khoai khi hầm không bị tan rã làm đục nước lẩu mà vẫn bùi dẻo nguyên miếng).

[Bước 4: Xào săn vịt & Hầm nước dừa tươi - ⏱️ 30 phút]
Bắc nồi lên bếp, phi thơm sả đập dập với chút dầu ăn. Trút toàn bộ thịt vịt đã ướp vào xào đảo lửa lớn trong 8 - 10 phút cho mỡ vịt tứa ra và thịt săn chắc lại ngấm đều vị chao thơm lừng. Đổ 600ml nước dừa xiêm tươi vào ngập mặt thịt. Đun sôi bùng lên, hớt sạch bọt rồi hạ lửa nhỏ hầm trong 25 phút cho thịt vịt mềm nhừ.

[Bước 5: Thêm khoai môn & Thưởng thức dạng lẩu - ⏱️ 15 phút]
Thả khoai môn đã chiên vào nồi nấu chung thêm 12 - 15 phút cho khoai chín bở bùi sánh ngậy nước dùng. Nếm lại gia vị cho vừa miệng. Đặt nồi lên bếp lẩu mini tại bàn ăn, nhúng rau muống non, cải bẹ xanh và ăn kèm bún tươi cùng chén nước chấm chao pha đường tỏi ớt.

💡 Mẹo đầu bếp: Chiên sơ khoai môn trước khi hầm là bí quyết giúp nước dùng vịt nấu chao luôn trong và sánh mịn tự nhiên, khoai bở bùi không bao giờ bị nát vụn làm đục nồi lẩu.', '1786037065573.webp', 'Món mặn', 'Đặc sản miền Tây Nam Bộ danh tiếng với thịt vịt béo mềm thơm lừng ngấm vị béo bùi của chao đỏ trắng, khoai môn dẻo bùi sánh ngậy nước dùng dừa tươi ngọt thanh.', 'Khó', '4 - 5 người', 30, 45, '[{"ten":"Thịt vịt xiêm tươi béo","so_luong":1,"don_vi":"kg","ghi_chu":"chặt miếng dày 3.5cm"},{"ten":"Chao trắng & Chao đỏ","so_luong":1,"don_vi":"hũ nhỏ (~6 viên)","ghi_chu":"tán nhuyễn lấy cả nước chao"},{"ten":"Khoai môn cao (khoai sáp)","so_luong":400,"don_vi":"g","ghi_chu":"gọt vỏ cắt khối chiên sơ"},{"ten":"Nước dừa xiêm tươi","so_luong":600,"don_vi":"ml","ghi_chu":"nước ngọt thanh tự nhiên"},{"ten":"Sả cây, gừng già, tỏi, ớt","so_luong":4,"don_vi":"cây/củ","ghi_chu":"đập dập băm nhuyễn"},{"ten":"Bún tươi & Rau muống non","so_luong":1,"don_vi":"set","ghi_chu":"nhúng lẩu ăn kèm"}]', '[{"buoc":1,"tieu_de":"Khử hôi lông vịt triệt để bằng rượu gừng","thoi_gian":"15 phút","noi_dung":"Cắt bỏ phao câu vịt (nguyên nhân gây hôi hàng đầu). Giã nát 1 củ gừng trộn cùng nửa bát rượu trắng, chà xát thật mạnh tay lên khắp mình vịt trong 5 phút từ trong ra ngoài. Rửa lại thật sạch với nước lạnh rồi để ráo. Dùng dao chặt thịt vịt thành các miếng vuông vừa ăn khoảng 3.5 x 3.5cm."},{"buoc":2,"tieu_de":"Ướp vịt đậm đà với cốt chao béo ngậy","thoi_gian":"40 phút","noi_dung":"Dùng thìa tán nhuyễn 4 viên chao trắng, 2 viên chao đỏ cùng 3 thìa canh nước chao. Trộn cùng 1.5 muỗng đường, 1 muỗng hạt nêm, sả băm, tỏi ớt băm và 1 thìa dầu hào. Ướp đều vào thịt vịt, dùng tay bóp nhẹ cho ngấm sâu và để thịt nghỉ trong ít nhất 40 phút."},{"buoc":3,"tieu_de":"Chiên sơ khoai môn giữ độ bở nguyên khối","thoi_gian":"8 phút","noi_dung":"Khoai môn gọt vỏ (đeo găng tay tránh ngứa), cắt thành các khối vuông dày 3cm. Đun nóng chảo dầu ở lửa vừa, thả khoai môn vào chiên sơ trong 3 - 4 phút đến khi mặt ngoài se cứng hanh vàng thì vớt ra để ráo (chiên khoai giúp khoai khi hầm không bị tan rã làm đục nước lẩu mà vẫn bùi dẻo nguyên miếng)."},{"buoc":4,"tieu_de":"Xào săn vịt & Hầm nước dừa tươi","thoi_gian":"30 phút","noi_dung":"Bắc nồi lên bếp, phi thơm sả đập dập với chút dầu ăn. Trút toàn bộ thịt vịt đã ướp vào xào đảo lửa lớn trong 8 - 10 phút cho mỡ vịt tứa ra và thịt săn chắc lại ngấm đều vị chao thơm lừng. Đổ 600ml nước dừa xiêm tươi vào ngập mặt thịt. Đun sôi bùng lên, hớt sạch bọt rồi hạ lửa nhỏ hầm trong 25 phút cho thịt vịt mềm nhừ."},{"buoc":5,"tieu_de":"Thêm khoai môn & Thưởng thức dạng lẩu","thoi_gian":"15 phút","noi_dung":"Thả khoai môn đã chiên vào nồi nấu chung thêm 12 - 15 phút cho khoai chín bở bùi sánh ngậy nước dùng. Nếm lại gia vị cho vừa miệng. Đặt nồi lên bếp lẩu mini tại bàn ăn, nhúng rau muống non, cải bẹ xanh và ăn kèm bún tươi cùng chén nước chấm chao pha đường tỏi ớt."}]', 'Chiên sơ khoai môn trước khi hầm là bí quyết giúp nước dùng vịt nấu chao luôn trong và sánh mịn tự nhiên, khoai bở bùi không bao giờ bị nát vụn làm đục nồi lẩu.', '{"calo":560,"protein":"38g","chat_beo":"36g","carb":"24g"}', '["Đặc sản miền Tây","Món lẩu tụ họp","Béo bùi ngậy vị","Cuối tuần sum họp"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (22, 'Giò lụa kho tiêu', 'Giò lụa (chả lụa) tươi ngon (300 g), Tiêu xanh tươi (hoặc tiêu sọ) (2 nhánh), Hành tím khô (2 củ), Nước mắm ngon cốt truyền thống (1.5 muỗng canh), Đường vàng & Nước màu (1 muỗng canh mỗi loại), Hành hoa & Ớt sừng (1 nhánh)', '[Bước 1: Thái giò lụa thanh con chì - ⏱️ 3 phút]
Giò lụa bóc sạch lá chuối, dùng dao sắc thái thành các thanh con chì dài khoảng 4cm và dày 1.5cm (thái thanh con chì giúp giò thấm sốt đều và khi rim không bị teo khô).

[Bước 2: Áp chảo se vàng miếng giò - ⏱️ 3 phút]
Đặt chảo lên bếp với 1 thìa dầu ăn, cho các thanh giò lụa vào đảo nhẹ trên lửa vừa trong 2 - 3 phút cho các mặt giò hơi se vàng nhạt và dậy mùi thơm đặc trưng của giò rán.

[Bước 3: Nấu sốt tiêu xanh đậm đà - ⏱️ 2 phút]
Gạt giò sang bên mép chảo, cho hành tím và các nhánh tiêu xanh đập dập vào phi thơm trong 20 giây cho tỏa hương thơm nồng. Hòa tan hỗn hợp gồm 1.5 muỗng nước mắm, 1 muỗng đường, 1 muỗng nước màu và 3 muỗng nước sôi nóng rồi rưới vào chảo.

[Bước 4: Rim kẹo sền sệt & Thưởng thức - ⏱️ 2 phút]
Hạ lửa vừa, đảo đều tay liên tục trong 2 - 3 phút để nước sốt mắm tiêu keo sánh lại, ôm một lớp caramel cay mặn óng ánh quanh từng miếng giò lụa. Rắc hành hoa cắt khúc và chút tiêu xay rồi tắt bếp, múc ra đĩa ăn nóng cùng cơm trắng.

💡 Mẹo đầu bếp: Giò lụa vốn đã có độ mặn sẵn, nên khi nêm nước mắm cần cân đối lượng đường vừa phải để nước kho có vị mặn ngọt hài hòa keo bóng mà không bị mặn gắt.', '1786037078146.webp', 'Món mặn', 'Từng miếng giò lụa dai giòn được rim săn đượm nước mắm nhĩ và tiêu xanh tươi cay nồng nàn, món mặn siêu tốc đưa cơm giải ngấy sau lễ Tết.', 'Dễ', '3 người', 5, 10, '[{"ten":"Giò lụa (chả lụa) tươi ngon","so_luong":300,"don_vi":"g","ghi_chu":"cắt thanh con chì dài 4cm dày 1.5cm"},{"ten":"Tiêu xanh tươi (hoặc tiêu sọ)","so_luong":2,"don_vi":"nhánh","ghi_chu":"đập dập nhẹ lấy tinh dầu"},{"ten":"Hành tím khô","so_luong":2,"don_vi":"củ","ghi_chu":"thái lát mỏng"},{"ten":"Nước mắm ngon cốt truyền thống","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"độ đạm cao"},{"ten":"Đường vàng & Nước màu","so_luong":1,"don_vi":"muỗng canh mỗi loại","ghi_chu":"tạo vị kẹo ngọt óng ả"},{"ten":"Hành hoa & Ớt sừng","so_luong":1,"don_vi":"nhánh","ghi_chu":"trang trí"}]', '[{"buoc":1,"tieu_de":"Thái giò lụa thanh con chì","thoi_gian":"3 phút","noi_dung":"Giò lụa bóc sạch lá chuối, dùng dao sắc thái thành các thanh con chì dài khoảng 4cm và dày 1.5cm (thái thanh con chì giúp giò thấm sốt đều và khi rim không bị teo khô)."},{"buoc":2,"tieu_de":"Áp chảo se vàng miếng giò","thoi_gian":"3 phút","noi_dung":"Đặt chảo lên bếp với 1 thìa dầu ăn, cho các thanh giò lụa vào đảo nhẹ trên lửa vừa trong 2 - 3 phút cho các mặt giò hơi se vàng nhạt và dậy mùi thơm đặc trưng của giò rán."},{"buoc":3,"tieu_de":"Nấu sốt tiêu xanh đậm đà","thoi_gian":"2 phút","noi_dung":"Gạt giò sang bên mép chảo, cho hành tím và các nhánh tiêu xanh đập dập vào phi thơm trong 20 giây cho tỏa hương thơm nồng. Hòa tan hỗn hợp gồm 1.5 muỗng nước mắm, 1 muỗng đường, 1 muỗng nước màu và 3 muỗng nước sôi nóng rồi rưới vào chảo."},{"buoc":4,"tieu_de":"Rim kẹo sền sệt & Thưởng thức","thoi_gian":"2 phút","noi_dung":"Hạ lửa vừa, đảo đều tay liên tục trong 2 - 3 phút để nước sốt mắm tiêu keo sánh lại, ôm một lớp caramel cay mặn óng ánh quanh từng miếng giò lụa. Rắc hành hoa cắt khúc và chút tiêu xay rồi tắt bếp, múc ra đĩa ăn nóng cùng cơm trắng."}]', 'Giò lụa vốn đã có độ mặn sẵn, nên khi nêm nước mắm cần cân đối lượng đường vừa phải để nước kho có vị mặn ngọt hài hòa keo bóng mà không bị mặn gắt.', '{"calo":310,"protein":"22g","chat_beo":"21g","carb":"6g"}', '["Nhanh gọn lẹ","Vét sạch nồi cơm","Món mặn dân dã","Tiêu xanh nồng ấm"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (23, 'Thịt băm viên sốt cà chua', 'Thịt nạc vai heo xay nhuyễn (350 g), Cà chua chín đỏ mọng (3 quả), Lòng trắng trứng gà (1 cái), Hành tím & Hành hoa (3 nhánh), Nước mắm & Đường (1.5 muỗng canh)', '[Bước 1: Quết thịt & Vo viên tròn mềm mọng - ⏱️ 10 phút]
Cho thịt xay vào tô cùng 1 lòng trắng trứng gà, 1 thìa hành tím băm, 1 thìa cà phê nước mắm, 1 thìa cà phê hạt nêm, 1/2 thìa tiêu và 1 thìa dầu ăn. Dùng thìa quết đều tay theo một chiều trong 3 phút để thịt dẻo dính. Thoa chút dầu ăn vào lòng bàn tay, ngắt từng phần thịt vo tròn thành các viên cỡ quả bóng bàn (khoảng 3cm).

[Bước 2: Rán sơ định hình viên thịt tròn xoe - ⏱️ 5 phút]
Đặt chảo lên bếp với 2 thìa dầu ăn ở lửa vừa. Nhẹ nhàng thả các viên thịt vào lăn đều trong 3 - 4 phút cho bề mặt thịt săn chắc định hình, hơi ngả vàng nhạt lớp vỏ ngoài (không rán kỹ làm khô thịt) rồi gắp ra đĩa riêng.

[Bước 3: Nấu sốt cà chua nhuyễn sánh - ⏱️ 4 phút]
Tận dụng chảo dầu, phi thơm hành tím băm rồi cho cà chua thái hạt lựu vào đảo nhuyễn. Nêm 1.5 muỗng nước mắm, 1 muỗng đường, 1/2 muỗng hạt nêm và nửa chén nước nóng. Đun lửa vừa dằm nhuyễn đến khi cà chua tan mịn thành sốt sánh đặc đỏ au.

[Bước 4: Om thịt viên đẫm sốt - ⏱️ 6 phút]
Thả các viên thịt vào chảo sốt cà chua, dùng thìa múc sốt rưới đều lên từng viên thịt. Đậy vung om nhỏ lửa liu riu trong 6 - 8 phút cho thịt chín thấu bên trong và ngấm vị chua ngọt của sốt. Mở vung, rắc hành hoa thái nhỏ tiêu xay rồi tắt bếp.

💡 Mẹo đầu bếp: Thêm 1 lòng trắng trứng và 1 thìa dầu ăn khi quết thịt băm sẽ giúp viên thịt sau khi rim sốt giữ trọn độ ẩm mọng, xốp mềm tan trong miệng mà không bị khô xơ.', '1786037093221.webp', 'Món mặn', 'Những viên thịt băm tròn trịa mềm mọng ngọt béo đậm đà kết hợp với nước sốt cà chua chua ngọt sánh mịn, món ăn khoái khẩu của cả người lớn lẫn trẻ nhỏ.', 'Dễ', '3 - 4 người', 15, 15, '[{"ten":"Thịt nạc vai heo xay nhuyễn","so_luong":350,"don_vi":"g","ghi_chu":"có mỡ nhẹ để viên thịt mềm không khô"},{"ten":"Cà chua chín đỏ mọng","so_luong":3,"don_vi":"quả","ghi_chu":"bỏ hạt thái hạt lựu nhỏ"},{"ten":"Lòng trắng trứng gà","so_luong":1,"don_vi":"cái","ghi_chu":"giúp viên thịt kết dính xốp mềm"},{"ten":"Hành tím & Hành hoa","so_luong":3,"don_vi":"nhánh","ghi_chu":"băm nhỏ"},{"ten":"Nước mắm & Đường","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"nêm vừa miệng"}]', '[{"buoc":1,"tieu_de":"Quết thịt & Vo viên tròn mềm mọng","thoi_gian":"10 phút","noi_dung":"Cho thịt xay vào tô cùng 1 lòng trắng trứng gà, 1 thìa hành tím băm, 1 thìa cà phê nước mắm, 1 thìa cà phê hạt nêm, 1/2 thìa tiêu và 1 thìa dầu ăn. Dùng thìa quết đều tay theo một chiều trong 3 phút để thịt dẻo dính. Thoa chút dầu ăn vào lòng bàn tay, ngắt từng phần thịt vo tròn thành các viên cỡ quả bóng bàn (khoảng 3cm)."},{"buoc":2,"tieu_de":"Rán sơ định hình viên thịt tròn xoe","thoi_gian":"5 phút","noi_dung":"Đặt chảo lên bếp với 2 thìa dầu ăn ở lửa vừa. Nhẹ nhàng thả các viên thịt vào lăn đều trong 3 - 4 phút cho bề mặt thịt săn chắc định hình, hơi ngả vàng nhạt lớp vỏ ngoài (không rán kỹ làm khô thịt) rồi gắp ra đĩa riêng."},{"buoc":3,"tieu_de":"Nấu sốt cà chua nhuyễn sánh","thoi_gian":"4 phút","noi_dung":"Tận dụng chảo dầu, phi thơm hành tím băm rồi cho cà chua thái hạt lựu vào đảo nhuyễn. Nêm 1.5 muỗng nước mắm, 1 muỗng đường, 1/2 muỗng hạt nêm và nửa chén nước nóng. Đun lửa vừa dằm nhuyễn đến khi cà chua tan mịn thành sốt sánh đặc đỏ au."},{"buoc":4,"tieu_de":"Om thịt viên đẫm sốt","thoi_gian":"6 phút","noi_dung":"Thả các viên thịt vào chảo sốt cà chua, dùng thìa múc sốt rưới đều lên từng viên thịt. Đậy vung om nhỏ lửa liu riu trong 6 - 8 phút cho thịt chín thấu bên trong và ngấm vị chua ngọt của sốt. Mở vung, rắc hành hoa thái nhỏ tiêu xay rồi tắt bếp."}]', 'Thêm 1 lòng trắng trứng và 1 thìa dầu ăn khi quết thịt băm sẽ giúp viên thịt sau khi rim sốt giữ trọn độ ẩm mọng, xốp mềm tan trong miệng mà không bị khô xơ.', '{"calo":360,"protein":"27g","chat_beo":"24g","carb":"11g"}', '["Trẻ nhỏ yêu thích","Dễ ăn","Món cơm gia đình","Chua ngọt thơm mềm"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (24, 'Canh chua cá lóc', 'Cá lóc đồng tươi (600 g), Dứa (thơm) & Cà chua (0.5 quả / 2 quả), Dọc mùng (bạc hà) & Đậu bắp (150 g), Giá đỗ sạch & Me chua chín (100 g / 40g me), Ngò om (rau ngổ) & Ngò gai (1 mớ nhỏ), Tỏi phi vàng giòn & Ớt tươi (1 muỗng canh)', '[Bước 1: Sơ chế cá lóc & Tước dọc mùng không ngứa - ⏱️ 10 phút]
Cá lóc mổ sạch màng đen bụng, xát muối chanh khử nhớt, cắt khúc 3cm để ráo. Dọc mùng tước sạch lớp vỏ xơ bên ngoài, thái vát xéo dày 1cm rồi bóp kỹ với 1 thìa muối hạt trong 3 phút, rửa xả lại 3 lần nước lạnh rồi dùng tay vắt thật kiệt nước (bóp muối và vắt ráo giúp dọc mùng giòn tan và tuyệt đối không ngứa cổ họng). Đậu bắp cắt xéo, dứa thái lát, cà chua bổ múi cau.

[Bước 2: Nấu nước dùng chua ngọt chuẩn vị Nam Bộ - ⏱️ 5 phút]
Cho vắt me vào chén múc nước sôi dầm nát lọc lấy nước cốt chua. Đun sôi 1.2 lít nước trên bếp. Nêm vào nồi nước dùng: nước cốt me, 2 muỗng canh nước mắm ngon, 2 muỗng canh đường cát và 1 thìa hạt nêm (canh chua Nam Bộ đặc trưng bởi vị chua thanh dịu đi liền với vị ngọt hậu đậm đà).

[Bước 3: Nấu chín tới cá lóc ngọt thịt - ⏱️ 7 phút]
Khi nước canh sôi bùng sùng sục, thả từng khúc cá lóc vào nồi. Nấu ở lửa vừa trong 6 - 8 phút cho thịt cá vừa chín tới trắng ngần. Dùng muôi thủng nhẹ nhàng vớt các khúc cá ra đĩa riêng (vớt cá ra riêng giúp cá không bị nát nhừ khi cho rau củ vào đun).

[Bước 4: Nấu rau củ giòn & Bày tô hoàn thiện - ⏱️ 3 phút]
Cho dứa, cà chua, đậu bắp và dọc mùng vào nồi nước canh đang sôi, đun trong 2 phút cho rau củ vừa chín giòn. Thêm giá đỗ vào đun sôi bùng lại 30 giây rồi tắt bếp. Múc rau củ và nước canh ra tô lớn, đặt các khúc cá lóc lên trên mặt, rắc ngò om, ngò gai thái nhỏ, vài lát ớt chỉ thiên và muỗng tỏi phi vàng thơm lừng lên trên.

💡 Mẹo đầu bếp: Rau ngổ (ngò om) và tỏi phi vàng ruộm là hai nguyên liệu bắt buộc tạo nên hương vị canh chua cá lóc đặc trưng chuẩn vị miền Tây; thiếu hai thứ này canh sẽ mất đi 50% độ thơm ngon.', '1786037110667.webp', 'Canh', 'Bát canh chua cá lóc chuẩn vị Nam Bộ thanh mát giải nhiệt, vị chua thanh từ me hòa quyện vị ngọt béo của cá lóc tươi và vị giòn thanh của dọc mùng, đậu bắp, giá đỗ ngào ngạt ngò om tỏi phi.', 'Trung bình', '4 người', 20, 20, '[{"ten":"Cá lóc đồng tươi","so_luong":600,"don_vi":"g","ghi_chu":"cắt khúc dày 3cm, khử sạch tanh"},{"ten":"Dứa (thơm) & Cà chua","so_luong":0.5,"don_vi":"quả / 2 quả","ghi_chu":"thái lát rẻ quạt và múi cau"},{"ten":"Dọc mùng (bạc hà) & Đậu bắp","so_luong":150,"don_vi":"g","ghi_chu":"tước vỏ, thái vát xéo"},{"ten":"Giá đỗ sạch & Me chua chín","so_luong":100,"don_vi":"g / 40g me","ghi_chu":"dầm me lấy nước cốt chua thanh"},{"ten":"Ngò om (rau ngổ) & Ngò gai","so_luong":1,"don_vi":"mớ nhỏ","ghi_chu":"linh hồn món canh chua"},{"ten":"Tỏi phi vàng giòn & Ớt tươi","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"rắc lên mặt tô canh"}]', '[{"buoc":1,"tieu_de":"Sơ chế cá lóc & Tước dọc mùng không ngứa","thoi_gian":"10 phút","noi_dung":"Cá lóc mổ sạch màng đen bụng, xát muối chanh khử nhớt, cắt khúc 3cm để ráo. Dọc mùng tước sạch lớp vỏ xơ bên ngoài, thái vát xéo dày 1cm rồi bóp kỹ với 1 thìa muối hạt trong 3 phút, rửa xả lại 3 lần nước lạnh rồi dùng tay vắt thật kiệt nước (bóp muối và vắt ráo giúp dọc mùng giòn tan và tuyệt đối không ngứa cổ họng). Đậu bắp cắt xéo, dứa thái lát, cà chua bổ múi cau."},{"buoc":2,"tieu_de":"Nấu nước dùng chua ngọt chuẩn vị Nam Bộ","thoi_gian":"5 phút","noi_dung":"Cho vắt me vào chén múc nước sôi dầm nát lọc lấy nước cốt chua. Đun sôi 1.2 lít nước trên bếp. Nêm vào nồi nước dùng: nước cốt me, 2 muỗng canh nước mắm ngon, 2 muỗng canh đường cát và 1 thìa hạt nêm (canh chua Nam Bộ đặc trưng bởi vị chua thanh dịu đi liền với vị ngọt hậu đậm đà)."},{"buoc":3,"tieu_de":"Nấu chín tới cá lóc ngọt thịt","thoi_gian":"7 phút","noi_dung":"Khi nước canh sôi bùng sùng sục, thả từng khúc cá lóc vào nồi. Nấu ở lửa vừa trong 6 - 8 phút cho thịt cá vừa chín tới trắng ngần. Dùng muôi thủng nhẹ nhàng vớt các khúc cá ra đĩa riêng (vớt cá ra riêng giúp cá không bị nát nhừ khi cho rau củ vào đun)."},{"buoc":4,"tieu_de":"Nấu rau củ giòn & Bày tô hoàn thiện","thoi_gian":"3 phút","noi_dung":"Cho dứa, cà chua, đậu bắp và dọc mùng vào nồi nước canh đang sôi, đun trong 2 phút cho rau củ vừa chín giòn. Thêm giá đỗ vào đun sôi bùng lại 30 giây rồi tắt bếp. Múc rau củ và nước canh ra tô lớn, đặt các khúc cá lóc lên trên mặt, rắc ngò om, ngò gai thái nhỏ, vài lát ớt chỉ thiên và muỗng tỏi phi vàng thơm lừng lên trên."}]', 'Rau ngổ (ngò om) và tỏi phi vàng ruộm là hai nguyên liệu bắt buộc tạo nên hương vị canh chua cá lóc đặc trưng chuẩn vị miền Tây; thiếu hai thứ này canh sẽ mất đi 50% độ thơm ngon.', '{"calo":280,"protein":"32g","chat_beo":"8g","carb":"18g"}', '["Canh thanh nhiệt","Đặc sản Nam Bộ","Chua ngọt hài hòa","Giàu dinh dưỡng"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (25, 'Canh rau ngót thịt băm', 'Rau ngót non tươi (1 bó (~300g)), Thịt heo nạc xay (150 g), Hành tím khô (1 củ), Nước mắm & Hạt nêm (1 muỗng canh)', '[Bước 1: Tuốt lá & Kỹ thuật vò rau ngót mềm mọng - ⏱️ 5 phút]
Tuốt lấy các lá ngót non và búp ngọn, bỏ cuống cứng. Rửa sạch rau với 2 lần nước muối loãng rồi vớt ra để ráo. Dùng hai lòng bàn tay vò nhẹ các nắm lá rau ngót cho hơi dập thớ gân (vò dập nhẹ giúp rau khi nấu nhanh chín mềm mướt, tiết trọn vị ngọt bùi và không bị rơm rác khi nuốt).

[Bước 2: Xào săn thịt băm đậm đà - ⏱️ 3 phút]
Đặt nồi lên bếp với 1 thìa dầu ăn, phi thơm hành tím băm đến khi dậy mùi thơm. Trút thịt xay vào xào đảo nhanh tay trên lửa vừa cùng 1 thìa cà phê nước mắm cho thịt săn chắc và dậy mùi thơm nức.

[Bước 3: Đun sôi nước dùng trong veo - ⏱️ 4 phút]
Đổ 1 lít nước lọc vào nồi thịt băm, bật lửa lớn đun sôi bùng lên. Dùng muôi vớt sạch lớp bọt trắng nổi bên trên để nước canh được trong veo và thanh vị.

[Bước 4: Nấu chín rau ngót & Hoàn thành - ⏱️ 3 phút]
Thả toàn bộ rau ngót đã vò vào nồi nước canh đang sôi sùng sục. Dùng đũa nhấn chìm rau xuống nước. Nêm thêm 1 thìa hạt nêm và chút muối cho vừa miệng. Đun sôi tiếp trong 2 - 3 phút cho rau chín mềm mượt mà vẫn giữ màu xanh mát rồi tắt bếp múc ra tô lớn.

💡 Mẹo đầu bếp: Vò nhẹ rau ngót trước khi nấu giúp rau mềm mượt và tiết ra trọn vẹn vị ngọt thanh mát, không bị dai cứng rơm rác khi ăn.', '1786037126752.webp', 'Canh', 'Bát canh ngọt mát lành thanh khiết với vị bùi bùi đặc trưng của rau ngót non tươi hòa quyện cùng vị ngọt thanh của thịt nạc băm, giải nhiệt tuyệt vời cho ngày hè.', 'Dễ', '3 - 4 người', 10, 10, '[{"ten":"Rau ngót non tươi","so_luong":1,"don_vi":"bó (~300g)","ghi_chu":"tuốt lá non, vò nhẹ cho mềm"},{"ten":"Thịt heo nạc xay","so_luong":150,"don_vi":"g","ghi_chu":"thịt tươi dẻo ướp chút gia vị"},{"ten":"Hành tím khô","so_luong":1,"don_vi":"củ","ghi_chu":"băm nhỏ phi thơm"},{"ten":"Nước mắm & Hạt nêm","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"nêm vừa thanh mát"}]', '[{"buoc":1,"tieu_de":"Tuốt lá & Kỹ thuật vò rau ngót mềm mọng","thoi_gian":"5 phút","noi_dung":"Tuốt lấy các lá ngót non và búp ngọn, bỏ cuống cứng. Rửa sạch rau với 2 lần nước muối loãng rồi vớt ra để ráo. Dùng hai lòng bàn tay vò nhẹ các nắm lá rau ngót cho hơi dập thớ gân (vò dập nhẹ giúp rau khi nấu nhanh chín mềm mướt, tiết trọn vị ngọt bùi và không bị rơm rác khi nuốt)."},{"buoc":2,"tieu_de":"Xào săn thịt băm đậm đà","thoi_gian":"3 phút","noi_dung":"Đặt nồi lên bếp với 1 thìa dầu ăn, phi thơm hành tím băm đến khi dậy mùi thơm. Trút thịt xay vào xào đảo nhanh tay trên lửa vừa cùng 1 thìa cà phê nước mắm cho thịt săn chắc và dậy mùi thơm nức."},{"buoc":3,"tieu_de":"Đun sôi nước dùng trong veo","thoi_gian":"4 phút","noi_dung":"Đổ 1 lít nước lọc vào nồi thịt băm, bật lửa lớn đun sôi bùng lên. Dùng muôi vớt sạch lớp bọt trắng nổi bên trên để nước canh được trong veo và thanh vị."},{"buoc":4,"tieu_de":"Nấu chín rau ngót & Hoàn thành","thoi_gian":"3 phút","noi_dung":"Thả toàn bộ rau ngót đã vò vào nồi nước canh đang sôi sùng sục. Dùng đũa nhấn chìm rau xuống nước. Nêm thêm 1 thìa hạt nêm và chút muối cho vừa miệng. Đun sôi tiếp trong 2 - 3 phút cho rau chín mềm mượt mà vẫn giữ màu xanh mát rồi tắt bếp múc ra tô lớn."}]', 'Vò nhẹ rau ngót trước khi nấu giúp rau mềm mượt và tiết ra trọn vẹn vị ngọt thanh mát, không bị dai cứng rơm rác khi ăn.', '{"calo":140,"protein":"14g","chat_beo":"6g","carb":"8g"}', '["Thanh nhiệt","Giải độc","Món canh quốc dân","Bổ máu lợi sữa"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (26, 'Canh cua rau đay mồng tơi', 'Cua đồng tươi giã lọc lấy nước (400 g), Rau đay & Mồng tơi tươi (1 mớ mỗi loại), Mướp hương non (1 quả), Gạch cua khêu từ mai (1 thìa canh), Muối hạt tinh khiết (1 thìa cà phê)', '[Bước 1: Lọc nước cua & Kỹ thuật kết tảng thịt cua - ⏱️ 10 phút]
Hòa 1 thìa cà phê muối hạt vào 1 lít nước lọc cua, dùng đũa khuấy đều (muối giúp protein cua kết tủa đóng tảng lớn đẹp mắt). Đặt nồi lên bếp bật lửa vừa. Trong 3 phút đầu khi nước còn ấm, dùng muôi khuấy nhẹ nhàng theo hình tròn sát đáy nồi để thịt cua không bị lắng bén cháy đáy nồi. Khi nước bắt đầu bốc hơi nóng và mảng thịt cua bắt đầu nổi lên mặt thì NGỪNG khuấy hoàn toàn.

[Bước 2: Hạ lửa nhỏ & Vớt tảng thịt cua - ⏱️ 5 phút]
Khi nước canh sôi lăn tăn, hạ ngay lửa xuống mức nhỏ nhất để thịt cua kết thành một tảng lớn vàng ươm nổi bồng bềnh trên mặt nước mà không bị vỡ vụn. Dùng muôi thủng khéo léo gạt nhẹ tảng thịt cua dồn về một góc hoặc múc riêng ra bát (giữ nguyên tảng thịt cua không bị nát khi cho rau vào nấu).

[Bước 3: Chưng gạch cua vàng ngậy - ⏱️ 3 phút]
Đặt chảo nhỏ lên bếp với 1 thìa dầu ăn, phi thơm hành tím băm nhuyễn. Trút phần gạch cua khêu từ mai vào chưng đều tay trên lửa nhỏ trong 1 phút cho gạch cua dậy màu vàng cam thơm ngậy nức mũi.

[Bước 4: Nấu rau mướp & Rưới gạch cua hoàn tất - ⏱️ 4 phút]
Bật lửa lớn cho nồi nước canh sôi lại, thả mướp hương vào trước, sau đó thả rau đay và mồng tơi thái nhỏ vào. Nhấn nhẹ rau xuống nước, nêm hạt nêm và chút nước mắm cho vừa miệng. Đun sôi trong 2 phút cho rau vừa chín tới. Thả lại tảng thịt cua và rưới phần gạch cua chưng vàng cam lên trên mặt nồi canh, đun sôi bùng 20 giây rồi múc ra tô lớn thưởng thức cùng cà pháo giòn.

💡 Mẹo đầu bếp: Khi đun nước cua: Cho muối hạt vào từ đầu và khuấy nhẹ đáy nồi lúc nước còn lạnh; khi thịt cua nổi lên thì lập tức ngừng khuấy và hạ lửa nhỏ liu riu để tảng thịt cua đóng bánh dày cộp tuyệt đẹp.', '1786037152327.webp', 'Canh', 'Canh cua đồng đóng tảng gạch vàng ươm thơm ngậy quyện cùng vị ngọt nhớt mát lành của rau đay, mồng tơi và mướp hương, ăn kèm cà pháo giòn tan chuẩn vị mâm cơm Bắc.', 'Trung bình', '4 người', 20, 15, '[{"ten":"Cua đồng tươi giã lọc lấy nước","so_luong":400,"don_vi":"g","ghi_chu":"lọc kỹ lấy 1 lít nước cua không cặn cát"},{"ten":"Rau đay & Mồng tơi tươi","so_luong":1,"don_vi":"mớ mỗi loại","ghi_chu":"nhặt lá non rửa sạch thái nhỏ 1cm"},{"ten":"Mướp hương non","so_luong":1,"don_vi":"quả","ghi_chu":"gọt vỏ thái vát xéo"},{"ten":"Gạch cua khêu từ mai","so_luong":1,"don_vi":"thìa canh","ghi_chu":"chưng hành khô tạo màu vàng ngậy"},{"ten":"Muối hạt tinh khiết","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"giúp thịt cua kết tảng lớn"}]', '[{"buoc":1,"tieu_de":"Lọc nước cua & Kỹ thuật kết tảng thịt cua","thoi_gian":"10 phút","noi_dung":"Hòa 1 thìa cà phê muối hạt vào 1 lít nước lọc cua, dùng đũa khuấy đều (muối giúp protein cua kết tủa đóng tảng lớn đẹp mắt). Đặt nồi lên bếp bật lửa vừa. Trong 3 phút đầu khi nước còn ấm, dùng muôi khuấy nhẹ nhàng theo hình tròn sát đáy nồi để thịt cua không bị lắng bén cháy đáy nồi. Khi nước bắt đầu bốc hơi nóng và mảng thịt cua bắt đầu nổi lên mặt thì NGỪNG khuấy hoàn toàn."},{"buoc":2,"tieu_de":"Hạ lửa nhỏ & Vớt tảng thịt cua","thoi_gian":"5 phút","noi_dung":"Khi nước canh sôi lăn tăn, hạ ngay lửa xuống mức nhỏ nhất để thịt cua kết thành một tảng lớn vàng ươm nổi bồng bềnh trên mặt nước mà không bị vỡ vụn. Dùng muôi thủng khéo léo gạt nhẹ tảng thịt cua dồn về một góc hoặc múc riêng ra bát (giữ nguyên tảng thịt cua không bị nát khi cho rau vào nấu)."},{"buoc":3,"tieu_de":"Chưng gạch cua vàng ngậy","thoi_gian":"3 phút","noi_dung":"Đặt chảo nhỏ lên bếp với 1 thìa dầu ăn, phi thơm hành tím băm nhuyễn. Trút phần gạch cua khêu từ mai vào chưng đều tay trên lửa nhỏ trong 1 phút cho gạch cua dậy màu vàng cam thơm ngậy nức mũi."},{"buoc":4,"tieu_de":"Nấu rau mướp & Rưới gạch cua hoàn tất","thoi_gian":"4 phút","noi_dung":"Bật lửa lớn cho nồi nước canh sôi lại, thả mướp hương vào trước, sau đó thả rau đay và mồng tơi thái nhỏ vào. Nhấn nhẹ rau xuống nước, nêm hạt nêm và chút nước mắm cho vừa miệng. Đun sôi trong 2 phút cho rau vừa chín tới. Thả lại tảng thịt cua và rưới phần gạch cua chưng vàng cam lên trên mặt nồi canh, đun sôi bùng 20 giây rồi múc ra tô lớn thưởng thức cùng cà pháo giòn."}]', 'Khi đun nước cua: Cho muối hạt vào từ đầu và khuấy nhẹ đáy nồi lúc nước còn lạnh; khi thịt cua nổi lên thì lập tức ngừng khuấy và hạ lửa nhỏ liu riu để tảng thịt cua đóng bánh dày cộp tuyệt đẹp.', '{"calo":190,"protein":"20g","chat_beo":"7g","carb":"12g"}', '["Canh mùa hè","Đặc sản miền Bắc","Giàu canxi","Ăn kèm cà pháo"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (27, 'Canh bí đao nấu thịt băm', 'Bí đao non (bí xanh) (500 g), Thịt heo nạc xay (150 g), Hành lá & Mùi tàu (ngò gai) (3 nhánh), Hành khô phi thơm (1 củ), Gia vị mắm muối tiêu (1 set)', '[Bước 1: Sơ chế bí đao không bị chua - ⏱️ 5 phút]
Bí đao nạo vỏ, bổ làm tư theo chiều dọc. Dùng dao cắt bỏ sạch toàn bộ phần ruột xốp trắng chứa hạt ở giữa (ruột bí là phần gây vị chua làm nước canh mất ngon). Rửa sạch bí rồi thái lát dày khoảng 1cm hoặc cắt khúc vừa ăn.

[Bước 2: Xào thơm thịt băm - ⏱️ 3 phút]
Phi thơm hành tím băm với 1 thìa dầu ăn, cho thịt xay vào đảo đều trên lửa vừa cùng 1 thìa cà phê nước mắm cho thịt săn thơm.

[Bước 3: Nấu nước sôi & Vớt sạch bọt - ⏱️ 4 phút]
Đổ 1 lít nước lọc vào nồi thịt đun sôi bùng lên, dùng muôi hớt sạch bọt nổi bên trên để nước canh trong vắt.

[Bước 4: Nấu bí đao vừa chín trong veo - ⏱️ 5 phút]
Thả toàn bộ bí đao vào nồi nước sôi, nêm hạt nêm và chút muối vừa miệng. Đun ở lửa vừa trong 4 - 5 phút đến khi từng miếng bí vừa chuyển màu trong suốt mềm ngọt thì tắt bếp ngay. Rắc hành hoa, mùi tàu thái nhỏ và tiêu xay rồi múc ra tô.

💡 Mẹo đầu bếp: Không nấu bí đao quá lâu trên bếp; chỉ nấu đến khi miếng bí vừa chuyển màu trong veo là tắt bếp ngay để bí giữ trọn độ giòn ngọt mọng nước mà không bị nhũn nát.', '1786037166093.webp', 'Canh', 'Bí đao mềm ngọt thanh mát nấu cùng thịt heo băm đậm đà rắc chút hành hoa tiêu sọ, món canh thanh nhiệt nhẹ nhàng giải độc cơ thể.', 'Dễ', '3 - 4 người', 10, 12, '[{"ten":"Bí đao non (bí xanh)","so_luong":500,"don_vi":"g","ghi_chu":"gọt vỏ, bỏ ruột chua, thái lát dày 1cm"},{"ten":"Thịt heo nạc xay","so_luong":150,"don_vi":"g","ghi_chu":"ướp chút hạt nêm tiêu"},{"ten":"Hành lá & Mùi tàu (ngò gai)","so_luong":3,"don_vi":"nhánh","ghi_chu":"thái nhỏ"},{"ten":"Hành khô phi thơm","so_luong":1,"don_vi":"củ","ghi_chu":"băm nhỏ"},{"ten":"Gia vị mắm muối tiêu","so_luong":1,"don_vi":"set","ghi_chu":"nêm vừa thanh"}]', '[{"buoc":1,"tieu_de":"Sơ chế bí đao không bị chua","thoi_gian":"5 phút","noi_dung":"Bí đao nạo vỏ, bổ làm tư theo chiều dọc. Dùng dao cắt bỏ sạch toàn bộ phần ruột xốp trắng chứa hạt ở giữa (ruột bí là phần gây vị chua làm nước canh mất ngon). Rửa sạch bí rồi thái lát dày khoảng 1cm hoặc cắt khúc vừa ăn."},{"buoc":2,"tieu_de":"Xào thơm thịt băm","thoi_gian":"3 phút","noi_dung":"Phi thơm hành tím băm với 1 thìa dầu ăn, cho thịt xay vào đảo đều trên lửa vừa cùng 1 thìa cà phê nước mắm cho thịt săn thơm."},{"buoc":3,"tieu_de":"Nấu nước sôi & Vớt sạch bọt","thoi_gian":"4 phút","noi_dung":"Đổ 1 lít nước lọc vào nồi thịt đun sôi bùng lên, dùng muôi hớt sạch bọt nổi bên trên để nước canh trong vắt."},{"buoc":4,"tieu_de":"Nấu bí đao vừa chín trong veo","thoi_gian":"5 phút","noi_dung":"Thả toàn bộ bí đao vào nồi nước sôi, nêm hạt nêm và chút muối vừa miệng. Đun ở lửa vừa trong 4 - 5 phút đến khi từng miếng bí vừa chuyển màu trong suốt mềm ngọt thì tắt bếp ngay. Rắc hành hoa, mùi tàu thái nhỏ và tiêu xay rồi múc ra tô."}]', 'Không nấu bí đao quá lâu trên bếp; chỉ nấu đến khi miếng bí vừa chuyển màu trong veo là tắt bếp ngay để bí giữ trọn độ giòn ngọt mọng nước mà không bị nhũn nát.', '{"calo":130,"protein":"12g","chat_beo":"5g","carb":"10g"}', '["Giải nhiệt","Thanh đạm","Giảm cân","Dễ tiêu hóa"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (28, 'Canh sườn nấu khoai tây cà rốt', 'Sườn non heo hoặc xương ống (500 g), Khoai tây vàng (3 củ (~300g)), Cà rốt tươi (1 củ), Hành hoa & Rau mùi tươi (1 mớ nhỏ), Gia vị, hạt tiêu sọ xay (1 set)', '[Bước 1: Chần sườn sạch mùi & Khử bọt bẩn - ⏱️ 8 phút]
Sườn chặt khúc 3.5cm, rửa với nước muối. Cho sườn vào nồi nước lạnh có vài lát gừng, đun sôi bùng trong 3 phút để tiết hết bọt bẩn và máu đọng. Vớt sườn ra rửa lại thật sạch dưới vòi nước lạnh.

[Bước 2: Ninh sườn lấy nước ngọt trong veo - ⏱️ 25 phút]
Cho sườn vào nồi cùng 1.2 lít nước lạnh và 1 thìa cà phê muối hạt. Bật lửa lớn đun sôi, liên tục hớt sạch bọt ở những phút đầu tiên. Hạ lửa nhỏ liu riu mở hé nắp nồi ninh trong 25 phút cho sườn mềm nhừ ngọt tủy.

[Bước 3: Sơ chế khoai tây không thâm & Nấu củ quả - ⏱️ 12 phút]
Khoai tây, cà rốt gọt vỏ cắt khối vuông 3cm, ngâm ngay khoai vào bát nước muối loãng 5 phút cho sạch nhựa thâm rồi vớt ráo. Thả cà rốt và khoai tây vào nồi canh sườn đang sôi, đun tiếp lửa vừa trong 10 - 12 phút cho khoai bở bùi mềm ngọt.

[Bước 4: Nêm nếm chuẩn vị & Bày tô - ⏱️ 2 phút]
Nếm thử khoai chín mềm bở tơi, nêm 1 muỗng nước mắm ngon và 1 thìa hạt nêm cho vừa miệng. Tắt bếp, rắc hành hoa, rau mùi thái nhỏ và chút tiêu xay thơm lừng rồi múc ra tô lớn thưởng thức nóng.

💡 Mẹo đầu bếp: Khi ninh sườn hãy bắt đầu từ nước lạnh và mở hé vung để liên tục hớt sạch bọt; nước canh hầm xương sẽ trong vắt óng ả ngọt ngào không bị đục cặn.', '1786037183354.webp', 'Canh', 'Nước canh sườn heo ninh ngọt lịm từ tủy xương, khoai tây bở tơi bùi béo kết hợp màu cam rực rỡ của cà rốt bổ dưỡng, món canh bổ dưỡng cho cả gia đình.', 'Trung bình', '4 người', 15, 40, '[{"ten":"Sườn non heo hoặc xương ống","so_luong":500,"don_vi":"g","ghi_chu":"chặt khúc 3.5cm"},{"ten":"Khoai tây vàng","so_luong":3,"don_vi":"củ (~300g)","ghi_chu":"gọt vỏ cắt khối vuông 3cm"},{"ten":"Cà rốt tươi","so_luong":1,"don_vi":"củ","ghi_chu":"tỉa hoa cắt khoanh 1.2cm"},{"ten":"Hành hoa & Rau mùi tươi","so_luong":1,"don_vi":"mớ nhỏ","ghi_chu":"thái nhỏ rắc canh"},{"ten":"Gia vị, hạt tiêu sọ xay","so_luong":1,"don_vi":"set","ghi_chu":"nêm nếm vừa vặn"}]', '[{"buoc":1,"tieu_de":"Chần sườn sạch mùi & Khử bọt bẩn","thoi_gian":"8 phút","noi_dung":"Sườn chặt khúc 3.5cm, rửa với nước muối. Cho sườn vào nồi nước lạnh có vài lát gừng, đun sôi bùng trong 3 phút để tiết hết bọt bẩn và máu đọng. Vớt sườn ra rửa lại thật sạch dưới vòi nước lạnh."},{"buoc":2,"tieu_de":"Ninh sườn lấy nước ngọt trong veo","thoi_gian":"25 phút","noi_dung":"Cho sườn vào nồi cùng 1.2 lít nước lạnh và 1 thìa cà phê muối hạt. Bật lửa lớn đun sôi, liên tục hớt sạch bọt ở những phút đầu tiên. Hạ lửa nhỏ liu riu mở hé nắp nồi ninh trong 25 phút cho sườn mềm nhừ ngọt tủy."},{"buoc":3,"tieu_de":"Sơ chế khoai tây không thâm & Nấu củ quả","thoi_gian":"12 phút","noi_dung":"Khoai tây, cà rốt gọt vỏ cắt khối vuông 3cm, ngâm ngay khoai vào bát nước muối loãng 5 phút cho sạch nhựa thâm rồi vớt ráo. Thả cà rốt và khoai tây vào nồi canh sườn đang sôi, đun tiếp lửa vừa trong 10 - 12 phút cho khoai bở bùi mềm ngọt."},{"buoc":4,"tieu_de":"Nêm nếm chuẩn vị & Bày tô","thoi_gian":"2 phút","noi_dung":"Nếm thử khoai chín mềm bở tơi, nêm 1 muỗng nước mắm ngon và 1 thìa hạt nêm cho vừa miệng. Tắt bếp, rắc hành hoa, rau mùi thái nhỏ và chút tiêu xay thơm lừng rồi múc ra tô lớn thưởng thức nóng."}]', 'Khi ninh sườn hãy bắt đầu từ nước lạnh và mở hé vung để liên tục hớt sạch bọt; nước canh hầm xương sẽ trong vắt óng ả ngọt ngào không bị đục cặn.', '{"calo":380,"protein":"28g","chat_beo":"18g","carb":"26g"}', '["Bổ dưỡng","Canh hầm ngon","Gia đình sum vầy","Giàu vitamin & khoáng chất"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (29, 'Canh chua tôm', 'Tôm sú tươi sống (300 g), Dứa chín & Cà chua (0.5 quả / 2 quả), Đậu bắp & Giá đỗ (100 g), Me chua chín (35 g), Ngò om & Ngò gai (1 mớ nhỏ)', '[Bước 1: Sơ chế & Ướp tôm tươi - ⏱️ 8 phút]
Tôm lột bỏ vỏ và đầu (chừa lại đuôi cho đẹp), rút sạch sợi chỉ đen trên lưng. Ướp tôm với 1/2 thìa hạt nêm và chút đầu hành lá băm nhỏ trong 5 phút.

[Bước 2: Xào cà chua tạo màu & Nấu nước dùng me - ⏱️ 5 phút]
Phi thơm tỏi băm với 1 thìa dầu ăn, cho một nửa lượng cà chua vào xào nhuyễn lấy màu đỏ cam tự nhiên. Đổ 1 lít nước vào đun sôi bùng, rót nước cốt me dầm vào nồi, nêm 2 muỗng nước mắm, 1.5 muỗng đường tạo vị chua ngọt hài hòa.

[Bước 3: Nấu chín giòn tôm tươi - ⏱️ 3 phút]
Thả tôm vào nồi nước sôi bùng, nấu trong khoảng 2 phút đến khi tôm chuyển màu đỏ cam uốn cong săn chắc ngọt mọng.

[Bước 4: Thêm dứa, đậu bắp, giá & Hoàn tất - ⏱️ 2 phút]
Cho dứa, cà chua còn lại, đậu bắp và giá đỗ vào nồi đun sôi thêm 1 phút cho rau củ vừa chín giòn thì tắt bếp ngay. Múc canh ra tô, rắc ngò om, ngò gai thái nhỏ và tỏi phi giòn lên trên.

💡 Mẹo đầu bếp: Tôm nấu canh chua chỉ cần sôi 2 phút là đạt độ ngọt giòn mọng nước tối đa; tuyệt đối không đun tôm quá lâu sẽ làm thịt tôm bị co rút xơ xác.', '1786037230275.webp', 'Canh', 'Tôm tươi chắc thịt đỏ au hòa trong nước canh chua me thanh mát, vị chua thanh ngọt hậu đượm hương dứa và cà chua thơm ngát.', 'Dễ', '3 - 4 người', 15, 15, '[{"ten":"Tôm sú tươi sống","so_luong":300,"don_vi":"g","ghi_chu":"bóc vỏ chừa đuôi, rút chỉ lưng"},{"ten":"Dứa chín & Cà chua","so_luong":0.5,"don_vi":"quả / 2 quả","ghi_chu":"thái lát rẻ quạt và múi cau"},{"ten":"Đậu bắp & Giá đỗ","so_luong":100,"don_vi":"g","ghi_chu":"rửa sạch"},{"ten":"Me chua chín","so_luong":35,"don_vi":"g","ghi_chu":"dầm nước sôi lấy cốt chua"},{"ten":"Ngò om & Ngò gai","so_luong":1,"don_vi":"mớ nhỏ","ghi_chu":"cắt nhỏ dậy mùi thơm"}]', '[{"buoc":1,"tieu_de":"Sơ chế & Ướp tôm tươi","thoi_gian":"8 phút","noi_dung":"Tôm lột bỏ vỏ và đầu (chừa lại đuôi cho đẹp), rút sạch sợi chỉ đen trên lưng. Ướp tôm với 1/2 thìa hạt nêm và chút đầu hành lá băm nhỏ trong 5 phút."},{"buoc":2,"tieu_de":"Xào cà chua tạo màu & Nấu nước dùng me","thoi_gian":"5 phút","noi_dung":"Phi thơm tỏi băm với 1 thìa dầu ăn, cho một nửa lượng cà chua vào xào nhuyễn lấy màu đỏ cam tự nhiên. Đổ 1 lít nước vào đun sôi bùng, rót nước cốt me dầm vào nồi, nêm 2 muỗng nước mắm, 1.5 muỗng đường tạo vị chua ngọt hài hòa."},{"buoc":3,"tieu_de":"Nấu chín giòn tôm tươi","thoi_gian":"3 phút","noi_dung":"Thả tôm vào nồi nước sôi bùng, nấu trong khoảng 2 phút đến khi tôm chuyển màu đỏ cam uốn cong săn chắc ngọt mọng."},{"buoc":4,"tieu_de":"Thêm dứa, đậu bắp, giá & Hoàn tất","thoi_gian":"2 phút","noi_dung":"Cho dứa, cà chua còn lại, đậu bắp và giá đỗ vào nồi đun sôi thêm 1 phút cho rau củ vừa chín giòn thì tắt bếp ngay. Múc canh ra tô, rắc ngò om, ngò gai thái nhỏ và tỏi phi giòn lên trên."}]', 'Tôm nấu canh chua chỉ cần sôi 2 phút là đạt độ ngọt giòn mọng nước tối đa; tuyệt đối không đun tôm quá lâu sẽ làm thịt tôm bị co rút xơ xác.', '{"calo":210,"protein":"24g","chat_beo":"4g","carb":"19g"}', '["Canh chua ngọt","Tôm tươi giòn ngọt","Thanh nhiệt giải say","Nam Bộ"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (30, 'Canh khổ qua nhồi thịt', 'Khổ qua (mướp đắng) (3 trái (~500g)), Thịt heo nạc vai xay (250 g), Mộc nhĩ ngâm nở (3 tai), Miến dong ngâm mềm (20 g), Hành tím & Hành hoa chần buộc (5 cọng), Nước dùng xương hầm trong (1.2 lít)', '[Bước 1: Khử đắng khổ qua & Nạo sạch ruột trắng - ⏱️ 10 phút]
Khổ qua cắt khúc dài 4 - 5cm (hoặc rạch một đường dọc thân quả). Dùng chuôi thìa nạo thật sạch toàn bộ hạt và lớp màng xốp trắng bên trong ruột (lớp màng trắng này là nơi tập trung 70% vị đắng gắt, nạo sạch sẽ giúp khổ qua ngọt thanh dễ ăn). Ngâm khúc khổ qua vào thau nước muối loãng 10 phút rồi vớt ra để ráo.

[Bước 2: Trộn nhân thịt dẻo quánh & Nhồi khổ qua - ⏱️ 10 phút]
Trộn đều thịt xay, mộc nhĩ thái nhuyễn, miến cắt ngắn, hành tím băm, 1 thìa cà phê nước mắm, 1 thìa hạt nêm và 1/2 thìa tiêu trong 3 phút cho dẻo dính. Nhồi nhân thịt thật chặt vào từng khúc khổ qua, miết phẳng hai đầu. Dùng cọng hành hoa chần sơ qua nước sôi buộc ngang thân từng khúc khổ qua cho đẹp mắt.

[Bước 3: Nấu nước canh sôi & Thả khổ qua - ⏱️ 5 phút]
Đun sôi 1.2 lít nước dùng xương hầm với 1 thìa cà phê muối hạt. Khi nước sôi bùng, nhẹ nhàng thả từng khúc khổ qua nhồi thịt vào nồi. Vớt sạch bọt màng nổi lên để nước canh trong vắt.

[Bước 4: Ninh lửa nhỏ liu riu mở nắp - ⏱️ 20 phút]
Hạ lửa nhỏ vừa, đun liu riu mở nắp trong 20 - 25 phút đến khi dùng tăm xiên nhẹ qua lớp vỏ khổ qua thấy mềm mại dễ dàng. Nêm nếm thêm chút hạt nêm và nước mắm vừa ăn. Tắt bếp, rắc hành hoa mùi tàu thái nhỏ rồi múc ra tô lớn thưởng thức.

💡 Mẹo đầu bếp: Nạo thật sạch lớp màng xốp trắng bên trong ruột khổ qua và nấu mở nắp nồi sẽ giúp khử sạch vị đắng gắt, chỉ giữ lại vị đắng dịu ngọt hậu thanh mát đặc trưng.', '1786037247932.webp', 'Canh', 'Trái khổ qua (mướp đắng) xanh mát nhồi nhân thịt băm mộc nhĩ ngọt béo, vị đắng dịu quyện nước dùng ngọt thanh sâu lắng mang ý nghĩa vượt qua khó khăn đón may mắn.', 'Trung bình', '4 người', 20, 30, '[{"ten":"Khổ qua (mướp đắng)","so_luong":3,"don_vi":"trái (~500g)","ghi_chu":"chọn trái gai to nở đều, màu xanh sáng"},{"ten":"Thịt heo nạc vai xay","so_luong":250,"don_vi":"g","ghi_chu":"thịt tươi có mỡ nhẹ để nhân mềm"},{"ten":"Mộc nhĩ ngâm nở","so_luong":3,"don_vi":"tai","ghi_chu":"thái sợi nhuyễn"},{"ten":"Miến dong ngâm mềm","so_luong":20,"don_vi":"g","ghi_chu":"cắt khúc ngắn 1cm"},{"ten":"Hành tím & Hành hoa chần buộc","so_luong":5,"don_vi":"cọng","ghi_chu":"buộc trang trí đẹp mắt"},{"ten":"Nước dùng xương hầm trong","so_luong":1.2,"don_vi":"lít","ghi_chu":"tạo vị ngọt thanh sâu"}]', '[{"buoc":1,"tieu_de":"Khử đắng khổ qua & Nạo sạch ruột trắng","thoi_gian":"10 phút","noi_dung":"Khổ qua cắt khúc dài 4 - 5cm (hoặc rạch một đường dọc thân quả). Dùng chuôi thìa nạo thật sạch toàn bộ hạt và lớp màng xốp trắng bên trong ruột (lớp màng trắng này là nơi tập trung 70% vị đắng gắt, nạo sạch sẽ giúp khổ qua ngọt thanh dễ ăn). Ngâm khúc khổ qua vào thau nước muối loãng 10 phút rồi vớt ra để ráo."},{"buoc":2,"tieu_de":"Trộn nhân thịt dẻo quánh & Nhồi khổ qua","thoi_gian":"10 phút","noi_dung":"Trộn đều thịt xay, mộc nhĩ thái nhuyễn, miến cắt ngắn, hành tím băm, 1 thìa cà phê nước mắm, 1 thìa hạt nêm và 1/2 thìa tiêu trong 3 phút cho dẻo dính. Nhồi nhân thịt thật chặt vào từng khúc khổ qua, miết phẳng hai đầu. Dùng cọng hành hoa chần sơ qua nước sôi buộc ngang thân từng khúc khổ qua cho đẹp mắt."},{"buoc":3,"tieu_de":"Nấu nước canh sôi & Thả khổ qua","thoi_gian":"5 phút","noi_dung":"Đun sôi 1.2 lít nước dùng xương hầm với 1 thìa cà phê muối hạt. Khi nước sôi bùng, nhẹ nhàng thả từng khúc khổ qua nhồi thịt vào nồi. Vớt sạch bọt màng nổi lên để nước canh trong vắt."},{"buoc":4,"tieu_de":"Ninh lửa nhỏ liu riu mở nắp","thoi_gian":"20 phút","noi_dung":"Hạ lửa nhỏ vừa, đun liu riu mở nắp trong 20 - 25 phút đến khi dùng tăm xiên nhẹ qua lớp vỏ khổ qua thấy mềm mại dễ dàng. Nêm nếm thêm chút hạt nêm và nước mắm vừa ăn. Tắt bếp, rắc hành hoa mùi tàu thái nhỏ rồi múc ra tô lớn thưởng thức."}]', 'Nạo thật sạch lớp màng xốp trắng bên trong ruột khổ qua và nấu mở nắp nồi sẽ giúp khử sạch vị đắng gắt, chỉ giữ lại vị đắng dịu ngọt hậu thanh mát đặc trưng.', '{"calo":240,"protein":"22g","chat_beo":"12g","carb":"11g"}', '["Món canh ngày Tết","Giải nhiệt thanh lọc","Hạ đường huyết","Ngọt hậu đắng thanh"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (31, 'Canh trứng cà chua', 'Trứng gà ta tươi (2 quả), Cà chua chín đỏ mọng (2 quả), Hành tím & Hành hoa (3 nhánh), Rau mùi (ngò rí) (1 mớ nhỏ), Nước mắm ngon & Tiêu xay (1 muỗng canh)', '[Bước 1: Đánh trứng & Chuẩn bị cà chua - ⏱️ 2 phút]
Đập 2 quả trứng gà vào bát, thêm 1/2 thìa cà phê nước mắm, chút tiêu và 1/2 thìa cà phê dầu ăn (dầu ăn giúp sợi vân mây trứng khi gặp nước sôi sẽ mềm mại mượt mà không bị khô cứng). Đánh tan đều tay. Cà chua rửa sạch, bổ múi cau mỏng.

[Bước 2: Xào sốt cà chua đỏ sánh - ⏱️ 2 phút]
Bắc nồi lên bếp với 1 thìa dầu ăn, phi thơm hành tím băm. Cho cà chua vào xào đều trên lửa vừa, nêm 1 thìa hạt nêm và dùng muôi dằm nhẹ cho cà chua ra nước sốt đỏ sánh đẹp mắt.

[Bước 3: Nấu nước canh sôi sùng sục - ⏱️ 2 phút]
Đổ 800ml nước sôi nóng vào nồi cà chua, nêm 1 muỗng nước mắm ngon. Bật lửa lớn nhất để nước canh sôi sục thật mạnh (nước sôi sục mạnh là điều kiện tiên quyết để tạo vân mây trứng bồng bềnh).

[Bước 4: Kỹ thuật rót dòng tạo vân mây bồng bềnh - ⏱️ 1 phút]
Khi nước canh đang sôi bùng mạnh mẽ, một tay cầm bát trứng rót từ từ từng dòng thật nhỏ từ trên cao xuống khắp mặt nồi, tay kia dùng đũa khuấy nhẹ nhàng theo một chiều vòng tròn. Lòng đỏ và lòng trắng sẽ lập tức chín đông và tơ ra thành từng dải vân mây vàng óng bồng bềnh đẹp mắt. Tắt bếp ngay lập tức, rắc hành hoa, rau mùi và chút tiêu xay lên trên mặt.

💡 Mẹo đầu bếp: Bắt buộc nước canh phải sôi sùng sục ở lửa lớn khi rót trứng vào và khuấy theo một chiều nhẹ tay; trứng sẽ tạo thành những dải vân mây xốp mỏng như lụa mà không bị vữa tanh.', '1786037266641.webp', 'Canh', 'Bát canh trứng cà chua đỏ rực điểm vân mây trứng gà vàng óng bồng bềnh mềm mại, món canh siêu tốc thơm ngon ngọt dịu khai vị hoàn hảo.', 'Dễ', '3 người', 5, 5, '[{"ten":"Trứng gà ta tươi","so_luong":2,"don_vi":"quả","ghi_chu":"đánh tan với 1/2 thìa cà phê dầu ăn"},{"ten":"Cà chua chín đỏ mọng","so_luong":2,"don_vi":"quả","ghi_chu":"bổ múi cau mỏng"},{"ten":"Hành tím & Hành hoa","so_luong":3,"don_vi":"nhánh","ghi_chu":"băm nhỏ"},{"ten":"Rau mùi (ngò rí)","so_luong":1,"don_vi":"mớ nhỏ","ghi_chu":"thái nhỏ rắc canh"},{"ten":"Nước mắm ngon & Tiêu xay","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"nêm vừa vị"}]', '[{"buoc":1,"tieu_de":"Đánh trứng & Chuẩn bị cà chua","thoi_gian":"2 phút","noi_dung":"Đập 2 quả trứng gà vào bát, thêm 1/2 thìa cà phê nước mắm, chút tiêu và 1/2 thìa cà phê dầu ăn (dầu ăn giúp sợi vân mây trứng khi gặp nước sôi sẽ mềm mại mượt mà không bị khô cứng). Đánh tan đều tay. Cà chua rửa sạch, bổ múi cau mỏng."},{"buoc":2,"tieu_de":"Xào sốt cà chua đỏ sánh","thoi_gian":"2 phút","noi_dung":"Bắc nồi lên bếp với 1 thìa dầu ăn, phi thơm hành tím băm. Cho cà chua vào xào đều trên lửa vừa, nêm 1 thìa hạt nêm và dùng muôi dằm nhẹ cho cà chua ra nước sốt đỏ sánh đẹp mắt."},{"buoc":3,"tieu_de":"Nấu nước canh sôi sùng sục","thoi_gian":"2 phút","noi_dung":"Đổ 800ml nước sôi nóng vào nồi cà chua, nêm 1 muỗng nước mắm ngon. Bật lửa lớn nhất để nước canh sôi sục thật mạnh (nước sôi sục mạnh là điều kiện tiên quyết để tạo vân mây trứng bồng bềnh)."},{"buoc":4,"tieu_de":"Kỹ thuật rót dòng tạo vân mây bồng bềnh","thoi_gian":"1 phút","noi_dung":"Khi nước canh đang sôi bùng mạnh mẽ, một tay cầm bát trứng rót từ từ từng dòng thật nhỏ từ trên cao xuống khắp mặt nồi, tay kia dùng đũa khuấy nhẹ nhàng theo một chiều vòng tròn. Lòng đỏ và lòng trắng sẽ lập tức chín đông và tơ ra thành từng dải vân mây vàng óng bồng bềnh đẹp mắt. Tắt bếp ngay lập tức, rắc hành hoa, rau mùi và chút tiêu xay lên trên mặt."}]', 'Bắt buộc nước canh phải sôi sùng sục ở lửa lớn khi rót trứng vào và khuấy theo một chiều nhẹ tay; trứng sẽ tạo thành những dải vân mây xốp mỏng như lụa mà không bị vữa tanh.', '{"calo":160,"protein":"12g","chat_beo":"11g","carb":"5g"}', '["Nhanh như chớp","Dễ làm nhất","Bữa cơm tiện lợi","Màu sắc bắt mắt"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (32, 'Canh ngao nấu chua', 'Ngao tươi sống (nghêu) (1 kg), Cà chua chín mọng (2 quả), Dứa (thơm) chín vừa (0.5 quả), Quả sấu xanh (hoặc me) (3 quả), Rau răm & Hành hoa tươi (1 mớ nhỏ)', '[Bước 1: Ngâm nhả cát & Luộc ngao lấy nước ngọt - ⏱️ 10 phút]
Ngao ngâm trong thau nước vo gạo có cắt vài lát ớt tươi trong 30 phút để nhả sạch bùn cát, rửa sạch vỏ ngoài. Cho ngao vào nồi với 1 lít nước lạnh, đun lửa lớn đến khi ngao vừa hé miệng mở vỏ thì vớt ngao ra ngay. Để nồi nước luộc ngao lắng cặn trong 5 phút rồi nhẹ nhàng gạn lấy phần nước trong veo bên trên, bỏ phần cặn cát đọng đáy nồi.

[Bước 2: Tách thịt ngao & Xào săn thơm nức - ⏱️ 5 phút]
Tách lấy phần ruột thịt ngao, bóp nhẹ rửa sạch phần phân đen bên trong để ngao không bị sạn. Đặt nồi lên bếp, phi thơm hành tím băm với 1 thìa dầu ăn, cho ruột ngao vào đảo nhanh tay trên lửa lớn cùng 1 thìa cà phê nước mắm trong 1 phút cho ngấm thơm rồi múc ra bát riêng.

[Bước 3: Nấu nước canh chua sấu thanh mát - ⏱️ 6 phút]
Cho cà chua vào nồi xào lấy màu đỏ cam, đổ nước luộc ngao trong veo vào đun sôi. Thả quả sấu cạo vỏ và dứa thái lát vào đun sôi ở lửa vừa trong 5 phút cho sấu chín mềm. Dùng muôi dầm nát quả sấu để tinh chất chua thanh dịu của sấu hòa tan vào nước canh.

[Bước 4: Thả ruột ngao & Rau răm hoàn thiện - ⏱️ 2 phút]
Trút toàn bộ bát ruột ngao xào vào nồi nước canh, nêm nếm lại thêm hạt nêm cho vị chua thanh ngọt đậm đà vừa miệng. Đun sôi bùng lại 30 giây rồi tắt bếp ngay. Rắc nhiều rau răm và hành hoa thái nhỏ lên mặt, múc ra tô thưởng thức nóng.

💡 Mẹo đầu bếp: Canh ngao nấu chua dứt khoát phải có rau răm; rau răm khử hoàn toàn tính hàn của ngao và mang lại hương vị thơm nồng nàn quyến rũ không thể thay thế.', '1786037279600.webp', 'Canh', 'Nước canh ngao ngọt lịm từ biển cả nấu cùng dứa chín chua thơm, cà chua mọng nước và quả sấu giòn, món canh thanh nhiệt cực phẩm mùa hè miền Bắc.', 'Dễ', '3 - 4 người', 15, 15, '[{"ten":"Ngao tươi sống (nghêu)","so_luong":1,"don_vi":"kg","ghi_chu":"ngâm nước ớt nhả sạch cát"},{"ten":"Cà chua chín mọng","so_luong":2,"don_vi":"quả","ghi_chu":"bổ múi cau"},{"ten":"Dứa (thơm) chín vừa","so_luong":0.5,"don_vi":"quả","ghi_chu":"thái lát mỏng rẻ quạt"},{"ten":"Quả sấu xanh (hoặc me)","so_luong":3,"don_vi":"quả","ghi_chu":"cạo vỏ khía cạnh"},{"ten":"Rau răm & Hành hoa tươi","so_luong":1,"don_vi":"mớ nhỏ","ghi_chu":"linh hồn món canh ngao"}]', '[{"buoc":1,"tieu_de":"Ngâm nhả cát & Luộc ngao lấy nước ngọt","thoi_gian":"10 phút","noi_dung":"Ngao ngâm trong thau nước vo gạo có cắt vài lát ớt tươi trong 30 phút để nhả sạch bùn cát, rửa sạch vỏ ngoài. Cho ngao vào nồi với 1 lít nước lạnh, đun lửa lớn đến khi ngao vừa hé miệng mở vỏ thì vớt ngao ra ngay. Để nồi nước luộc ngao lắng cặn trong 5 phút rồi nhẹ nhàng gạn lấy phần nước trong veo bên trên, bỏ phần cặn cát đọng đáy nồi."},{"buoc":2,"tieu_de":"Tách thịt ngao & Xào săn thơm nức","thoi_gian":"5 phút","noi_dung":"Tách lấy phần ruột thịt ngao, bóp nhẹ rửa sạch phần phân đen bên trong để ngao không bị sạn. Đặt nồi lên bếp, phi thơm hành tím băm với 1 thìa dầu ăn, cho ruột ngao vào đảo nhanh tay trên lửa lớn cùng 1 thìa cà phê nước mắm trong 1 phút cho ngấm thơm rồi múc ra bát riêng."},{"buoc":3,"tieu_de":"Nấu nước canh chua sấu thanh mát","thoi_gian":"6 phút","noi_dung":"Cho cà chua vào nồi xào lấy màu đỏ cam, đổ nước luộc ngao trong veo vào đun sôi. Thả quả sấu cạo vỏ và dứa thái lát vào đun sôi ở lửa vừa trong 5 phút cho sấu chín mềm. Dùng muôi dầm nát quả sấu để tinh chất chua thanh dịu của sấu hòa tan vào nước canh."},{"buoc":4,"tieu_de":"Thả ruột ngao & Rau răm hoàn thiện","thoi_gian":"2 phút","noi_dung":"Trút toàn bộ bát ruột ngao xào vào nồi nước canh, nêm nếm lại thêm hạt nêm cho vị chua thanh ngọt đậm đà vừa miệng. Đun sôi bùng lại 30 giây rồi tắt bếp ngay. Rắc nhiều rau răm và hành hoa thái nhỏ lên mặt, múc ra tô thưởng thức nóng."}]', 'Canh ngao nấu chua dứt khoát phải có rau răm; rau răm khử hoàn toàn tính hàn của ngao và mang lại hương vị thơm nồng nàn quyến rũ không thể thay thế.', '{"calo":170,"protein":"22g","chat_beo":"3g","carb":"14g"}', '["Canh thanh nhiệt","Giải độc mùa hè","Hải sản ngọt lành","Vị chua sấu Bắc"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (33, 'Canh đậu hũ rong biển', 'Đậu hũ non tươi (1 hộp (~300g)), Rong biển khô nấu canh (Miyeok) (15 g), Thịt heo nạc vai xay (100 g), Gừng tươi già (1 nhánh nhỏ), Dầu mè nguyên chất (1 thìa cà phê)', '[Bước 1: Ngâm nở & Khử tanh rong biển - ⏱️ 10 phút]
Ngâm 15g rong biển khô vào thau nước lạnh trong 10 phút cho nở bung to gấp 5 lần. Bóp nhẹ rong biển với vài giọt rượu trắng và vài lát gừng đập dập để tẩy sạch hoàn toàn mùi tanh của biển, xả lại nước lạnh rồi dùng kéo cắt khúc vừa ăn 3cm.

[Bước 2: Xào thịt băm & Xào thơm rong biển với dầu mè - ⏱️ 4 phút]
Đặt nồi lên bếp với 1 thìa cà phê dầu mè, cho thịt xay và gừng thái chỉ vào xào săn trên lửa vừa. Trút toàn bộ rong biển vào đảo đều tay cùng thịt trong 2 phút cho sợi rong biển săn lại và ngấm đượm hương gừng ấm.

[Bước 3: Nấu sôi nước dùng thanh ngọt - ⏱️ 5 phút]
Đổ 800ml nước sôi nóng vào nồi rong biển, bật lửa lớn đun sôi bùng, hớt sạch bọt. Nêm 1 muỗng canh nước tương đậu nành (hoặc nước mắm) và 1 thìa hạt nêm cho thanh vị.

[Bước 4: Thả đậu non mượt mà & Hoàn tất - ⏱️ 2 phút]
Cắt đậu hũ non thành các khối vuông 2 x 2cm, nhẹ nhàng thả từng khối vào nồi canh đang sôi lăn tăn (tránh khuấy mạnh tay làm nát đậu non). Đun sôi nhẹ trong 2 phút, nhỏ vài giọt dầu mè thơm ngậy lên trên mặt rồi tắt bếp múc ra tô thưởng thức nóng.

💡 Mẹo đầu bếp: Xào sơ rong biển với vài sợi gừng tươi và dầu mè trước khi châm nước nấu giúp khử sạch 100% mùi tanh đặc trưng và làm nước canh thơm ngậy hấp dẫn.', '1786037293536.webp', 'Canh', 'Đậu hũ non mềm tan mượt mà hòa cùng rong biển khô thanh mát ngọt tự nhiên và thịt băm ngọt nước, món canh chuẩn phong cách dưỡng sinh lành mạnh.', 'Dễ', '3 người', 10, 10, '[{"ten":"Đậu hũ non tươi","so_luong":1,"don_vi":"hộp (~300g)","ghi_chu":"cắt khối vuông 2cm"},{"ten":"Rong biển khô nấu canh (Miyeok)","so_luong":15,"don_vi":"g","ghi_chu":"ngâm nở to, rửa sạch khử tanh"},{"ten":"Thịt heo nạc vai xay","so_luong":100,"don_vi":"g","ghi_chu":"ướp chút gia vị"},{"ten":"Gừng tươi già","so_luong":1,"don_vi":"nhánh nhỏ","ghi_chu":"thái chỉ mỏng ấm bụng"},{"ten":"Dầu mè nguyên chất","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"nhỏ vào khi hoàn thành"}]', '[{"buoc":1,"tieu_de":"Ngâm nở & Khử tanh rong biển","thoi_gian":"10 phút","noi_dung":"Ngâm 15g rong biển khô vào thau nước lạnh trong 10 phút cho nở bung to gấp 5 lần. Bóp nhẹ rong biển với vài giọt rượu trắng và vài lát gừng đập dập để tẩy sạch hoàn toàn mùi tanh của biển, xả lại nước lạnh rồi dùng kéo cắt khúc vừa ăn 3cm."},{"buoc":2,"tieu_de":"Xào thịt băm & Xào thơm rong biển với dầu mè","thoi_gian":"4 phút","noi_dung":"Đặt nồi lên bếp với 1 thìa cà phê dầu mè, cho thịt xay và gừng thái chỉ vào xào săn trên lửa vừa. Trút toàn bộ rong biển vào đảo đều tay cùng thịt trong 2 phút cho sợi rong biển săn lại và ngấm đượm hương gừng ấm."},{"buoc":3,"tieu_de":"Nấu sôi nước dùng thanh ngọt","thoi_gian":"5 phút","noi_dung":"Đổ 800ml nước sôi nóng vào nồi rong biển, bật lửa lớn đun sôi bùng, hớt sạch bọt. Nêm 1 muỗng canh nước tương đậu nành (hoặc nước mắm) và 1 thìa hạt nêm cho thanh vị."},{"buoc":4,"tieu_de":"Thả đậu non mượt mà & Hoàn tất","thoi_gian":"2 phút","noi_dung":"Cắt đậu hũ non thành các khối vuông 2 x 2cm, nhẹ nhàng thả từng khối vào nồi canh đang sôi lăn tăn (tránh khuấy mạnh tay làm nát đậu non). Đun sôi nhẹ trong 2 phút, nhỏ vài giọt dầu mè thơm ngậy lên trên mặt rồi tắt bếp múc ra tô thưởng thức nóng."}]', 'Xào sơ rong biển với vài sợi gừng tươi và dầu mè trước khi châm nước nấu giúp khử sạch 100% mùi tanh đặc trưng và làm nước canh thơm ngậy hấp dẫn.', '{"calo":180,"protein":"18g","chat_beo":"8g","carb":"9g"}', '["Eat Clean","Dưỡng sinh","Giàu I-ốt & Khoáng chất","Thanh đạm nhẹ bụng"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (34, 'Rau muống xào tỏi', 'Rau muống ngọn non (1 bó (~500g)), Tỏi khô ta thơm nồng (2 củ to), Dầu ăn thực vật (2 muỗng canh), Nước mắm ngon & Dầu hào (1 muỗng canh mỗi loại)', '[Bước 1: Chần sơ sốc nhiệt đá lạnh giữ màu xanh ngắt - ⏱️ 3 phút]
Đun sôi một nồi nước lớn với 1 thìa cà phê muối hạt đầy. Khi nước sôi sùng sục trên lửa lớn, thả toàn bộ rau muống vào dùng đũa nhấn chìm đều trong đúng 40 giây. Vớt ngay ra thau nước đá lạnh ngâm 2 phút để khóa màu xanh diệp lục và giữ độ giòn sần sật, sau đó vớt ra rổ xóc thật ráo nước.

[Bước 2: Phi thơm tỏi vàng giòn - ⏱️ 1 phút]
Đặt chảo gang hoặc chảo sâu lòng lên bếp bật lửa lớn, cho 2 muỗng canh dầu ăn vào đun nóng già. Cho 2/3 lượng tỏi đập dập vào phi nhanh trong 15 giây đến khi tỏi ngả vàng nhạt và tỏa mùi thơm nức mũi.

[Bước 3: Xào rau muống lửa cực lớn (Wok Hei) - ⏱️ 2 phút]
Trút toàn bộ rau muống đã ráo nước vào chảo. Giữ ngọn lửa lớn nhất có thể, dùng đũa và muôi đảo thật nhanh tay và liên tục. Nêm 1 muỗng canh dầu hào, 1 thìa nước mắm ngon và 1 thìa hạt nêm. Đảo đều tay trong 60 - 90 giây để từng cọng rau ngấm đều gia vị và áo lớp dầu bóng bẩy.

[Bước 4: Cho tỏi tươi lần 2 & Bày đĩa - ⏱️ 30 giây]
Khi rau vừa chín tới vẫn giữ độ giòn ngọt mọng nước, cho nốt 1/3 lượng tỏi đập dập còn lại vào đảo nhanh 10 giây (lớp tỏi sau giữ mùi hăng thơm tươi mới của tỏi sống kết hợp tỏi phi vàng). Tắt bếp trút ngay ra đĩa phẳng, không để rau trong chảo nóng sẽ làm rau bị ỉu xỉn màu.

💡 Mẹo đầu bếp: Bí quyết rau muống xào xanh ngắt không bao giờ thâm đen: Chần nhanh 40 giây qua nước sôi có muối rồi ngâm đá lạnh, xào trên ngọn lửa lớn nhất và cho tỏi làm 2 đợt.', '1786037313574.webp', 'Món xào', 'Đĩa rau muống xào tỏi xanh ngắt mướt mát giòn sần sật, ngập tràn mùi tỏi phi thơm nức mũi, món rau xào quốc dân không thể thiếu trong bữa cơm Việt.', 'Dễ', '3 - 4 người', 10, 5, '[{"ten":"Rau muống ngọn non","so_luong":1,"don_vi":"bó (~500g)","ghi_chu":"nhặt bớt lá già gốc cứng, rửa sạch"},{"ten":"Tỏi khô ta thơm nồng","so_luong":2,"don_vi":"củ to","ghi_chu":"đập dập thô, chia 2 phần"},{"ten":"Dầu ăn thực vật","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"giúp rau bóng bẩy mướt mắt"},{"ten":"Nước mắm ngon & Dầu hào","so_luong":1,"don_vi":"muỗng canh mỗi loại","ghi_chu":"nêm đậm đà"}]', '[{"buoc":1,"tieu_de":"Chần sơ sốc nhiệt đá lạnh giữ màu xanh ngắt","thoi_gian":"3 phút","noi_dung":"Đun sôi một nồi nước lớn với 1 thìa cà phê muối hạt đầy. Khi nước sôi sùng sục trên lửa lớn, thả toàn bộ rau muống vào dùng đũa nhấn chìm đều trong đúng 40 giây. Vớt ngay ra thau nước đá lạnh ngâm 2 phút để khóa màu xanh diệp lục và giữ độ giòn sần sật, sau đó vớt ra rổ xóc thật ráo nước."},{"buoc":2,"tieu_de":"Phi thơm tỏi vàng giòn","thoi_gian":"1 phút","noi_dung":"Đặt chảo gang hoặc chảo sâu lòng lên bếp bật lửa lớn, cho 2 muỗng canh dầu ăn vào đun nóng già. Cho 2/3 lượng tỏi đập dập vào phi nhanh trong 15 giây đến khi tỏi ngả vàng nhạt và tỏa mùi thơm nức mũi."},{"buoc":3,"tieu_de":"Xào rau muống lửa cực lớn (Wok Hei)","thoi_gian":"2 phút","noi_dung":"Trút toàn bộ rau muống đã ráo nước vào chảo. Giữ ngọn lửa lớn nhất có thể, dùng đũa và muôi đảo thật nhanh tay và liên tục. Nêm 1 muỗng canh dầu hào, 1 thìa nước mắm ngon và 1 thìa hạt nêm. Đảo đều tay trong 60 - 90 giây để từng cọng rau ngấm đều gia vị và áo lớp dầu bóng bẩy."},{"buoc":4,"tieu_de":"Cho tỏi tươi lần 2 & Bày đĩa","thoi_gian":"30 giây","noi_dung":"Khi rau vừa chín tới vẫn giữ độ giòn ngọt mọng nước, cho nốt 1/3 lượng tỏi đập dập còn lại vào đảo nhanh 10 giây (lớp tỏi sau giữ mùi hăng thơm tươi mới của tỏi sống kết hợp tỏi phi vàng). Tắt bếp trút ngay ra đĩa phẳng, không để rau trong chảo nóng sẽ làm rau bị ỉu xỉn màu."}]', 'Bí quyết rau muống xào xanh ngắt không bao giờ thâm đen: Chần nhanh 40 giây qua nước sôi có muối rồi ngâm đá lạnh, xào trên ngọn lửa lớn nhất và cho tỏi làm 2 đợt.', '{"calo":120,"protein":"5g","chat_beo":"7g","carb":"9g"}', '["Món xào quốc dân","Giòn sần sật","Thơm lừng tỏi phi","Bữa cơm hàng ngày"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (35, 'Ngọn su su xào tỏi', 'Ngọn su su non (400 g), Tỏi khô ta (2 củ), Dầu hào & Hạt nêm (1.5 muỗng canh), Tiêu xay & Nước mắm (1 thìa)', '[Bước 1: Kỹ thuật tước xơ ngọn su su - ⏱️ 10 phút]
Dùng móng tay tước sạch lớp xơ cứng bao quanh phần thân cuống su su (tước kỹ từ gốc lên ngọn để khi xào rau mềm giòn không bị bã). Bẻ thân su su thành từng đoạn dài 5 - 6cm, lá non vò nhẹ. Rửa sạch ngâm nước muối 5 phút rồi vớt ra để thật ráo.

[Bước 2: Phi thơm tỏi vàng ruộm - ⏱️ 1 phút]
Đun nóng chảo với 1.5 muỗng dầu ăn trên lửa lớn, cho tỏi đập dập vào phi thơm vàng trong 15 giây.

[Bước 3: Xào nhanh tay lửa lớn - ⏱️ 3 phút]
Trút ngọn su su vào đảo nhanh tay trên lửa lớn. Thêm 2 thìa canh nước sôi vào chảo (hơi nước sôi giúp su su chín đều nhanh mà không bị khô cháy). Nêm 1 thìa dầu hào, 1 thìa hạt nêm và chút nước mắm đảo đều tay trong 2 phút.

[Bước 4: Hoàn thiện & Bày đĩa - ⏱️ 30 giây]
Khi ngọn su su vừa chín tới chuyển màu xanh nõn chuối bóng mượt giòn ngọt, tắt bếp ngay. Rắc chút tiêu xay rồi trút ra đĩa thưởng thức nóng.

💡 Mẹo đầu bếp: Tước kỹ lớp xơ cuống và thêm 2 thìa nước sôi khi xào giúp cọng su su chín mềm từ trong ruột mà lớp vỏ ngoài vẫn giòn sần sật mọng nước.', '1786037326995.webp', 'Món xào', 'Ngọn su su bánh tẻ non xanh giòn ngọt tự nhiên xào cùng tỏi thơm nức, món rau đặc sản vùng cao mát lành cực kỳ bắt cơm.', 'Dễ', '3 người', 15, 5, '[{"ten":"Ngọn su su non","so_luong":400,"don_vi":"g","ghi_chu":"tước sạch xơ cuống, bẻ đoạn ngắn 5cm"},{"ten":"Tỏi khô ta","so_luong":2,"don_vi":"củ","ghi_chu":"đập dập thô"},{"ten":"Dầu hào & Hạt nêm","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo độ bóng ngậy"},{"ten":"Tiêu xay & Nước mắm","so_luong":1,"don_vi":"thìa","ghi_chu":"tạo mùi thơm"}]', '[{"buoc":1,"tieu_de":"Kỹ thuật tước xơ ngọn su su","thoi_gian":"10 phút","noi_dung":"Dùng móng tay tước sạch lớp xơ cứng bao quanh phần thân cuống su su (tước kỹ từ gốc lên ngọn để khi xào rau mềm giòn không bị bã). Bẻ thân su su thành từng đoạn dài 5 - 6cm, lá non vò nhẹ. Rửa sạch ngâm nước muối 5 phút rồi vớt ra để thật ráo."},{"buoc":2,"tieu_de":"Phi thơm tỏi vàng ruộm","thoi_gian":"1 phút","noi_dung":"Đun nóng chảo với 1.5 muỗng dầu ăn trên lửa lớn, cho tỏi đập dập vào phi thơm vàng trong 15 giây."},{"buoc":3,"tieu_de":"Xào nhanh tay lửa lớn","thoi_gian":"3 phút","noi_dung":"Trút ngọn su su vào đảo nhanh tay trên lửa lớn. Thêm 2 thìa canh nước sôi vào chảo (hơi nước sôi giúp su su chín đều nhanh mà không bị khô cháy). Nêm 1 thìa dầu hào, 1 thìa hạt nêm và chút nước mắm đảo đều tay trong 2 phút."},{"buoc":4,"tieu_de":"Hoàn thiện & Bày đĩa","thoi_gian":"30 giây","noi_dung":"Khi ngọn su su vừa chín tới chuyển màu xanh nõn chuối bóng mượt giòn ngọt, tắt bếp ngay. Rắc chút tiêu xay rồi trút ra đĩa thưởng thức nóng."}]', 'Tước kỹ lớp xơ cuống và thêm 2 thìa nước sôi khi xào giúp cọng su su chín mềm từ trong ruột mà lớp vỏ ngoài vẫn giòn sần sật mọng nước.', '{"calo":110,"protein":"4g","chat_beo":"6g","carb":"10g"}', '["Đặc sản miền núi","Giòn ngọt tự nhiên","Giàu chất xơ","Món xào thanh nhẹ"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (36, 'Bắp cải xào thịt heo', 'Bắp cải tươi (400 g), Thịt ba chỉ heo (200 g), Cà chua chín (1 quả), Hành tím & Hành hoa (3 nhánh), Nước mắm & Tiêu xay (1.5 muỗng canh)', '[Bước 1: Thái sợi bắp cải & Ráo nước - ⏱️ 5 phút]
Bắp cải bỏ lá già, thái sợi bản rộng khoảng 0.8cm (không thái quá mỏng xào sẽ bị nhũn nát ra nước). Rửa sạch ngâm nước muối 5 phút rồi vớt ra rổ xóc thật ráo nước.

[Bước 2: Đảo thịt ba chỉ ra mỡ xém cạnh - ⏱️ 4 phút]
Cho thịt ba chỉ vào chảo nóng ở lửa vừa (không cho dầu ăn). Đảo đều tay 3 - 4 phút cho thịt tiết bớt mỡ thơm và các cạnh xém vàng nâu, cho hành tím vào phi thơm cùng.

[Bước 3: Xào bắp cải lửa lớn không ra nước - ⏱️ 4 phút]
Tăng lửa lớn, trút toàn bộ bắp cải và cà chua vào chảo xào chung với mỡ thịt. Đảo thật nhanh tay liên tục, nêm 1.5 muỗng nước mắm ngon và 1 thìa hạt nêm. Xào trong 3 phút đến khi sợi bắp cải vừa chín tới mềm mà vẫn giữ độ giòn sần sật.

[Bước 4: Rắc hành tiêu & Trình bày - ⏱️ 1 phút]
Rắc hành hoa cắt khúc và hạt tiêu xay thơm nồng vào chảo, đảo đều 10 giây rồi tắt bếp ngay. Múc ra đĩa lớn thưởng thức nóng cùng cơm trắng.

💡 Mẹo đầu bếp: Xào bắp cải bắt buộc phải để lửa thật lớn và không đậy nắp vung; bắp cải sẽ giữ nguyên độ giòn ngọt mọng nước tự nhiên mà không bị chảy nước lênh láng ra đĩa.', '1786037340314.webp', 'Món xào', 'Bắp cải giòn ngọt xào cùng thịt ba chỉ béo ngậy thái mỏng xém cạnh, rắc chút hành hoa tiêu sọ thơm lừng, món xào ấm cúng cho bữa cơm sum họp.', 'Dễ', '3 - 4 người', 10, 10, '[{"ten":"Bắp cải tươi","so_luong":400,"don_vi":"g","ghi_chu":"thái sợi bản dày 0.8cm"},{"ten":"Thịt ba chỉ heo","so_luong":200,"don_vi":"g","ghi_chu":"thái lát mỏng 2mm"},{"ten":"Cà chua chín","so_luong":1,"don_vi":"quả","ghi_chu":"bổ múi cau tạo vị chua thanh"},{"ten":"Hành tím & Hành hoa","so_luong":3,"don_vi":"nhánh","ghi_chu":"thái nhỏ"},{"ten":"Nước mắm & Tiêu xay","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"nêm vừa vị"}]', '[{"buoc":1,"tieu_de":"Thái sợi bắp cải & Ráo nước","thoi_gian":"5 phút","noi_dung":"Bắp cải bỏ lá già, thái sợi bản rộng khoảng 0.8cm (không thái quá mỏng xào sẽ bị nhũn nát ra nước). Rửa sạch ngâm nước muối 5 phút rồi vớt ra rổ xóc thật ráo nước."},{"buoc":2,"tieu_de":"Đảo thịt ba chỉ ra mỡ xém cạnh","thoi_gian":"4 phút","noi_dung":"Cho thịt ba chỉ vào chảo nóng ở lửa vừa (không cho dầu ăn). Đảo đều tay 3 - 4 phút cho thịt tiết bớt mỡ thơm và các cạnh xém vàng nâu, cho hành tím vào phi thơm cùng."},{"buoc":3,"tieu_de":"Xào bắp cải lửa lớn không ra nước","thoi_gian":"4 phút","noi_dung":"Tăng lửa lớn, trút toàn bộ bắp cải và cà chua vào chảo xào chung với mỡ thịt. Đảo thật nhanh tay liên tục, nêm 1.5 muỗng nước mắm ngon và 1 thìa hạt nêm. Xào trong 3 phút đến khi sợi bắp cải vừa chín tới mềm mà vẫn giữ độ giòn sần sật."},{"buoc":4,"tieu_de":"Rắc hành tiêu & Trình bày","thoi_gian":"1 phút","noi_dung":"Rắc hành hoa cắt khúc và hạt tiêu xay thơm nồng vào chảo, đảo đều 10 giây rồi tắt bếp ngay. Múc ra đĩa lớn thưởng thức nóng cùng cơm trắng."}]', 'Xào bắp cải bắt buộc phải để lửa thật lớn và không đậy nắp vung; bắp cải sẽ giữ nguyên độ giòn ngọt mọng nước tự nhiên mà không bị chảy nước lênh láng ra đĩa.', '{"calo":260,"protein":"15g","chat_beo":"18g","carb":"11g"}', '["Món xào gia đình","Giòn ngọt","Đưa cơm mùa lạnh","Dễ làm"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (37, 'Mướp xào lòng gà', 'Mướp hương non (2 quả (~400g)), Bộ lòng mề gan gà tươi (2 bộ (~250g)), Hành tím & Hành hoa (3 nhánh), Dầu hào & Nước mắm (1.5 muỗng canh)', '[Bước 1: Sơ chế sạch lòng gà & Khía hoa mề - ⏱️ 10 phút]
Mề gà bóc màng vàng, bóp kỹ với muối hạt và chanh trong 3 phút rửa sạch nhớt. Khía hoa ca-rô trên mặt mề rồi thái miếng vừa ăn (khía hoa giúp mề gà khi xào nở giòn đẹp mắt). Gan và lòng thái khúc 3cm. Ướp với 1 thìa cà phê nước mắm, tiêu và hành tím trong 10 phút.

[Bước 2: Xào chín tới lòng mề gà - ⏱️ 3 phút]
Phi thơm hành tím với 1 thìa dầu ăn trên lửa lớn, trút lòng mề gà vào xào đảo nhanh tay trong 2.5 - 3 phút cho lòng chín tới săn giòn rồi múc ra đĩa riêng (không để lại trong chảo).

[Bước 3: Xào mướp hương ngọt thơm - ⏱️ 2 phút]
Thêm chút dầu vào chảo, cho mướp hương thái vát vào đảo nhanh tay trên lửa lớn cùng 1 thìa hạt nêm và 1 thìa nước lọc trong 1.5 phút cho mướp vừa chuyển màu xanh trong tái chín.

[Bước 4: Hòa quyện & Bày đĩa - ⏱️ 1 phút]
Đổ đĩa lòng gà trở lại chảo mướp, đảo nhanh tay trong 30 giây cho ngấm vị mướp ngọt ngào. Rắc hành hoa, tiêu xay rồi tắt bếp trút ngay ra đĩa (không xào lâu mướp sẽ nhũn ra nước).

💡 Mẹo đầu bếp: Xào lòng mề gà riêng rồi mới xào mướp; chỉ trộn chung 30 giây cuối để mướp không bị thâm nhũn và lòng gà giữ trọn độ giòn sần sật sảng khoái.', '1786037352718.webp', 'Món xào', 'Mướp hương mềm mượt thơm nức mũi xào cùng lòng mề gà giòn sần sật đậm đà, món ăn thanh tao ngọt vị quen thuộc trong mâm cơm mùa hè.', 'Dễ', '3 người', 15, 8, '[{"ten":"Mướp hương non","so_luong":2,"don_vi":"quả (~400g)","ghi_chu":"gọt vỏ thái vát xéo dày 1.5cm"},{"ten":"Bộ lòng mề gan gà tươi","so_luong":2,"don_vi":"bộ (~250g)","ghi_chu":"bóp muối khử sạch mùi"},{"ten":"Hành tím & Hành hoa","so_luong":3,"don_vi":"nhánh","ghi_chu":"thái nhỏ"},{"ten":"Dầu hào & Nước mắm","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"nêm nếm đậm đà"}]', '[{"buoc":1,"tieu_de":"Sơ chế sạch lòng gà & Khía hoa mề","thoi_gian":"10 phút","noi_dung":"Mề gà bóc màng vàng, bóp kỹ với muối hạt và chanh trong 3 phút rửa sạch nhớt. Khía hoa ca-rô trên mặt mề rồi thái miếng vừa ăn (khía hoa giúp mề gà khi xào nở giòn đẹp mắt). Gan và lòng thái khúc 3cm. Ướp với 1 thìa cà phê nước mắm, tiêu và hành tím trong 10 phút."},{"buoc":2,"tieu_de":"Xào chín tới lòng mề gà","thoi_gian":"3 phút","noi_dung":"Phi thơm hành tím với 1 thìa dầu ăn trên lửa lớn, trút lòng mề gà vào xào đảo nhanh tay trong 2.5 - 3 phút cho lòng chín tới săn giòn rồi múc ra đĩa riêng (không để lại trong chảo)."},{"buoc":3,"tieu_de":"Xào mướp hương ngọt thơm","thoi_gian":"2 phút","noi_dung":"Thêm chút dầu vào chảo, cho mướp hương thái vát vào đảo nhanh tay trên lửa lớn cùng 1 thìa hạt nêm và 1 thìa nước lọc trong 1.5 phút cho mướp vừa chuyển màu xanh trong tái chín."},{"buoc":4,"tieu_de":"Hòa quyện & Bày đĩa","thoi_gian":"1 phút","noi_dung":"Đổ đĩa lòng gà trở lại chảo mướp, đảo nhanh tay trong 30 giây cho ngấm vị mướp ngọt ngào. Rắc hành hoa, tiêu xay rồi tắt bếp trút ngay ra đĩa (không xào lâu mướp sẽ nhũn ra nước)."}]', 'Xào lòng mề gà riêng rồi mới xào mướp; chỉ trộn chung 30 giây cuối để mướp không bị thâm nhũn và lòng gà giữ trọn độ giòn sần sật sảng khoái.', '{"calo":210,"protein":"20g","chat_beo":"10g","carb":"10g"}', '["Mướp hương thơm ngát","Giòn sần sật","Thanh mát","Món xào dân dã"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (38, 'Đậu cove xào thịt bò', 'Đậu cove non tươi (350 g), Thịt thăn bò tươi (250 g), Tỏi khô ta băm nhuyễn (2 củ), Dầu hào & Nước tương (1.5 muỗng canh)', '[Bước 1: Ướp thịt bò mềm mọng với dầu hào - ⏱️ 15 phút]
Thịt bò thái mỏng ngang thớ, ướp với 1 muỗng dầu hào, 1/2 lượng tỏi băm, 1/2 thìa tiêu và 1 thìa canh dầu ăn trong 15 phút để thớ thịt giữ ẩm.

[Bước 2: Xào tái thịt bò lửa lớn - ⏱️ 2 phút]
Phi thơm tỏi trên chảo lửa lớn với 1 thìa dầu ăn, trút thịt bò vào đảo cực nhanh tay trong 60 giây cho thịt vừa chín tái hồng thì trút ngay ra đĩa riêng.

[Bước 3: Xào đậu cove giòn ngọt - ⏱️ 4 phút]
Cho đậu cove thái vát vào chảo đảo đều trên lửa lớn, thêm 3 thìa nước sôi và 1 thìa hạt nêm. Đậy vung chảo trong 1 phút cho hơi nước làm đậu chín giòn đều từ bên trong mà vẫn xanh mướt.

[Bước 4: Trộn đều & Hoàn tất - ⏱️ 1 phút]
Đổ đĩa thịt bò cùng toàn bộ nước ngọt vào chảo đậu, đảo nhanh tay 30 giây cho hòa quyện rồi tắt bếp, rắc tiêu xay và trút ra đĩa thưởng thức nóng.

💡 Mẹo đầu bếp: Thêm 3 thìa nước sôi và đậy vung 1 phút khi xào đậu cove giúp hạt đậu chín ngọt mềm mà vỏ ngoài vẫn giữ màu xanh nõn chuối giòn tan.', '1786036772485.webp', 'Món xào', 'Từng quả đậu cove xanh giòn ngọt tự nhiên xào quyện cùng những lát thịt bò thăn mềm mọng đẫm dầu hào và tỏi phi thơm nức mũi.', 'Dễ', '3 - 4 người', 15, 8, '[{"ten":"Đậu cove non tươi","so_luong":350,"don_vi":"g","ghi_chu":"tước xơ 2 bên, thái vát xéo mỏng"},{"ten":"Thịt thăn bò tươi","so_luong":250,"don_vi":"g","ghi_chu":"thái mỏng ngang thớ bản rộng"},{"ten":"Tỏi khô ta băm nhuyễn","so_luong":2,"don_vi":"củ","ghi_chu":"phi thơm"},{"ten":"Dầu hào & Nước tương","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo màu nâu bóng thơm béo"}]', '[{"buoc":1,"tieu_de":"Ướp thịt bò mềm mọng với dầu hào","thoi_gian":"15 phút","noi_dung":"Thịt bò thái mỏng ngang thớ, ướp với 1 muỗng dầu hào, 1/2 lượng tỏi băm, 1/2 thìa tiêu và 1 thìa canh dầu ăn trong 15 phút để thớ thịt giữ ẩm."},{"buoc":2,"tieu_de":"Xào tái thịt bò lửa lớn","thoi_gian":"2 phút","noi_dung":"Phi thơm tỏi trên chảo lửa lớn với 1 thìa dầu ăn, trút thịt bò vào đảo cực nhanh tay trong 60 giây cho thịt vừa chín tái hồng thì trút ngay ra đĩa riêng."},{"buoc":3,"tieu_de":"Xào đậu cove giòn ngọt","thoi_gian":"4 phút","noi_dung":"Cho đậu cove thái vát vào chảo đảo đều trên lửa lớn, thêm 3 thìa nước sôi và 1 thìa hạt nêm. Đậy vung chảo trong 1 phút cho hơi nước làm đậu chín giòn đều từ bên trong mà vẫn xanh mướt."},{"buoc":4,"tieu_de":"Trộn đều & Hoàn tất","thoi_gian":"1 phút","noi_dung":"Đổ đĩa thịt bò cùng toàn bộ nước ngọt vào chảo đậu, đảo nhanh tay 30 giây cho hòa quyện rồi tắt bếp, rắc tiêu xay và trút ra đĩa thưởng thức nóng."}]', 'Thêm 3 thìa nước sôi và đậy vung 1 phút khi xào đậu cove giúp hạt đậu chín ngọt mềm mà vỏ ngoài vẫn giữ màu xanh nõn chuối giòn tan.', '{"calo":270,"protein":"29g","chat_beo":"9g","carb":"18g"}', '["Giàu đạm & xơ","Eat Clean","Nhanh gọn","Bổ dưỡng gia đình"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (39, 'Bông cải xanh xào tôm', 'Bông cải xanh (súp lơ) (1 cây (~400g)), Tôm sú tươi bóc nõn (250 g), Cà rốt tỉa hoa (0.5 củ), Tỏi khô ta băm (1.5 củ), Dầu hào & Dầu mè (1.5 muỗng canh)', '[Bước 1: Chần sơ bông cải xanh giữ vitamin - ⏱️ 3 phút]
Đun sôi nồi nước với 1 thìa cà phê muối. Thả bông cải xanh và cà rốt vào chần nhanh đúng 60 giây rồi vớt ra ngâm ngay vào thau nước đá lạnh 2 phút, vớt ra để ráo.

[Bước 2: Xào săn tôm tươi đỏ au - ⏱️ 2 phút]
Phi thơm tỏi băm trên chảo với 1 thìa dầu ăn, trút tôm vào đảo đều trên lửa lớn trong 1.5 phút đến khi tôm chuyển màu đỏ cam săn chắc thì trút ra đĩa riêng.

[Bước 3: Xào bông cải xanh ngấm sốt dầu hào - ⏱️ 2 phút]
Cho súp lơ và cà rốt vào chảo đảo đều trên lửa lớn cùng 1 muỗng dầu hào và 1 thìa hạt nêm trong 1.5 phút cho rau củ bóng bẩy ngấm vị.

[Bước 4: Hòa quyện & Dầu mè thơm ngậy - ⏱️ 1 phút]
Trút đĩa tôm vào đảo chung 30 giây, nhỏ vài giọt dầu mè thơm ngậy lên mặt rồi tắt bếp trút ra đĩa thưởng thức nóng.

💡 Mẹo đầu bếp: Chần sơ súp lơ qua nước sôi rồi ngâm đá lạnh trước khi xào giúp giữ nguyên 100% vitamin và độ giòn ngọt mọng nước tự nhiên.', '1786036757571.webp', 'Món xào', 'Tôm tươi chắc ngọt đỏ au xào cùng bông cải xanh giòn mát thấm đẫm sốt tỏi dầu hào bóng bẩy, món ăn giàu vitamin và khoáng chất tốt cho sức khỏe.', 'Dễ', '3 người', 15, 8, '[{"ten":"Bông cải xanh (súp lơ)","so_luong":1,"don_vi":"cây (~400g)","ghi_chu":"tách nhánh vừa ăn, ngâm nước muối"},{"ten":"Tôm sú tươi bóc nõn","so_luong":250,"don_vi":"g","ghi_chu":"chừa đuôi rút sạch chỉ lưng"},{"ten":"Cà rốt tỉa hoa","so_luong":0.5,"don_vi":"củ","ghi_chu":"thái mỏng 2mm"},{"ten":"Tỏi khô ta băm","so_luong":1.5,"don_vi":"củ","ghi_chu":"phi thơm"},{"ten":"Dầu hào & Dầu mè","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tạo mùi thơm béo"}]', '[{"buoc":1,"tieu_de":"Chần sơ bông cải xanh giữ vitamin","thoi_gian":"3 phút","noi_dung":"Đun sôi nồi nước với 1 thìa cà phê muối. Thả bông cải xanh và cà rốt vào chần nhanh đúng 60 giây rồi vớt ra ngâm ngay vào thau nước đá lạnh 2 phút, vớt ra để ráo."},{"buoc":2,"tieu_de":"Xào săn tôm tươi đỏ au","thoi_gian":"2 phút","noi_dung":"Phi thơm tỏi băm trên chảo với 1 thìa dầu ăn, trút tôm vào đảo đều trên lửa lớn trong 1.5 phút đến khi tôm chuyển màu đỏ cam săn chắc thì trút ra đĩa riêng."},{"buoc":3,"tieu_de":"Xào bông cải xanh ngấm sốt dầu hào","thoi_gian":"2 phút","noi_dung":"Cho súp lơ và cà rốt vào chảo đảo đều trên lửa lớn cùng 1 muỗng dầu hào và 1 thìa hạt nêm trong 1.5 phút cho rau củ bóng bẩy ngấm vị."},{"buoc":4,"tieu_de":"Hòa quyện & Dầu mè thơm ngậy","thoi_gian":"1 phút","noi_dung":"Trút đĩa tôm vào đảo chung 30 giây, nhỏ vài giọt dầu mè thơm ngậy lên mặt rồi tắt bếp trút ra đĩa thưởng thức nóng."}]', 'Chần sơ súp lơ qua nước sôi rồi ngâm đá lạnh trước khi xào giúp giữ nguyên 100% vitamin và độ giòn ngọt mọng nước tự nhiên.', '{"calo":230,"protein":"26g","chat_beo":"6g","carb":"16g"}', '["Healthy","Giàu canxi & vitamin C","Màu sắc hấp dẫn","Tốt cho tim mạch"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (40, 'Rau lang xào tỏi', 'Rau lang non (khoai lang) (400 g), Tỏi khô ta (2 củ to), Dầu ăn (2 muỗng canh), Hạt nêm & Nước mắm (1 muỗng canh)', '[Bước 1: Chần nhanh khử nhựa chát & Giữ màu xanh - ⏱️ 3 phút]
Đun sôi nồi nước lớn với 1 thìa muối hạt. Thả rau lang vào chần nhanh trong 40 giây rồi vớt ra ngâm ngay vào nước lạnh (chần nhanh giúp khử sạch chất nhựa chát và ngăn rau bị thâm đen).

[Bước 2: Phi thơm ngập tỏi vàng giòn - ⏱️ 1 phút]
Đun nóng chảo với 2 muỗng dầu ăn, phi thơm tỏi đập dập trên lửa vừa đến khi dậy mùi thơm nức mũi.

[Bước 3: Xào nhanh tay lửa lớn - ⏱️ 2 phút]
Trút rau lang vào đảo thật nhanh tay trên ngọn lửa lớn nhất, nêm 1 thìa hạt nêm và 1 thìa nước mắm ngon cho rau ngấm đều gia vị bóng bẩy.

[Bước 4: Hoàn tất & Thưởng thức - ⏱️ 30 giây]
Rau chín mềm mượt mà vẫn giữ màu xanh tươi mát, tắt bếp ngay và trút ra đĩa dùng nóng.

💡 Mẹo đầu bếp: Rau lang rất dễ bị thâm đen do nhựa; chần nhanh 40 giây qua nước sôi có muối hạt sẽ giữ cho đĩa rau lang xào luôn xanh mướt mượt mà.', '1786036745728.webp', 'Món xào', 'Ngọn rau lang non mướt xào mềm ngọt hòa cùng hương tỏi phi thơm lừng nức mũi, món rau dân dã giàu chất xơ và cực kỳ nhuận tràng tốt cho tiêu hóa.', 'Dễ', '3 người', 10, 5, '[{"ten":"Rau lang non (khoai lang)","so_luong":400,"don_vi":"g","ghi_chu":"nhặt ngọn non búp lá, ngâm muối rửa sạch"},{"ten":"Tỏi khô ta","so_luong":2,"don_vi":"củ to","ghi_chu":"đập dập thô"},{"ten":"Dầu ăn","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"xào rau bóng mượt"},{"ten":"Hạt nêm & Nước mắm","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"nêm vừa miệng"}]', '[{"buoc":1,"tieu_de":"Chần nhanh khử nhựa chát & Giữ màu xanh","thoi_gian":"3 phút","noi_dung":"Đun sôi nồi nước lớn với 1 thìa muối hạt. Thả rau lang vào chần nhanh trong 40 giây rồi vớt ra ngâm ngay vào nước lạnh (chần nhanh giúp khử sạch chất nhựa chát và ngăn rau bị thâm đen)."},{"buoc":2,"tieu_de":"Phi thơm ngập tỏi vàng giòn","thoi_gian":"1 phút","noi_dung":"Đun nóng chảo với 2 muỗng dầu ăn, phi thơm tỏi đập dập trên lửa vừa đến khi dậy mùi thơm nức mũi."},{"buoc":3,"tieu_de":"Xào nhanh tay lửa lớn","thoi_gian":"2 phút","noi_dung":"Trút rau lang vào đảo thật nhanh tay trên ngọn lửa lớn nhất, nêm 1 thìa hạt nêm và 1 thìa nước mắm ngon cho rau ngấm đều gia vị bóng bẩy."},{"buoc":4,"tieu_de":"Hoàn tất & Thưởng thức","thoi_gian":"30 giây","noi_dung":"Rau chín mềm mượt mà vẫn giữ màu xanh tươi mát, tắt bếp ngay và trút ra đĩa dùng nóng."}]', 'Rau lang rất dễ bị thâm đen do nhựa; chần nhanh 40 giây qua nước sôi có muối hạt sẽ giữ cho đĩa rau lang xào luôn xanh mướt mượt mà.', '{"calo":115,"protein":"4g","chat_beo":"6g","carb":"11g"}', '["Nhuận tràng","Dân dã thanh mát","Dễ làm","Thơm lừng tỏi phi"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (41, 'Rau luộc thập cẩm', 'Bắp cải tươi (200 g), Cà rốt & Su hào (1 củ mỗi loại), Đậu cove non (100 g), Bông cải xanh (150 g), Muối hạt tinh khiết (1 thìa cà phê)', '[Bước 1: Sơ chế & Tỉa hoa củ quả đồng đều - ⏱️ 8 phút]
Cà rốt, su hào gọt vỏ tỉa hoa cắt thanh que dày 1.2cm. Đậu cove tước xơ bẻ đôi. Súp lơ tách nhánh, bắp cải cắt miếng vuông 4 x 4cm. Rửa sạch tất cả để ráo.

[Bước 2: Luộc củ cứng trước chuẩn thời gian - ⏱️ 4 phút]
Đun sôi 1.5 lít nước với 1 thìa muối hạt. Thả cà rốt và su hào vào luộc trước trong đúng 3 phút vì củ cứng lâu chín hơn.

[Bước 3: Luộc rau mềm tiếp theo - ⏱️ 3 phút]
Tiếp tục cho đậu cove, súp lơ xanh và bắp cải vào luộc chung thêm 2.5 - 3 phút cho tất cả vừa chín tới vẫn giữ độ giòn ngọt mọng nước.

[Bước 4: Bày đĩa thập cẩm ngũ sắc - ⏱️ 2 phút]
Dùng muôi thủng vớt rau củ ra xếp xen kẽ màu sắc đỏ, cam, xanh, trắng quanh đĩa tròn, dọn kèm chén kho quẹt tôm thịt hoặc nước chấm kho đậm đà.

💡 Mẹo đầu bếp: Luộc theo thứ tự: củ cứng (cà rốt, su hào) cho vào trước, rau mềm (súp lơ, bắp cải) cho vào sau để tất cả cùng chín tới giòn ngọt đều nhau.', '1786036732528.webp', 'Rau', 'Đĩa củ quả thập cẩm luộc đủ sắc màu rực rỡ xanh đỏ trắng giòn ngọt thanh tao, chấm kèm kho quẹt tộ đất hay muối vừng bùi béo tuyệt ngon.', 'Dễ', '4 người', 15, 10, '[{"ten":"Bắp cải tươi","so_luong":200,"don_vi":"g","ghi_chu":"cắt miếng vuông 4cm"},{"ten":"Cà rốt & Su hào","so_luong":1,"don_vi":"củ mỗi loại","ghi_chu":"tỉa hoa cắt thanh que dày 1.2cm"},{"ten":"Đậu cove non","so_luong":100,"don_vi":"g","ghi_chu":"tước xơ bẻ đôi"},{"ten":"Bông cải xanh","so_luong":150,"don_vi":"g","ghi_chu":"tách nhánh vừa ăn"},{"ten":"Muối hạt tinh khiết","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"cho vào nước luộc giữ màu"}]', '[{"buoc":1,"tieu_de":"Sơ chế & Tỉa hoa củ quả đồng đều","thoi_gian":"8 phút","noi_dung":"Cà rốt, su hào gọt vỏ tỉa hoa cắt thanh que dày 1.2cm. Đậu cove tước xơ bẻ đôi. Súp lơ tách nhánh, bắp cải cắt miếng vuông 4 x 4cm. Rửa sạch tất cả để ráo."},{"buoc":2,"tieu_de":"Luộc củ cứng trước chuẩn thời gian","thoi_gian":"4 phút","noi_dung":"Đun sôi 1.5 lít nước với 1 thìa muối hạt. Thả cà rốt và su hào vào luộc trước trong đúng 3 phút vì củ cứng lâu chín hơn."},{"buoc":3,"tieu_de":"Luộc rau mềm tiếp theo","thoi_gian":"3 phút","noi_dung":"Tiếp tục cho đậu cove, súp lơ xanh và bắp cải vào luộc chung thêm 2.5 - 3 phút cho tất cả vừa chín tới vẫn giữ độ giòn ngọt mọng nước."},{"buoc":4,"tieu_de":"Bày đĩa thập cẩm ngũ sắc","thoi_gian":"2 phút","noi_dung":"Dùng muôi thủng vớt rau củ ra xếp xen kẽ màu sắc đỏ, cam, xanh, trắng quanh đĩa tròn, dọn kèm chén kho quẹt tôm thịt hoặc nước chấm kho đậm đà."}]', 'Luộc theo thứ tự: củ cứng (cà rốt, su hào) cho vào trước, rau mềm (súp lơ, bắp cải) cho vào sau để tất cả cùng chín tới giòn ngọt đều nhau.', '{"calo":90,"protein":"4g","chat_beo":"1g","carb":"18g"}', '["Thanh lọc cơ thể","Chấm kho quẹt cực phẩm","Giàu vitamin","Không dầu mỡ"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (42, 'Dưa leo trộn chua ngọt', 'Dưa leo (dưa chuột) tươi (3 quả (~400g)), Tỏi khô ta & Ớt sừng (1.5 củ / trái), Giấm gạo lên men tự nhiên (2 muỗng canh), Đường cát trắng (2 muỗng canh), Nước mắm & Rau mùi (1 muỗng canh)', '[Bước 1: Nạo ruột dưa & Thái lát xéo - ⏱️ 5 phút]
Dưa leo ngâm nước muối 10 phút, gọt vỏ sọc dưa xen kẽ, chẻ đôi theo chiều dọc. Dùng thìa nhỏ nạo sạch phần ruột ướt ở giữa (ruột dưa là phần làm nộm bị chảy nước ỉu nhão). Dùng dao sắc thái lát xéo dày 0.5cm.

[Bước 2: Kỹ thuật xóc muối rút nước giòn đanh - ⏱️ 5 phút]
Trộn dưa leo với 1/2 thìa cà phê muối hạt trong 5 phút để dưa tiết bớt nước hăng, xả nhanh lại với nước lạnh rồi dùng tay vắt nhẹ ráo nước (bước này giúp từng lát dưa giòn tan đanh sần sật).

[Bước 3: Pha nước sốt chua ngọt tỏi ớt - ⏱️ 3 phút]
Khuấy tan hoàn toàn hỗn hợp gồm: 2 muỗng đường, 2 muỗng giấm gạo, 1 muỗng nước mắm cùng tỏi băm và ớt băm nhuyễn.

[Bước 4: Trộn đều & Ướp lạnh - ⏱️ 15 phút]
Đổ nước sốt vào dưa leo trộn đều tay, để trong ngăn mát tủ lạnh 15 phút cho ngấm sâu vị chua ngọt mát lạnh rồi rắc rau mùi thái nhỏ thưởng thức.

💡 Mẹo đầu bếp: Nạo bỏ ruột dưa và xóc muối vắt nhẹ trước khi trộn giúp dưa leo giữ trọn độ giòn rôm rốp cả tiếng mà không bao giờ bị chảy nước lõng bõng.', '1786036718732.webp', 'Rau', 'Từng lát dưa leo giòn tan sần sật thấm đẫm vị chua chua ngọt ngọt cay nhẹ của tỏi ớt, món gỏi nộm giải ngấy số một cho các món chiên xào thịt kho.', 'Dễ', '3 người', 10, 0, '[{"ten":"Dưa leo (dưa chuột) tươi","so_luong":3,"don_vi":"quả (~400g)","ghi_chu":"chọn quả đặc ruột, rửa sạch ngâm muối"},{"ten":"Tỏi khô ta & Ớt sừng","so_luong":1.5,"don_vi":"củ / trái","ghi_chu":"băm nhỏ"},{"ten":"Giấm gạo lên men tự nhiên","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"tạo vị chua thanh"},{"ten":"Đường cát trắng","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"cân bằng chua ngọt"},{"ten":"Nước mắm & Rau mùi","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"tạo hương thơm"}]', '[{"buoc":1,"tieu_de":"Nạo ruột dưa & Thái lát xéo","thoi_gian":"5 phút","noi_dung":"Dưa leo ngâm nước muối 10 phút, gọt vỏ sọc dưa xen kẽ, chẻ đôi theo chiều dọc. Dùng thìa nhỏ nạo sạch phần ruột ướt ở giữa (ruột dưa là phần làm nộm bị chảy nước ỉu nhão). Dùng dao sắc thái lát xéo dày 0.5cm."},{"buoc":2,"tieu_de":"Kỹ thuật xóc muối rút nước giòn đanh","thoi_gian":"5 phút","noi_dung":"Trộn dưa leo với 1/2 thìa cà phê muối hạt trong 5 phút để dưa tiết bớt nước hăng, xả nhanh lại với nước lạnh rồi dùng tay vắt nhẹ ráo nước (bước này giúp từng lát dưa giòn tan đanh sần sật)."},{"buoc":3,"tieu_de":"Pha nước sốt chua ngọt tỏi ớt","thoi_gian":"3 phút","noi_dung":"Khuấy tan hoàn toàn hỗn hợp gồm: 2 muỗng đường, 2 muỗng giấm gạo, 1 muỗng nước mắm cùng tỏi băm và ớt băm nhuyễn."},{"buoc":4,"tieu_de":"Trộn đều & Ướp lạnh","thoi_gian":"15 phút","noi_dung":"Đổ nước sốt vào dưa leo trộn đều tay, để trong ngăn mát tủ lạnh 15 phút cho ngấm sâu vị chua ngọt mát lạnh rồi rắc rau mùi thái nhỏ thưởng thức."}]', 'Nạo bỏ ruột dưa và xóc muối vắt nhẹ trước khi trộn giúp dưa leo giữ trọn độ giòn rôm rốp cả tiếng mà không bao giờ bị chảy nước lõng bõng.', '{"calo":75,"protein":"2g","chat_beo":"0.5g","carb":"15g"}', '["Món kèm giải ngấy","Giòn tan sần sật","Chua ngọt dịu mát","Không dầu mỡ"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (43, 'Kim chi cải thảo', 'Cải thảo búp tươi chắc (1.5 kg), Bột ớt vảy Hàn Quốc (60 g), Củ cải trắng & Cà rốt (1 củ mỗi loại), Hẹ & Hành boa-rô (100 g), Lê ngọt hoặc táo chín (0.5 quả), Hồ nếp nấu chín để nguội (1 chén nhỏ)', '[Bước 1: Xát muối làm mềm bẹ cải thảo - ⏱️ 30 phút]
Cải thảo chẻ làm tư, xát kỹ muối hạt vào từng bẹ lá từ trong ra ngoài. Để nghỉ trong 2 tiếng cho bẹ cải thảo dẻo dai uốn cong không gãy. Xả sạch lại 3 lần nước lạnh cho hết vị mặn gắt rồi dùng tay vắt thật ráo nước.

[Bước 2: Nấu hồ nếp & Xay hỗn hợp sốt lê táo - ⏱️ 10 phút]
Khuấy 2 thìa bột nếp với 1 chén nước trên lửa nhỏ thành hồ loãng sánh để nguội. Xay nhuyễn nửa quả lê cùng tỏi, gừng, hành tây và nước mắm. Trộn hồ nếp cùng hỗn hợp lê xay, 60g bột ớt Hàn Quốc và 1.5 muỗng đường thành âu sốt đỏ au sền sệt thơm nức.

[Bước 3: Trộn nhân củ cải hẹ - ⏱️ 5 phút]
Cho củ cải bào sợi, cà rốt và hẹ cắt khúc vào âu sốt trộn đều tay để làm phần nhân kim chi thơm ngọt.

[Bước 4: Phết sốt vào từng bẹ lá & Lên men chuẩn vị - ⏱️ 15 phút]
Đeo găng tay, phết đều hỗn hợp sốt nhân vào từng kẽ lá cải thảo từ trong ra ngoài. Cuộn tròn bắp cải xếp chặt vào hộp thủy tinh kín nắp. Để ở nhiệt độ phòng 1 - 2 ngày cho lên men chua dịu rồi bảo quản trong ngăn mát tủ lạnh dùng dần.

💡 Mẹo đầu bếp: Xay thêm nửa quả lê hoặc táo ngọt vào hỗn hợp sốt kim chi sẽ giúp kim chi lên men chua thanh tự nhiên cực kỳ thơm ngon mà không bị chua gắt chát.', '1786036705786.webp', 'Rau', 'Cải thảo muối giòn đượm màu ớt đỏ rực rỡ, vị cay nồng nàn thơm ngát hương tỏi gừng lê táo, chua dịu kích thích vị giác đưa cơm cực đỉnh.', 'Trung bình', '5 - 6 người', 40, 0, '[{"ten":"Cải thảo búp tươi chắc","so_luong":1.5,"don_vi":"kg","ghi_chu":"chẻ đôi hoặc làm tư, xát muối hạt"},{"ten":"Bột ớt vảy Hàn Quốc","so_luong":60,"don_vi":"g","ghi_chu":"tạo màu đỏ đẹp và vị cay ấm"},{"ten":"Củ cải trắng & Cà rốt","so_luong":1,"don_vi":"củ mỗi loại","ghi_chu":"bào sợi mỏng 3cm"},{"ten":"Hẹ & Hành boa-rô","so_luong":100,"don_vi":"g","ghi_chu":"cắt khúc 4cm"},{"ten":"Lê ngọt hoặc táo chín","so_luong":0.5,"don_vi":"quả","ghi_chu":"xay nhuyễn tạo ngọt lên men tự nhiên"},{"ten":"Hồ nếp nấu chín để nguội","so_luong":1,"don_vi":"chén nhỏ","ghi_chu":"giúp sốt bám dính đều"}]', '[{"buoc":1,"tieu_de":"Xát muối làm mềm bẹ cải thảo","thoi_gian":"30 phút","noi_dung":"Cải thảo chẻ làm tư, xát kỹ muối hạt vào từng bẹ lá từ trong ra ngoài. Để nghỉ trong 2 tiếng cho bẹ cải thảo dẻo dai uốn cong không gãy. Xả sạch lại 3 lần nước lạnh cho hết vị mặn gắt rồi dùng tay vắt thật ráo nước."},{"buoc":2,"tieu_de":"Nấu hồ nếp & Xay hỗn hợp sốt lê táo","thoi_gian":"10 phút","noi_dung":"Khuấy 2 thìa bột nếp với 1 chén nước trên lửa nhỏ thành hồ loãng sánh để nguội. Xay nhuyễn nửa quả lê cùng tỏi, gừng, hành tây và nước mắm. Trộn hồ nếp cùng hỗn hợp lê xay, 60g bột ớt Hàn Quốc và 1.5 muỗng đường thành âu sốt đỏ au sền sệt thơm nức."},{"buoc":3,"tieu_de":"Trộn nhân củ cải hẹ","thoi_gian":"5 phút","noi_dung":"Cho củ cải bào sợi, cà rốt và hẹ cắt khúc vào âu sốt trộn đều tay để làm phần nhân kim chi thơm ngọt."},{"buoc":4,"tieu_de":"Phết sốt vào từng bẹ lá & Lên men chuẩn vị","thoi_gian":"15 phút","noi_dung":"Đeo găng tay, phết đều hỗn hợp sốt nhân vào từng kẽ lá cải thảo từ trong ra ngoài. Cuộn tròn bắp cải xếp chặt vào hộp thủy tinh kín nắp. Để ở nhiệt độ phòng 1 - 2 ngày cho lên men chua dịu rồi bảo quản trong ngăn mát tủ lạnh dùng dần."}]', 'Xay thêm nửa quả lê hoặc táo ngọt vào hỗn hợp sốt kim chi sẽ giúp kim chi lên men chua thanh tự nhiên cực kỳ thơm ngon mà không bị chua gắt chát.', '{"calo":85,"protein":"3g","chat_beo":"1g","carb":"16g"}', '["Món muối chua ngon","Men vi sinh Probiotic","Cay nồng đưa cơm","Giải ngấy tuyệt vời"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (44, 'Đậu hũ chiên giòn', 'Đậu hũ trắng mơ tươi mềm (4 miếng), Dầu ăn chiên ngập (300 ml), Mắm tôm hoặc mắm tỏi ớt (1 chén), Kinh giới & Tía tô tươi (1 mớ nhỏ)', '[Bước 1: Thấm khô tuyệt đối bề mặt miếng đậu - ⏱️ 3 phút]
Cắt đậu hũ thành các khối vuông 3 x 3cm vừa ăn. Dùng khăn giấy chuyên dụng dặm thật khô ráo toàn bộ các mặt miếng đậu (lau khô nước là bí quyết giúp chiên không bắn dầu và lớp vỏ đậu nhanh phồng giòn rụm).

[Bước 2: Canh nhiệt dầu nóng già chuẩn xác - ⏱️ 2 phút]
Đổ dầu ngập 1/2 miếng đậu vào chảo sâu lòng, đun nóng già ở lửa vừa (thử đầu đũa gỗ thấy sủi bọt khí tăm tắp mạnh mẽ là dầu đạt nhiệt độ lý tưởng khoảng 170°C).

[Bước 3: Chiên phồng vàng giòn rụm các mặt - ⏱️ 6 phút]
Nhẹ nhàng thả từng miếng đậu vào chảo, để khoảng cách không cho các miếng đậu dính vào nhau. Chiên lửa vừa trong 3 phút cho mặt dưới phồng xốp se vàng cứng thì lật mặt chiên tiếp các cạnh còn lại cho miếng đậu vàng ruộm giòn tan.

[Bước 4: Thấm dầu & Thưởng thức nóng giòn - ⏱️ 2 phút]
Vớt đậu ra đĩa có lót giấy thấm dầu. Dọn ăn ngay khi còn bốc khói nóng giòn cùng rau kinh giới, tía tô và chén mắm tôm vắt chanh ớt đánh sủi bọt trắng xóa.

💡 Mẹo đầu bếp: Bắt buộc phải lau thật khô nước trên miếng đậu trước khi thả vào chảo dầu nóng già; đậu sẽ phồng xốp giòn rụm bên ngoài mà bên trong vẫn mềm béo ngậy.', '1786036689705.webp', 'Món mặn', 'Từng miếng đậu hũ trắng ngần được chiên phồng vàng ruộm giòn tan lớp vỏ ngoài, bên trong béo mềm mướt như kem chấm mắm tôm sủi bọt hoặc mắm tỏi ớt.', 'Dễ', '3 người', 5, 10, '[{"ten":"Đậu hũ trắng mơ tươi mềm","so_luong":4,"don_vi":"miếng","ghi_chu":"cắt khối vuông 3 x 3cm"},{"ten":"Dầu ăn chiên ngập","so_luong":300,"don_vi":"ml","ghi_chu":"giúp đậu phồng giòn đều 4 mặt"},{"ten":"Mắm tôm hoặc mắm tỏi ớt","so_luong":1,"don_vi":"chén","ghi_chu":"đánh sủi bọt chanh đường"},{"ten":"Kinh giới & Tía tô tươi","so_luong":1,"don_vi":"mớ nhỏ","ghi_chu":"rau thơm ăn kèm chuẩn vị"}]', '[{"buoc":1,"tieu_de":"Thấm khô tuyệt đối bề mặt miếng đậu","thoi_gian":"3 phút","noi_dung":"Cắt đậu hũ thành các khối vuông 3 x 3cm vừa ăn. Dùng khăn giấy chuyên dụng dặm thật khô ráo toàn bộ các mặt miếng đậu (lau khô nước là bí quyết giúp chiên không bắn dầu và lớp vỏ đậu nhanh phồng giòn rụm)."},{"buoc":2,"tieu_de":"Canh nhiệt dầu nóng già chuẩn xác","thoi_gian":"2 phút","noi_dung":"Đổ dầu ngập 1/2 miếng đậu vào chảo sâu lòng, đun nóng già ở lửa vừa (thử đầu đũa gỗ thấy sủi bọt khí tăm tắp mạnh mẽ là dầu đạt nhiệt độ lý tưởng khoảng 170°C)."},{"buoc":3,"tieu_de":"Chiên phồng vàng giòn rụm các mặt","thoi_gian":"6 phút","noi_dung":"Nhẹ nhàng thả từng miếng đậu vào chảo, để khoảng cách không cho các miếng đậu dính vào nhau. Chiên lửa vừa trong 3 phút cho mặt dưới phồng xốp se vàng cứng thì lật mặt chiên tiếp các cạnh còn lại cho miếng đậu vàng ruộm giòn tan."},{"buoc":4,"tieu_de":"Thấm dầu & Thưởng thức nóng giòn","thoi_gian":"2 phút","noi_dung":"Vớt đậu ra đĩa có lót giấy thấm dầu. Dọn ăn ngay khi còn bốc khói nóng giòn cùng rau kinh giới, tía tô và chén mắm tôm vắt chanh ớt đánh sủi bọt trắng xóa."}]', 'Bắt buộc phải lau thật khô nước trên miếng đậu trước khi thả vào chảo dầu nóng già; đậu sẽ phồng xốp giòn rụm bên ngoài mà bên trong vẫn mềm béo ngậy.', '{"calo":280,"protein":"22g","chat_beo":"20g","carb":"4g"}', '["Giòn rụm bên ngoài","Mềm béo bên trong","Dân dã","Ăn kèm bún đậu mắm tôm"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (45, 'Trứng chiên hành lá', 'Trứng gà tươi (3 quả), Hành hoa (hành lá) tươi (3 nhánh), Nước mắm truyền thống (1 muỗng canh), Tiêu xay & Nước lọc (1 thìa cà phê), Dầu ăn (1.5 muỗng canh)', '[Bước 1: Đánh bông trứng cùng hành hoa - ⏱️ 2 phút]
Đập 3 quả trứng vào tô, thêm 1 muỗng nước mắm ngon, 1/2 thìa tiêu, 1 thìa cà phê nước lọc và toàn bộ hành hoa thái nhỏ. Dùng đũa đánh đều tay liên tục trong 1 phút cho trứng sủi bọt mịn li ti.

[Bước 2: Làm nóng chảo dầu - ⏱️ 1 phút]
Đặt chảo chống dính lên bếp với 1.5 muỗng dầu ăn đun nóng già ở lửa vừa, láng dầu đều khắp mặt chảo.

[Bước 3: Đổ trứng & Rán vàng se mặt - ⏱️ 2 phút]
Rót hỗn hợp trứng vào giữa chảo, nghiêng chảo cho trứng dàn mỏng đều. Hạ lửa nhỏ vừa rán trong 2 phút cho mặt đáy se vàng óng ả.

[Bước 4: Cuộn tròn hoặc lật mặt hoàn thiện - ⏱️ 1 phút]
Khéo léo dùng xẻng lật mặt trứng hoặc cuộn tròn trứng lại trên chảo, đun thêm 30 giây cho chín đều rồi trút ra đĩa cắt khúc thưởng thức cùng cơm nóng.

💡 Mẹo đầu bếp: Cho 1 thìa cà phê nước lọc và đánh thật kỹ cho trứng sủi bọt trước khi rán, trứng chiên sẽ xốp mềm bông xốp và dày dặn hơn rất nhiều.', '1786036674608.webp', 'Món mặn', 'Trứng chiên vàng xốp bông thơm lừng hương hành hoa thái nhỏ quyện cùng nước mắm nhĩ, món ăn tuổi thơ siêu tốc chưa đầy 5 phút là có ngay trên bàn ăn.', 'Dễ', '2 - 3 người', 3, 5, '[{"ten":"Trứng gà tươi","so_luong":3,"don_vi":"quả","ghi_chu":"chọn trứng gà ta thơm bùi"},{"ten":"Hành hoa (hành lá) tươi","so_luong":3,"don_vi":"nhánh","ghi_chu":"rửa sạch thái nhỏ nhuyễn"},{"ten":"Nước mắm truyền thống","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"tạo mùi thơm nồng nàn"},{"ten":"Tiêu xay & Nước lọc","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"giúp trứng bông xốp"},{"ten":"Dầu ăn","so_luong":1.5,"don_vi":"muỗng canh","ghi_chu":"tráng chảo nóng"}]', '[{"buoc":1,"tieu_de":"Đánh bông trứng cùng hành hoa","thoi_gian":"2 phút","noi_dung":"Đập 3 quả trứng vào tô, thêm 1 muỗng nước mắm ngon, 1/2 thìa tiêu, 1 thìa cà phê nước lọc và toàn bộ hành hoa thái nhỏ. Dùng đũa đánh đều tay liên tục trong 1 phút cho trứng sủi bọt mịn li ti."},{"buoc":2,"tieu_de":"Làm nóng chảo dầu","thoi_gian":"1 phút","noi_dung":"Đặt chảo chống dính lên bếp với 1.5 muỗng dầu ăn đun nóng già ở lửa vừa, láng dầu đều khắp mặt chảo."},{"buoc":3,"tieu_de":"Đổ trứng & Rán vàng se mặt","thoi_gian":"2 phút","noi_dung":"Rót hỗn hợp trứng vào giữa chảo, nghiêng chảo cho trứng dàn mỏng đều. Hạ lửa nhỏ vừa rán trong 2 phút cho mặt đáy se vàng óng ả."},{"buoc":4,"tieu_de":"Cuộn tròn hoặc lật mặt hoàn thiện","thoi_gian":"1 phút","noi_dung":"Khéo léo dùng xẻng lật mặt trứng hoặc cuộn tròn trứng lại trên chảo, đun thêm 30 giây cho chín đều rồi trút ra đĩa cắt khúc thưởng thức cùng cơm nóng."}]', 'Cho 1 thìa cà phê nước lọc và đánh thật kỹ cho trứng sủi bọt trước khi rán, trứng chiên sẽ xốp mềm bông xốp và dày dặn hơn rất nhiều.', '{"calo":220,"protein":"15g","chat_beo":"17g","carb":"2g"}', '["Nhanh nhất trần đời","Dễ làm","Bữa sáng tiện lợi","Trẻ nhỏ mê tít"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (46, 'Trứng ốp la', 'Trứng gà tươi mới (2 quả), Dầu ăn hoặc bơ lạt (1 muỗng canh), Muối tiêu hoặc nước tương (1 chút)', '[Bước 1: Làm nóng chảo & Canh nhiệt viền giòn - ⏱️ 1 phút]
Đặt chảo chống dính lên bếp bật lửa vừa với 1 muỗng canh dầu ăn (hoặc bơ lạt). Đun nóng già đến khi dầu lăn tăn sủi bọt nhẹ.

[Bước 2: Kỹ thuật đập trứng giữ nguyên lòng đỏ - ⏱️ 30 giây]
Hạ lửa xuống mức nhỏ vừa, đập nhẹ nhàng từng quả trứng gà sát mặt chảo để lòng đỏ nằm nguyên vẹn tròn trịa ở chính giữa lòng trắng, không bị vỡ màng.

[Bước 3: Kỹ thuật hấp hơi chín lòng đào hoàn hảo - ⏱️ 1.5 phút]
Rán trong 1 phút cho viền lòng trắng xém vàng giòn rụm. Nhỏ 1 thìa cà phê nước lọc vào mép chảo rồi đậy vung lại ngay trong 30 giây (hơi nước bốc lên sẽ làm chín se lớp màng trên của lòng trắng trong khi lòng đỏ bên trong vẫn dẻo quánh sóng sánh).

[Bước 4: Trình bày & Rắc tiêu - ⏱️ 30 giây]
Dùng xẻng dẹt nhẹ nhàng múc trứng ra đĩa, rắc chút muối tiêu sọ và vài giọt nước tương lên bề mặt, thưởng thức ngay khi còn nóng giòn cùng bánh mì.

💡 Mẹo đầu bếp: Bí quyết lòng đào chín dẻo không sống tanh: Nhỏ 1 thìa nước lọc vào mép chảo và đậy vung 30 giây cuối; hơi nước sẽ nấu chín màng lòng trắng trên cùng mà viền đáy vẫn giòn rụm.', '1786036610673.webp', 'Món mặn', 'Trứng ốp la viền giòn rụm màu vàng nâu thơm phức, lòng trắng chín đông mềm mọng, lòng đào vàng óng dẻo béo ngậy tan chảy chấm bánh mì hay xì dầu cực phẩm.', 'Dễ', '1 - 2 người', 2, 3, '[{"ten":"Trứng gà tươi mới","so_luong":2,"don_vi":"quả","ghi_chu":"trứng mới lòng đỏ căng tròn không vỡ"},{"ten":"Dầu ăn hoặc bơ lạt","so_luong":1,"don_vi":"muỗng canh","ghi_chu":"tạo mùi thơm ngậy"},{"ten":"Muối tiêu hoặc nước tương","so_luong":1,"don_vi":"chút","ghi_chu":"rắc lên bề mặt"}]', '[{"buoc":1,"tieu_de":"Làm nóng chảo & Canh nhiệt viền giòn","thoi_gian":"1 phút","noi_dung":"Đặt chảo chống dính lên bếp bật lửa vừa với 1 muỗng canh dầu ăn (hoặc bơ lạt). Đun nóng già đến khi dầu lăn tăn sủi bọt nhẹ."},{"buoc":2,"tieu_de":"Kỹ thuật đập trứng giữ nguyên lòng đỏ","thoi_gian":"30 giây","noi_dung":"Hạ lửa xuống mức nhỏ vừa, đập nhẹ nhàng từng quả trứng gà sát mặt chảo để lòng đỏ nằm nguyên vẹn tròn trịa ở chính giữa lòng trắng, không bị vỡ màng."},{"buoc":3,"tieu_de":"Kỹ thuật hấp hơi chín lòng đào hoàn hảo","thoi_gian":"1.5 phút","noi_dung":"Rán trong 1 phút cho viền lòng trắng xém vàng giòn rụm. Nhỏ 1 thìa cà phê nước lọc vào mép chảo rồi đậy vung lại ngay trong 30 giây (hơi nước bốc lên sẽ làm chín se lớp màng trên của lòng trắng trong khi lòng đỏ bên trong vẫn dẻo quánh sóng sánh)."},{"buoc":4,"tieu_de":"Trình bày & Rắc tiêu","thoi_gian":"30 giây","noi_dung":"Dùng xẻng dẹt nhẹ nhàng múc trứng ra đĩa, rắc chút muối tiêu sọ và vài giọt nước tương lên bề mặt, thưởng thức ngay khi còn nóng giòn cùng bánh mì."}]', 'Bí quyết lòng đào chín dẻo không sống tanh: Nhỏ 1 thìa nước lọc vào mép chảo và đậy vung 30 giây cuối; hơi nước sẽ nấu chín màng lòng trắng trên cùng mà viền đáy vẫn giòn rụm.', '{"calo":190,"protein":"13g","chat_beo":"15g","carb":"1g"}', '["Bữa sáng nhanh","Lòng đào béo ngậy","Giàu đạm","Ăn kèm bánh mì"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (47, 'Dưa giá đỗ muối chua', 'Giá đỗ sạch mập mạp (300 g), Bông hẹ tươi (100 g), Cà rốt tươi (0.5 củ), Giấm gạo & Đường cát (2 muỗng canh mỗi loại), Muối hạt tinh khiết (1 thìa canh)', '[Bước 1: Sơ chế & Làm ráo kiệt nguyên liệu - ⏱️ 8 phút]
Giá đỗ ngâm nước muối loãng 5 phút, rửa sạch vớt ra để thật ráo nước. Hẹ cắt khúc dài bằng cọng giá (khoảng 4cm). Cà rốt gọt vỏ bào sợi mỏng, ớt sừng thái sợi dài.

[Bước 2: Nấu nước ngâm giấm đường & Để nguội hoàn toàn - ⏱️ 5 phút]
Đun sôi 500ml nước với 2 muỗng đường, 2 muỗng giấm gạo và 1 thìa canh muối hạt, khuấy tan đều rồi tắt bếp. Để nước ngâm nguội hoàn toàn về nhiệt độ phòng (nếu đổ nước còn ấm vào giá sẽ bị chín nhũn ủng).

[Bước 3: Trộn đều & Xếp vào hũ - ⏱️ 2 phút]
Trộn đều giá đỗ, hẹ và cà rốt bào sợi trong âu sạch, xếp nhẹ nhàng vào hũ thủy tinh hoặc âu sứ.

[Bước 4: Ngâm chua lên men thần tốc - ⏱️ 4 tiếng]
Rót nước ngâm đã nguội hẳn ngập mặt giá đỗ. Dùng nan tre hoặc đĩa nhỏ gài nén nhẹ. Để ở nhiệt độ phòng sau 4 - 6 tiếng là dưa giá đã lên men chua dịu, giòn sần sật ăn được ngay.

💡 Mẹo đầu bếp: Bắt buộc nước ngâm giấm đường phải để thật nguội hẳn mới đổ vào giá đỗ; nếu đổ khi nước còn ấm giá đỗ sẽ bị chín nhũn ủng và thâm xỉn.', '1786036596750.webp', 'Rau', 'Dưa giá đỗ muối chua ngọt giòn sần sật điểm sắc xanh của hẹ và sắc cam của cà rốt, món ăn kèm thanh mát giải ngấy hoàn hảo cho thịt kho tàu hay nem rán.', 'Dễ', '4 người', 15, 0, '[{"ten":"Giá đỗ sạch mập mạp","so_luong":300,"don_vi":"g","ghi_chu":"rửa sạch ngắt bớt chân rễ dài"},{"ten":"Bông hẹ tươi","so_luong":100,"don_vi":"g","ghi_chu":"rửa sạch cắt khúc 4cm"},{"ten":"Cà rốt tươi","so_luong":0.5,"don_vi":"củ","ghi_chu":"bào sợi mỏng dài 4cm"},{"ten":"Giấm gạo & Đường cát","so_luong":2,"don_vi":"muỗng canh mỗi loại","ghi_chu":"pha nước muối chua ngọt"},{"ten":"Muối hạt tinh khiết","so_luong":1,"don_vi":"thìa canh","ghi_chu":"lên men chuẩn vị"}]', '[{"buoc":1,"tieu_de":"Sơ chế & Làm ráo kiệt nguyên liệu","thoi_gian":"8 phút","noi_dung":"Giá đỗ ngâm nước muối loãng 5 phút, rửa sạch vớt ra để thật ráo nước. Hẹ cắt khúc dài bằng cọng giá (khoảng 4cm). Cà rốt gọt vỏ bào sợi mỏng, ớt sừng thái sợi dài."},{"buoc":2,"tieu_de":"Nấu nước ngâm giấm đường & Để nguội hoàn toàn","thoi_gian":"5 phút","noi_dung":"Đun sôi 500ml nước với 2 muỗng đường, 2 muỗng giấm gạo và 1 thìa canh muối hạt, khuấy tan đều rồi tắt bếp. Để nước ngâm nguội hoàn toàn về nhiệt độ phòng (nếu đổ nước còn ấm vào giá sẽ bị chín nhũn ủng)."},{"buoc":3,"tieu_de":"Trộn đều & Xếp vào hũ","thoi_gian":"2 phút","noi_dung":"Trộn đều giá đỗ, hẹ và cà rốt bào sợi trong âu sạch, xếp nhẹ nhàng vào hũ thủy tinh hoặc âu sứ."},{"buoc":4,"tieu_de":"Ngâm chua lên men thần tốc","thoi_gian":"4 tiếng","noi_dung":"Rót nước ngâm đã nguội hẳn ngập mặt giá đỗ. Dùng nan tre hoặc đĩa nhỏ gài nén nhẹ. Để ở nhiệt độ phòng sau 4 - 6 tiếng là dưa giá đã lên men chua dịu, giòn sần sật ăn được ngay."}]', 'Bắt buộc nước ngâm giấm đường phải để thật nguội hẳn mới đổ vào giá đỗ; nếu đổ khi nước còn ấm giá đỗ sẽ bị chín nhũn ủng và thâm xỉn.', '{"calo":65,"protein":"3g","chat_beo":"0.2g","carb":"13g"}', '["Giải ngấy thịt kho","Giòn sần sật","Chua ngọt thanh mát","Món kèm kinh điển"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (48, 'Cà muối xổi', 'Cà pháo tươi bánh tẻ (400 g), Củ riềng tươi (30 g), Tỏi khô & Ớt chỉ thiên (1.5 củ / 3 trái), Nước cốt chanh tươi (2 muỗng canh), Nước mắm ngon & Đường (2 muỗng canh mỗi loại)', '[Bước 1: Khử nhựa thâm & Cắt cà ngâm nước muối chanh - ⏱️ 15 phút]
Chuẩn bị thau nước đun sôi để nguội pha 1 thìa muối hạt và 1 quả chanh vắt nước. Cà pháo dùng dao sắc gọt bỏ cuống (không gọt sâu vào thịt cà), bổ đôi hoặc khía chữ thập rồi thả ngay vào thau nước muối chanh ngâm trong 20 phút để ra sạch nhựa đắng chát và giữ miếng cà trắng tinh không bị thâm đen.

[Bước 2: Rửa sạch & Vắt ráo kiệt nước - ⏱️ 5 phút]
Vớt cà pháo ra rửa xả lại 2 lần bằng nước đun sôi để nguội, dùng tay bóp nhẹ cho ráo kiệt nước rồi để lên rây.

[Bước 3: Pha sốt mắm riềng tỏi ớt đậm đà - ⏱️ 3 phút]
Khuấy tan hoàn toàn hỗn hợp gồm: 2 muỗng nước mắm nhĩ, 2 muỗng đường, 2 muỗng nước cốt chanh tươi cùng tỏi băm, ớt băm và củ riềng thái chỉ mỏng thơm nồng.

[Bước 4: Trộn xổi & Thấm vị giòn tan - ⏱️ 1 tiếng]
Trút toàn bộ cà pháo vào âu sốt mắm riềng, dùng thìa trộn đều tay cho nước sốt bao bọc đều khắp từng miếng cà. Để nghỉ ở nhiệt độ phòng trong 1 - 2 tiếng cho cà ngấm đượm vị giòn tan chua cay mặn ngọt là dùng được ngay.

💡 Mẹo đầu bếp: Thả ngay miếng cà vào thau nước muối chanh loãng ngay sau khi cắt cuống; cà sẽ giữ được màu trắng phao tinh tươm và khử sạch hoàn toàn nhựa đắng chát.', '1786036578552.webp', 'Rau', 'Từng quả cà pháo trắng muốt giòn tan rôm rốp quyện cùng vị cay nồng của riềng tỏi ớt băm và vị chua ngọt mặn mà, linh hồn ăn kèm canh cua mồng tơi ngày hè.', 'Dễ', '4 người', 20, 0, '[{"ten":"Cà pháo tươi bánh tẻ","so_luong":400,"don_vi":"g","ghi_chu":"chọn quả vừa phải, không quá non hay già"},{"ten":"Củ riềng tươi","so_luong":30,"don_vi":"g","ghi_chu":"thái chỉ mỏng hoặc giã dập"},{"ten":"Tỏi khô & Ớt chỉ thiên","so_luong":1.5,"don_vi":"củ / 3 trái","ghi_chu":"băm nhỏ"},{"ten":"Nước cốt chanh tươi","so_luong":2,"don_vi":"muỗng canh","ghi_chu":"tạo vị chua thanh xổi nhanh"},{"ten":"Nước mắm ngon & Đường","so_luong":2,"don_vi":"muỗng canh mỗi loại","ghi_chu":"hòa quyện vị đậm đà"}]', '[{"buoc":1,"tieu_de":"Khử nhựa thâm & Cắt cà ngâm nước muối chanh","thoi_gian":"15 phút","noi_dung":"Chuẩn bị thau nước đun sôi để nguội pha 1 thìa muối hạt và 1 quả chanh vắt nước. Cà pháo dùng dao sắc gọt bỏ cuống (không gọt sâu vào thịt cà), bổ đôi hoặc khía chữ thập rồi thả ngay vào thau nước muối chanh ngâm trong 20 phút để ra sạch nhựa đắng chát và giữ miếng cà trắng tinh không bị thâm đen."},{"buoc":2,"tieu_de":"Rửa sạch & Vắt ráo kiệt nước","thoi_gian":"5 phút","noi_dung":"Vớt cà pháo ra rửa xả lại 2 lần bằng nước đun sôi để nguội, dùng tay bóp nhẹ cho ráo kiệt nước rồi để lên rây."},{"buoc":3,"tieu_de":"Pha sốt mắm riềng tỏi ớt đậm đà","thoi_gian":"3 phút","noi_dung":"Khuấy tan hoàn toàn hỗn hợp gồm: 2 muỗng nước mắm nhĩ, 2 muỗng đường, 2 muỗng nước cốt chanh tươi cùng tỏi băm, ớt băm và củ riềng thái chỉ mỏng thơm nồng."},{"buoc":4,"tieu_de":"Trộn xổi & Thấm vị giòn tan","thoi_gian":"1 tiếng","noi_dung":"Trút toàn bộ cà pháo vào âu sốt mắm riềng, dùng thìa trộn đều tay cho nước sốt bao bọc đều khắp từng miếng cà. Để nghỉ ở nhiệt độ phòng trong 1 - 2 tiếng cho cà ngấm đượm vị giòn tan chua cay mặn ngọt là dùng được ngay."}]', 'Thả ngay miếng cà vào thau nước muối chanh loãng ngay sau khi cắt cuống; cà sẽ giữ được màu trắng phao tinh tươm và khử sạch hoàn toàn nhựa đắng chát.', '{"calo":70,"protein":"2g","chat_beo":"0.3g","carb":"15g"}', '["Cà giòn rôm rốp","Cặp đôi canh cua","Dân dã Bắc Bộ","Chua cay mặn ngọt"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (49, 'Chả lụa thái lát', 'Chả lụa (giò lụa) tươi ngon (300 g), Muối tiêu chanh hoặc tương ớt (1 chén nhỏ), Dưa leo & Rau thơm ngò rí (1 set)', '[Bước 1: Bóc vỏ chuối giữ nguyên hương thơm - ⏱️ 2 phút]
Dùng dao rạch nhẹ lớp lá chuối bao quanh khoanh giò lụa, bóc sạch lá và gạt bỏ lớp mỡ mỏng dính quanh viền, đặt khoanh giò lên mặt thớt sạch khô ráo.

[Bước 2: Kỹ thuật cắt lát tam giác cánh hoa đều tăm tắp - ⏱️ 3 phút]
Cắt khoanh giò làm đôi theo đường kính. Sau đó dùng dao sắc cắt mỗi nửa khoanh thành 3 hoặc 4 miếng hình tam giác đều nhau có độ dày khoảng 1cm (dùng dao sắc một đường dứt khoát để mặt giò láng mịn không bị răng cưa).

[Bước 3: Xếp hình cánh hoa trang trọng - ⏱️ 2 phút]
Xếp các miếng giò xòe tròn đều như cánh hoa nở quanh đĩa tròn, các đỉnh tam giác hướng ra ngoài hoặc hướng vào tâm. Đặt nhánh ngò rí hoặc lát ớt sừng tỉa hoa ở chính giữa đĩa.

[Bước 4: Chuẩn bị nước chấm & Dùng kèm - ⏱️ 1 phút]
Pha chén muối tiêu chanh ớt hoặc chuẩn bị chén tương ớt cay nồng chấm kèm, thưởng thức trực tiếp cùng cơm nóng, xôi nếp hoặc bánh giầy.

💡 Mẹo đầu bếp: Giò lụa ngon chuẩn truyền thống khi cắt ra bề mặt sẽ có những lỗ lăn tăn bọt khí tự nhiên, màu hơi ửng hồng phớt và tỏa mùi thơm dịu nhẹ của nước mắm cốt nhĩ.', '1786036544401.webp', 'Món mặn', 'Khoanh chả lụa (giò lụa) truyền thống màu trắng hồng mịn màng điểm vân bọt khí tự nhiên, thái lát tam giác giòn dai thơm ngát mùi lá chuối và nước mắm nhĩ.', 'Dễ', '3 - 4 người', 5, 0, '[{"ten":"Chả lụa (giò lụa) tươi ngon","so_luong":300,"don_vi":"g","ghi_chu":"gói lá chuối thơm nức mùi thịt tươi"},{"ten":"Muối tiêu chanh hoặc tương ớt","so_luong":1,"don_vi":"chén nhỏ","ghi_chu":"chấm kèm"},{"ten":"Dưa leo & Rau thơm ngò rí","so_luong":1,"don_vi":"set","ghi_chu":"bày đĩa trang trí"}]', '[{"buoc":1,"tieu_de":"Bóc vỏ chuối giữ nguyên hương thơm","thoi_gian":"2 phút","noi_dung":"Dùng dao rạch nhẹ lớp lá chuối bao quanh khoanh giò lụa, bóc sạch lá và gạt bỏ lớp mỡ mỏng dính quanh viền, đặt khoanh giò lên mặt thớt sạch khô ráo."},{"buoc":2,"tieu_de":"Kỹ thuật cắt lát tam giác cánh hoa đều tăm tắp","thoi_gian":"3 phút","noi_dung":"Cắt khoanh giò làm đôi theo đường kính. Sau đó dùng dao sắc cắt mỗi nửa khoanh thành 3 hoặc 4 miếng hình tam giác đều nhau có độ dày khoảng 1cm (dùng dao sắc một đường dứt khoát để mặt giò láng mịn không bị răng cưa)."},{"buoc":3,"tieu_de":"Xếp hình cánh hoa trang trọng","thoi_gian":"2 phút","noi_dung":"Xếp các miếng giò xòe tròn đều như cánh hoa nở quanh đĩa tròn, các đỉnh tam giác hướng ra ngoài hoặc hướng vào tâm. Đặt nhánh ngò rí hoặc lát ớt sừng tỉa hoa ở chính giữa đĩa."},{"buoc":4,"tieu_de":"Chuẩn bị nước chấm & Dùng kèm","thoi_gian":"1 phút","noi_dung":"Pha chén muối tiêu chanh ớt hoặc chuẩn bị chén tương ớt cay nồng chấm kèm, thưởng thức trực tiếp cùng cơm nóng, xôi nếp hoặc bánh giầy."}]', 'Giò lụa ngon chuẩn truyền thống khi cắt ra bề mặt sẽ có những lỗ lăn tăn bọt khí tự nhiên, màu hơi ửng hồng phớt và tỏa mùi thơm dịu nhẹ của nước mắm cốt nhĩ.', '{"calo":270,"protein":"21g","chat_beo":"19g","carb":"2g"}', '["Món nguội tiện lợi","Mâm cỗ ngày Tết","Giòn dai thơm ngọt","Ăn kèm bánh giầy/xôi"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (50, 'Lạc rang muối', 'Lạc nhân (đậu phộng) đỏ (300 g), Muối tinh hoặc bột canh (1.5 thìa cà phê), Dầu ăn thực vật (1 thìa cà phê)', '[Bước 1: Sàng sẩy & Nhặt bỏ hạt lép - ⏱️ 3 phút]
Đổ lạc ra rổ nhặt bỏ các hạt lép, mốc sâu hỏng để mẻ lạc rang đạt độ thơm bùi đồng đều không bị đắng hôi.

[Bước 2: Rang nhỏ lửa đều tay liên tục - ⏱️ 12 phút]
Cho lạc vào chảo gang khô trên lửa nhỏ nhất. Dùng đũa đảo đều tay liên tục không ngừng nghỉ trong 12 - 14 phút. Khi nghe tiếng nổ lách tách rộn ràng, vỏ lụa nứt nhẹ và mùi thơm bùi nồng nàn bốc lên thì thử cắn nhẹ hạt lạc thấy giòn tan là lạc đã chín thấu bên trong.

[Bước 3: Kỹ thuật ủ giấy báo & Áo dầu bóng - ⏱️ 5 phút]
Trút lạc ra ủ trong tờ giấy báo hoặc khăn vải sạch trong 5 phút để hơi nóng làm lạc giòn rụm lâu dài. Sau đó đổ lại vào chảo khi còn hơi ấm, nhỏ 1 thìa cà phê dầu ăn đảo nhanh 20 giây cho từng hạt lạc bóng bẩy.

[Bước 4: Xóc muối khi còn hơi ấm & Bảo quản - ⏱️ 2 phút]
Rắc muối tinh vào chảo lạc còn hơi ấm, xóc đều tay để muối bám dính một lớp trắng mịn quanh vỏ lạc. Để nguội hoàn toàn rồi trút vào hũ thủy tinh đậy kín nắp bảo quản giòn tan cả tháng.

💡 Mẹo đầu bếp: Chờ lạc nguội bớt còn hơi ấm rồi mới rắc muối; nếu rắc muối lúc lạc vừa bắc khỏi bếp còn quá nóng, muối sẽ bị chảy nước tan ra làm ỉu lạc ngay lập tức.', '1786036533983.webp', 'Món mặn', 'Hạt lạc (đậu phộng) rang chín vàng ruộm thơm bùi béo ngậy áo đều lớp muối mịn màng mằn mặn, món nhắm nhâm nhi và đưa cơm siêu bền bỉ.', 'Dễ', '4 người', 5, 15, '[{"ten":"Lạc nhân (đậu phộng) đỏ","so_luong":300,"don_vi":"g","ghi_chu":"hạt mẩy tròn đều, không lép mốc"},{"ten":"Muối tinh hoặc bột canh","so_luong":1.5,"don_vi":"thìa cà phê","ghi_chu":"rang khô rắc đều khi ấm"},{"ten":"Dầu ăn thực vật","so_luong":1,"don_vi":"thìa cà phê","ghi_chu":"tạo độ bóng và dính muối"}]', '[{"buoc":1,"tieu_de":"Sàng sẩy & Nhặt bỏ hạt lép","thoi_gian":"3 phút","noi_dung":"Đổ lạc ra rổ nhặt bỏ các hạt lép, mốc sâu hỏng để mẻ lạc rang đạt độ thơm bùi đồng đều không bị đắng hôi."},{"buoc":2,"tieu_de":"Rang nhỏ lửa đều tay liên tục","thoi_gian":"12 phút","noi_dung":"Cho lạc vào chảo gang khô trên lửa nhỏ nhất. Dùng đũa đảo đều tay liên tục không ngừng nghỉ trong 12 - 14 phút. Khi nghe tiếng nổ lách tách rộn ràng, vỏ lụa nứt nhẹ và mùi thơm bùi nồng nàn bốc lên thì thử cắn nhẹ hạt lạc thấy giòn tan là lạc đã chín thấu bên trong."},{"buoc":3,"tieu_de":"Kỹ thuật ủ giấy báo & Áo dầu bóng","thoi_gian":"5 phút","noi_dung":"Trút lạc ra ủ trong tờ giấy báo hoặc khăn vải sạch trong 5 phút để hơi nóng làm lạc giòn rụm lâu dài. Sau đó đổ lại vào chảo khi còn hơi ấm, nhỏ 1 thìa cà phê dầu ăn đảo nhanh 20 giây cho từng hạt lạc bóng bẩy."},{"buoc":4,"tieu_de":"Xóc muối khi còn hơi ấm & Bảo quản","thoi_gian":"2 phút","noi_dung":"Rắc muối tinh vào chảo lạc còn hơi ấm, xóc đều tay để muối bám dính một lớp trắng mịn quanh vỏ lạc. Để nguội hoàn toàn rồi trút vào hũ thủy tinh đậy kín nắp bảo quản giòn tan cả tháng."}]', 'Chờ lạc nguội bớt còn hơi ấm rồi mới rắc muối; nếu rắc muối lúc lạc vừa bắc khỏi bếp còn quá nóng, muối sẽ bị chảy nước tan ra làm ỉu lạc ngay lập tức.', '{"calo":560,"protein":"25g","chat_beo":"49g","carb":"16g"}', '["Món ăn dân dã","Bùi béo giòn rụm","Để dành ăn lâu","Món nhắm bia"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (51, 'Dưa hấu tráng miệng', 'Dưa hấu tươi già ngọt (1 kg)', '[Bước 1: Rửa sạch vỏ ngoài & Ướp lạnh - ⏱️ 5 phút]
Rửa sạch vỏ ngoài quả dưa hấu dưới vòi nước lạnh, lau khô. Để vào ngăn mát tủ lạnh trước 1 - 2 tiếng trước khi bổ để miếng dưa mát lạnh sảng khoái.

[Bước 2: Bổ dưa làm tư theo chiều dọc - ⏱️ 2 phút]
Dùng dao lớn sắc bổ quả dưa làm tư theo chiều dọc từ cuống xuống đáy thành các thanh dưa dài đều nhau.

[Bước 3: Gọt vỏ & Cắt miếng tam giác - ⏱️ 2 phút]
Dùng dao lướt nhẹ gọt bỏ lớp vỏ xanh và phần cùi trắng sát đáy vỏ. Cắt thịt dưa thành các lát tam giác dày khoảng 1.5cm vừa miệng.

[Bước 4: Bày đĩa hình cánh quạt & Thưởng thức - ⏱️ 1 phút]
Xếp so le các miếng dưa hình cánh quạt trên đĩa tròn lớn, cắm tăm tre dọn tráng miệng mát lành sau bữa cơm.

💡 Mẹo đầu bếp: Chọn quả dưa hấu có vết rám màu vàng kem ở đáy và cuống teo nhỏ khô cong là quả dưa già chín ngọt lịm mọng nước nhiều đường.', '1786036522570.webp', 'Tráng miệng', 'Từng miếng dưa hấu đỏ tươi mọng nước mát lạnh ngọt lịm tan chảy xua tan cảm giác ngấy và đem lại sự sảng khoái tức thì sau bữa ăn.', 'Dễ', '4 người', 5, 0, '[{"ten":"Dưa hấu tươi già ngọt","so_luong":1,"don_vi":"kg","ghi_chu":"cuống héo, đáy vàng sẫm, vỗ kêu đanh"}]', '[{"buoc":1,"tieu_de":"Rửa sạch vỏ ngoài & Ướp lạnh","thoi_gian":"5 phút","noi_dung":"Rửa sạch vỏ ngoài quả dưa hấu dưới vòi nước lạnh, lau khô. Để vào ngăn mát tủ lạnh trước 1 - 2 tiếng trước khi bổ để miếng dưa mát lạnh sảng khoái."},{"buoc":2,"tieu_de":"Bổ dưa làm tư theo chiều dọc","thoi_gian":"2 phút","noi_dung":"Dùng dao lớn sắc bổ quả dưa làm tư theo chiều dọc từ cuống xuống đáy thành các thanh dưa dài đều nhau."},{"buoc":3,"tieu_de":"Gọt vỏ & Cắt miếng tam giác","thoi_gian":"2 phút","noi_dung":"Dùng dao lướt nhẹ gọt bỏ lớp vỏ xanh và phần cùi trắng sát đáy vỏ. Cắt thịt dưa thành các lát tam giác dày khoảng 1.5cm vừa miệng."},{"buoc":4,"tieu_de":"Bày đĩa hình cánh quạt & Thưởng thức","thoi_gian":"1 phút","noi_dung":"Xếp so le các miếng dưa hình cánh quạt trên đĩa tròn lớn, cắm tăm tre dọn tráng miệng mát lành sau bữa cơm."}]', 'Chọn quả dưa hấu có vết rám màu vàng kem ở đáy và cuống teo nhỏ khô cong là quả dưa già chín ngọt lịm mọng nước nhiều đường.', '{"calo":60,"protein":"1g","chat_beo":"0.2g","carb":"15g"}', '["Tráng miệng mát lành","Nhiều vitamin A & C","Bổ sung nước","Giải nhiệt mùa hè"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (52, 'Xoài chín tráng miệng', 'Xoài cát Hòa Lộc chín vàng (2 quả (~700g))', '[Bước 1: Rửa sạch & Cắt sát hai bên má xoài - ⏱️ 2 phút]
Rửa sạch vỏ xoài, lau khô. Đặt đứng quả xoài, dùng dao sắc đưa lưỡi dao khía sát hai bên má hạt xoài để cắt rời 2 phần má thịt xoài lớn nhiều nạc.

[Bước 2: Khía vảy rồng ca-rô nghệ thuật - ⏱️ 2 phút]
Dùng đầu mũi dao sắc khía các đường ca-rô vuông trên má thịt xoài cách nhau 1.5cm nhưng khéo léo không làm rách lớp vỏ dưới.

[Bước 3: Ấn lộn ngược đáy tạo hình nhím đẹp mắt - ⏱️ 1 phút]
Dùng hai tay cầm hai đầu má xoài, dùng ngón tay ấn nhẹ từ dưới tâm đáy vỏ lên; các khối xoài vuông sẽ xòe bung ra như hình vảy nhím nở hoa tuyệt đẹp.

[Bước 4: Bày đĩa & Thưởng thức ngọt lịm - ⏱️ 1 phút]
Đặt các má xoài lên đĩa tráng miệng, phần thịt quanh hạt gọt sạch vỏ cắt khối xếp kèm xung quanh, ướp lạnh 10 phút trước khi dùng.

💡 Mẹo đầu bếp: Tỉa vảy rồng ca-rô rồi lộn ngược đáy vừa giúp món tráng miệng đẹp mắt sang trọng vừa giúp thưởng thức dễ dàng không lo dính nước ngọt ra tay.', '1786036513550.webp', 'Tráng miệng', 'Những miếng xoài cát chín vàng óng ả mềm thơm nức mũi, vị ngọt lịm đậm đà thanh tao đặc trưng của trái cây nhiệt đới Việt Nam.', 'Dễ', '3 - 4 người', 5, 0, '[{"ten":"Xoài cát Hòa Lộc chín vàng","so_luong":2,"don_vi":"quả (~700g)","ghi_chu":"vỏ vàng ươm căng mịn, thơm lừng"}]', '[{"buoc":1,"tieu_de":"Rửa sạch & Cắt sát hai bên má xoài","thoi_gian":"2 phút","noi_dung":"Rửa sạch vỏ xoài, lau khô. Đặt đứng quả xoài, dùng dao sắc đưa lưỡi dao khía sát hai bên má hạt xoài để cắt rời 2 phần má thịt xoài lớn nhiều nạc."},{"buoc":2,"tieu_de":"Khía vảy rồng ca-rô nghệ thuật","thoi_gian":"2 phút","noi_dung":"Dùng đầu mũi dao sắc khía các đường ca-rô vuông trên má thịt xoài cách nhau 1.5cm nhưng khéo léo không làm rách lớp vỏ dưới."},{"buoc":3,"tieu_de":"Ấn lộn ngược đáy tạo hình nhím đẹp mắt","thoi_gian":"1 phút","noi_dung":"Dùng hai tay cầm hai đầu má xoài, dùng ngón tay ấn nhẹ từ dưới tâm đáy vỏ lên; các khối xoài vuông sẽ xòe bung ra như hình vảy nhím nở hoa tuyệt đẹp."},{"buoc":4,"tieu_de":"Bày đĩa & Thưởng thức ngọt lịm","thoi_gian":"1 phút","noi_dung":"Đặt các má xoài lên đĩa tráng miệng, phần thịt quanh hạt gọt sạch vỏ cắt khối xếp kèm xung quanh, ướp lạnh 10 phút trước khi dùng."}]', 'Tỉa vảy rồng ca-rô rồi lộn ngược đáy vừa giúp món tráng miệng đẹp mắt sang trọng vừa giúp thưởng thức dễ dàng không lo dính nước ngọt ra tay.', '{"calo":90,"protein":"1.2g","chat_beo":"0.4g","carb":"23g"}', '["Trái cây nhiệt đới","Ngọt lịm thơm lừng","Tráng miệng hảo hạng","Giàu vitamin A"]');
INSERT INTO `mon_an` (`id`, `ten_mon`, `nguyen_lieu_chinh`, `cong_thuc`, `hinh_anh`, `loai_mon`, `mo_ta`, `do_kho`, `khau_phan`, `thoi_gian_chuan_bi`, `thoi_gian_nau`, `nguyen_lieu_chi_tiet`, `cac_buoc_thuc_hien`, `meo_nau_an`, `dinh_duong`, `tags`) VALUES (53, 'Thanh long tráng miệng', 'Thanh long ruột đỏ hoặc trắng (1 quả (~600g))', '[Bước 1: Cắt cuống & Bổ đôi - ⏱️ 1 phút]
Rửa sạch vỏ ngoài quả thanh long, dùng dao cắt bỏ phần cuống và chóp đuôi. Bổ đôi quả thanh long theo chiều dọc.

[Bước 2: Lột vỏ mượt mà - ⏱️ 1 phút]
Dùng tay cầm mép vỏ ở đầu nhọn nhẹ nhàng kéo lột ngược về sau; lớp vỏ đỏ sẽ tách rời hoàn toàn khỏi khối thịt quả một cách dễ dàng.

[Bước 3: Cắt khối vuông quân cờ đều tay - ⏱️ 2 phút]
Đặt nửa quả thanh long lên thớt, cắt thành các khối vuông quân cờ kích thước 2 x 2cm đều tăm tắp.

[Bước 4: Ướp lạnh & Bày đĩa - ⏱️ 1 phút]
Xếp các khối thanh long vào đĩa tráng miệng, để trong ngăn mát tủ lạnh 15 phút trước khi dùng để tăng vị thanh mát giòn ngọt sảng khoái.

💡 Mẹo đầu bếp: Thanh long ruột đỏ có vị ngọt đậm đà và chứa nhiều chất chống oxy hóa anthocyanin hơn ruột trắng; phối hợp cả hai loại trên đĩa tạo hiệu ứng màu sắc tương phản rực rỡ.', '1786036502298.webp', 'Tráng miệng', 'Từng khối thanh long thanh mát mềm ngọt với hàng ngàn hạt nhỏ li ti vui miệng, món tráng miệng giải nhiệt dịu dàng hỗ trợ tiêu hóa sau bữa cơm.', 'Dễ', '3 - 4 người', 5, 0, '[{"ten":"Thanh long ruột đỏ hoặc trắng","so_luong":1,"don_vi":"quả (~600g)","ghi_chu":"vỏ đỏ tươi, tai xanh bóng"}]', '[{"buoc":1,"tieu_de":"Cắt cuống & Bổ đôi","thoi_gian":"1 phút","noi_dung":"Rửa sạch vỏ ngoài quả thanh long, dùng dao cắt bỏ phần cuống và chóp đuôi. Bổ đôi quả thanh long theo chiều dọc."},{"buoc":2,"tieu_de":"Lột vỏ mượt mà","thoi_gian":"1 phút","noi_dung":"Dùng tay cầm mép vỏ ở đầu nhọn nhẹ nhàng kéo lột ngược về sau; lớp vỏ đỏ sẽ tách rời hoàn toàn khỏi khối thịt quả một cách dễ dàng."},{"buoc":3,"tieu_de":"Cắt khối vuông quân cờ đều tay","thoi_gian":"2 phút","noi_dung":"Đặt nửa quả thanh long lên thớt, cắt thành các khối vuông quân cờ kích thước 2 x 2cm đều tăm tắp."},{"buoc":4,"tieu_de":"Ướp lạnh & Bày đĩa","thoi_gian":"1 phút","noi_dung":"Xếp các khối thanh long vào đĩa tráng miệng, để trong ngăn mát tủ lạnh 15 phút trước khi dùng để tăng vị thanh mát giòn ngọt sảng khoái."}]', 'Thanh long ruột đỏ có vị ngọt đậm đà và chứa nhiều chất chống oxy hóa anthocyanin hơn ruột trắng; phối hợp cả hai loại trên đĩa tạo hiệu ứng màu sắc tương phản rực rỡ.', '{"calo":70,"protein":"1.5g","chat_beo":"0.5g","carb":"16g"}', '["Thanh mát giải nhiệt","Nhuận tràng tiêu hóa","Chống oxy hóa","Tráng miệng tươi ngon"]');

